local function new(className, props, parentObject)
    local obj = Instance.new(className)

    for k, v in pairs(props or {}) do
        pcall(function()
            obj[k] = v
        end)
    end

    local parentOK, parentErr = pcall(function()
        obj.Parent = parentObject
    end)
    if not parentOK then
        pcall(function() obj:Destroy() end)
        error("MAWWW UI parent failed: " .. tostring(parentErr), 2)
    end
    return obj
end

local function corner(parentObject, radius)
    return new("UICorner", {
        CornerRadius = UDim.new(0, radius or 10),
    }, parentObject)
end

local function stroke(parentObject, color, thickness, transparency)
    return new("UIStroke", {
        Color = color,
        Thickness = thickness or 1,
        Transparency = transparency or 0,
    }, parentObject)
end

local function tween(object, duration, properties)
    return TweenService:Create(
        object,
        TweenInfo.new(duration, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
        properties
    )
end

