local function __n3k_feature_makeAdapter(ctx)
    local adapter = {}

    local tabPages = {}
    local tabObjects = {}
    local currentTabName = nil

    local function normalizedName(name)
        local s = string.lower(__n3k_feature_safeText(name))
        if s == "information" then return "INFORMATION" end
        if s == "survivor" then return "SURVIVE" end
        if s == "visuals" or s == "visual" then return "VISUAL" end
        if s == "killer" then return "KILLER" end
        if s == "misc" then return "MISC" end
        if s == "config" or s == "save" then return "SAVE" end
        return string.upper(__n3k_feature_safeText(name))
    end

    local function getPage(name)
        local key = normalizedName(name)
        if tabPages[key] then return tabPages[key], key end

        if key == "INFORMATION" and ctx.infoPage then
            tabPages[key] = ctx.infoPage
            return ctx.infoPage, key
        end

        local page = new("ScrollingFrame", {
            Name = "FeaturePage_" .. key:gsub("%W", "_"),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(8, 8),
            Size = UDim2.new(1, -16, 1, -16),
            CanvasSize = UDim2.new(0, 0, 0, 0),
            ScrollBarThickness = 4,
            ScrollBarImageTransparency = 0.35,
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            Visible = false,
            ZIndex = 20,
        }, ctx.page)

        local padding = new("UIPadding", {
            PaddingTop = UDim.new(0, 2),
            PaddingBottom = UDim.new(0, 8),
            PaddingLeft = UDim.new(0, 2),
            PaddingRight = UDim.new(0, 8),
        }, page)

        local layout = new("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            Padding = UDim.new(0, 7),
        }, page)

        tabPages[key] = page
        return page, key
    end

    local function showTab(name)
        local page, key = getPage(name)
        currentTabName = key
        for k, p in pairs(tabPages) do
            p.Visible = (k == key)
        end
        if ctx.pageTitle then
            ctx.pageTitle.Text = key
        end
        if ctx.pageSubtitle then
            ctx.pageSubtitle.Text = "MAWWW HUB • " .. __n3k_feature_safeText(ctx.scriptName)
        end
        if ctx.buttons then
            for buttonName, button in pairs(ctx.buttons) do
                pcall(function()
                    button.BackgroundColor3 =
                        (buttonName == key)
                        and Color3.fromRGB(24, 91, 130)
                        or COLORS.Panel2
                    button.TextColor3 =
                        (buttonName == key)
                        and COLORS.Cyan
                        or COLORS.Text
                end)
            end
        end
        return page
    end

    adapter.__MAWWW_GetSearchPages = function()
        return tabPages
    end
    adapter.__MAWWW_ShowSearchTab = function(name)
        return showTab(name)
    end

    local function makeSection(tabPage, title)
        local box = new("Frame", {
            BackgroundColor3 = COLORS.Panel2,
            BackgroundTransparency = 0.12,
            BorderSizePixel = 0,
            Size = UDim2.new(1, -2, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            LayoutOrder = #tabPage:GetChildren() + 1,
            ZIndex = 21,
        }, tabPage)
        corner(box, 10)
        stroke(box, COLORS.Stroke, 1, 0.55)

        new("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(11, 7),
            Size = UDim2.new(1, -22, 0, 22),
            Font = Enum.Font.GothamBold,
            Text = __n3k_feature_safeText(title),
            TextColor3 = COLORS.Text,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 22,
        }, box)

        local content = new("Frame", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(9, 32),
            Size = UDim2.new(1, -18, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            ZIndex = 22,
        }, box)

        local layout = new("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            SortOrder = Enum.SortOrder.LayoutOrder,
            Padding = UDim.new(0, 5),
        }, content)

        new("UIPadding", {
            PaddingBottom = UDim.new(0, 9),
        }, content)

        pcall(function()
            box:SetAttribute("MAWWW_SearchSection", true)
            box:SetAttribute("MAWWW_SearchSectionTitle", __n3k_feature_safeText(title))
            box:SetAttribute("MAWWW_SearchPage", tostring(tabPage.Name or "FeaturePage"))
        end)

        local section = {}
        section.__configPrefix = tostring(tabPage.Name or "FeaturePage") .. "::" .. tostring(title or "Section")

        local function __n3k_registerSearchControl(holder, titleText, contentText)

            pcall(function()
                holder:SetAttribute("MAWWW_SearchChild", true)
                holder:SetAttribute("MAWWW_FeatureTitle", __n3k_feature_safeText(titleText))
                holder:SetAttribute("MAWWW_FeatureContent", __n3k_feature_safeText(contentText or ""))
            end)
            return holder
        end

        local function __n3k_registerConfigControl(opts, control, getter, setter)
            if not opts or opts.Save == false then return control end
            local env = getgenv()
            env.__MAWWW_ConfigElements = env.__MAWWW_ConfigElements or {}
            env.Elements = env.__MAWWW_ConfigElements
            local Elements = env.__MAWWW_ConfigElements
            local configKey = tostring(opts.ConfigId or opts.Title or "Control")

            configKey = section.__configPrefix .. "::" .. configKey

            Elements[configKey] = {
                Control = control,
                Get = getter,
                Set = setter,
                Title = tostring(opts.Title or "Control"),
                ConfigId = tostring(opts.ConfigId or opts.Title or "Control"),
                Section = tostring(title or "Section"),
                Page = tostring(tabPage.Name or "FeaturePage"),
                StableId = "MAWWW::" .. tostring(opts.ConfigId or opts.Title or "Control"),
            }
            return control
        end

        local function controlHeight(desc)
            return desc and desc ~= "" and 56 or 39
        end

        local function makeControl(titleText, contentText)
            local h = controlHeight(contentText)
            local holder = new("Frame", {
                BackgroundColor3 = COLORS.Panel3,
                BackgroundTransparency = 0.18,
                BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, h),
                ZIndex = 23,
            }, content)
            corner(holder, 8)

            local label = new("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(10, 6),
                Size = UDim2.new(1, -20, 0, 18),
                Font = Enum.Font.GothamSemibold,
                Text = __n3k_feature_safeText(titleText),
                TextColor3 = COLORS.Text,
                TextSize = 9,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 24,
            }, holder)

            local descLabel
            if contentText and contentText ~= "" then
                descLabel = new("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(10, 25),
                    Size = UDim2.new(1, -20, 0, 25),
                    Font = Enum.Font.Gotham,
                    Text = __n3k_feature_safeText(contentText),
                    TextColor3 = COLORS.Muted,
                    TextSize = 8,
                    TextWrapped = true,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 24,
                }, holder)
            end

            __n3k_registerSearchControl(holder, titleText, contentText)
            return holder
        end

        function section:AddToggle(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Toggle", opts.Content)
            local button = new("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(72, 25),
                BackgroundColor3 = COLORS.Panel,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                ZIndex = 25,
            }, holder)
            corner(button, 8)
            stroke(button, COLORS.Stroke, 1, 0.35)

            local state = opts.Default == true
            local function render()
                button.Text = state and "ON" or "OFF"
                button.TextColor3 = state and COLORS.Green or COLORS.Muted
                button.BackgroundColor3 = state
                    and Color3.fromRGB(20, 65, 52)
                    or COLORS.Panel
            end
            render()

            local function fire()
                pcall(function()
                    if type(opts.Callback) == "function" then opts.Callback(state) end
                end)
            end

            local function setToggleState(v, silent)
                state = (v == true)
                render()
                if not silent then fire() end
            end

            button.Activated:Connect(function()
                setToggleState(not state, false)
            end)

            local control = __n3k_registerConfigControl(opts, button,
                function() return state end,
                setToggleState)
            local syncRegistry = getgenv().__MAWWW_ToggleStateSync
            if type(syncRegistry) ~= "table" then
                syncRegistry = {}
                getgenv().__MAWWW_ToggleStateSync = syncRegistry
            end
            syncRegistry[control] = {
                Set = setToggleState,
                Get = function() return state end,
            }
            return control
        end

        function section:AddButton(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Button", opts.Content)
            local button = new("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(100, 25),
                BackgroundColor3 = COLORS.Blue,
                BorderSizePixel = 0,
                Text = "RUN",
                Font = Enum.Font.GothamBold,
                TextSize = 8,
                TextColor3 = COLORS.Text,
                AutoButtonColor = false,
                ZIndex = 25,
            }, holder)
            corner(button, 8)
            button.Activated:Connect(function()
                pcall(function()
                    if type(opts.Callback) == "function" then
                        opts.Callback()
                    end
                end)
            end)
            return button
        end

        function section:AddSlider(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Slider", opts.Content)
            local minV = tonumber(opts.Min) or 0
            local maxV = tonumber(opts.Max) or 100
            if maxV < minV then minV, maxV = maxV, minV end
            local value = tonumber(opts.Default)
            if value == nil then value = minV end
            value = math.clamp(value, minV, maxV)

            local input = new("TextBox", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(92, 25),
                BackgroundColor3 = COLORS.Panel,
                BorderSizePixel = 0,
                ClearTextOnFocus = false,
                Font = Enum.Font.GothamBold,
                Text = tostring(value),
                TextColor3 = COLORS.Cyan,
                TextSize = 9,
                TextXAlignment = Enum.TextXAlignment.Center,
                ZIndex = 25,
            }, holder)
            corner(input, 8)
            stroke(input, COLORS.Stroke, 1, 0.35)

            local function apply()
                local n = tonumber(input.Text)
                if n == nil then
                    input.Text = tostring(value)
                    return
                end
                n = math.clamp(n, minV, maxV)
                local inc = tonumber(opts.Increment)
                if inc and inc > 0 then
                    n = math.floor((n - minV) / inc + 0.5) * inc + minV
                    n = math.clamp(n, minV, maxV)
                end
                value = n
                input.Text = tostring(n)
                pcall(function()
                    if type(opts.Callback) == "function" then
                        opts.Callback(n)
                    end
                end)
            end
            input.FocusLost:Connect(apply)
            return __n3k_registerConfigControl(opts, input,
                function() return value end,
                function(v, silent)
                    local n = tonumber(v)
                    if n == nil then return end
                    n = math.clamp(n, minV, maxV)
                    value = n
                    input.Text = tostring(n)
                    if not silent then
                        pcall(function() if type(opts.Callback) == "function" then opts.Callback(n) end end)
                    end
                end)
        end

        function section:AddDropdown(opts)
            opts = opts or {}
            local dropdownApis = getgenv().__MAWWW_DropdownAPIs
            if type(dropdownApis) ~= "table" then
                dropdownApis = {}
                getgenv().__MAWWW_DropdownAPIs = dropdownApis
            end
            local holder = makeControl(opts.Title or "Dropdown", opts.Content)
            local options = opts.Options or {}
            local index = 1
            local defaultValue = opts.Default
            if type(defaultValue) == "table" then defaultValue = defaultValue[1] end
            for i, option in ipairs(options) do
                if tostring(option) == tostring(defaultValue) then
                    index = i
                    break
                end
            end

            local button = new("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(120, 25),
                BackgroundColor3 = COLORS.Panel,
                BorderSizePixel = 0,
                Font = Enum.Font.GothamBold,
                TextSize = 8,
                TextColor3 = COLORS.Cyan,
                AutoButtonColor = false,
                ZIndex = 25,
            }, holder)
            corner(button, 8)
            stroke(button, COLORS.Stroke, 1, 0.35)

            local function current()
                return options[index]
            end
            local function render()
                button.Text = tostring(current() or "None")
            end
            render()

            local function fire()
                pcall(function()
                    if type(opts.Callback) == "function" then opts.Callback(current()) end
                end)
            end

            button.Activated:Connect(function()
                if #options == 0 then return end
                index = (index % #options) + 1
                render()
                fire()
            end)

            dropdownApis[button] = {
                SetValues = function(newOptions, selected, silent)
                    options = type(newOptions) == "table" and newOptions or {}
                    index = 1
                    if selected ~= nil then
                        for i, option in ipairs(options) do
                            if tostring(option) == tostring(selected) then index = i; break end
                        end
                    end
                    render()
                    if not silent then fire() end
                end,
                GetValues = function() return options end,
            }

            return __n3k_registerConfigControl(opts, button,
                function() return current() end,
                function(v, silent)
                    for i, option in ipairs(options) do
                        if tostring(option) == tostring(v) then
                            index = i
                            render()
                            if not silent then fire() end
                            return
                        end
                    end
                end)
        end

        function section:AddInput(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Input", opts.Content)
            local input = new("TextBox", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(145, 25),
                BackgroundColor3 = COLORS.Panel,
                BorderSizePixel = 0,
                ClearTextOnFocus = false,
                Font = Enum.Font.Gotham,
                PlaceholderText = __n3k_feature_safeText(opts.Placeholder),
                Text = __n3k_feature_safeText(opts.Default),
                TextColor3 = COLORS.Text,
                TextSize = 8,
                ZIndex = 25,
            }, holder)
            corner(input, 8)
            stroke(input, COLORS.Stroke, 1, 0.35)
            local function fire()
                pcall(function()
                    if type(opts.Callback) == "function" then opts.Callback(input.Text) end
                end)
            end
            input.FocusLost:Connect(fire)
            return __n3k_registerConfigControl(opts, input,
                function() return input.Text end,
                function(v, silent)
                    input.Text = __n3k_feature_safeText(v)
                    if not silent then fire() end
                end)
        end

        function section:AddKeybind(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Keybind", opts.Content)
            local button = new("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(92, 25),
                BackgroundColor3 = COLORS.Panel,
                BorderSizePixel = 0,
                Text = __n3k_feature_safeText(opts.Default or "None"),
                Font = Enum.Font.GothamBold,
                TextSize = 8,
                TextColor3 = COLORS.Cyan,
                AutoButtonColor = false,
                ZIndex = 25,
            }, holder)
            corner(button, 8)
            stroke(button, COLORS.Stroke, 1, 0.35)
            return button
        end

        function section:AddColorPicker(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Color", opts.Content)
            local color = opts.Default
            local button = new("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(92, 25),
                BackgroundColor3 = (typeof(color) == "Color3" and color) or COLORS.Blue,
                BorderSizePixel = 0,
                Text = "COLOR",
                Font = Enum.Font.GothamBold,
                TextSize = 8,
                TextColor3 = COLORS.Text,
                AutoButtonColor = false,
                ZIndex = 25,
            }, holder)
            corner(button, 8)
            button.Activated:Connect(function()

                local palette = {
                    Color3.fromRGB(255,255,255),
                    Color3.fromRGB(255,90,90),
                    Color3.fromRGB(90,180,255),
                    Color3.fromRGB(110,255,160),
                    Color3.fromRGB(190,110,255),
                }
                local current = button.BackgroundColor3
                local nextIndex = 1
                for i, c in ipairs(palette) do
                    if math.abs(c.R - current.R) < 0.01
                        and math.abs(c.G - current.G) < 0.01
                        and math.abs(c.B - current.B) < 0.01 then
                        nextIndex = (i % #palette) + 1
                        break
                    end
                end
                button.BackgroundColor3 = palette[nextIndex]
                pcall(function()
                    if type(opts.Callback) == "function" then opts.Callback(button.BackgroundColor3) end
                end)
            end)

            return __n3k_registerConfigControl(opts, button,
                function() return button.BackgroundColor3 end,
                function(v, silent)
                    if typeof(v) ~= "Color3" then return end
                    button.BackgroundColor3 = v
                    if not silent then
                        pcall(function() if type(opts.Callback) == "function" then opts.Callback(v) end end)
                    end
                end)
        end

        function section:AddParagraph(opts)
            opts = opts or {}
            local holder = makeControl(opts.Title or "Info", opts.Content or opts.Description)
            return holder
        end

        return section
    end

    function adapter:Window(opts)
        opts = opts or {}
        local window = {}

        function window:InfoTab(_)
            return getPage("INFORMATION")
        end

        function window:AddTab(opts2)
            opts2 = opts2 or {}
            local name = opts2.Name or "Tab"
            local page = getPage(name)
            local key = normalizedName(name)
            local tab = {}
            tab.Name = key

            function tab:AddSection(title)
                return makeSection(page, title)
            end

            tabObjects[key] = tab
            showTab(key)
            return tab
        end

        return window
    end

    function adapter:MakeNotify(opts)
        opts = opts or {}
        __n3k_feature_notify(ctx.featureGui, opts.Title, opts.Content, opts.Delay or 2)
    end

    return adapter
end

local function __MAWWW_START()
    getgenv().VD = getgenv().VD or {}
    local W = getgenv()

    VD.AutoCrouch           = false
    VD.KILLER_AutoAttack         = VD.KILLER_AutoAttack or false
    VD.KILLER_AutoAttackRange    = VD.KILLER_AutoAttackRange or 12
    VD.KILLER_AutoAttackCooldown = VD.KILLER_AutoAttackCooldown or 0.15
    VD.SURV_AutoFlee        = VD.SURV_AutoFlee or false
    VD.SURV_AutoFleeDist    = VD.SURV_AutoFleeDist or 40
    VD.SURV_AutoFleeCooldown= VD.SURV_AutoFleeCooldown or 1.5

    VD.VeilEnabled          = VD.VeilEnabled or false
    VD.VeilShowFOV          = VD.VeilShowFOV ~= false
    VD.VeilShowTracker      = VD.VeilShowTracker or false
    VD.VeilAutoPredict      = VD.VeilAutoPredict ~= false
    VD.VeilFOV              = VD.VeilFOV or 150
    VD.VeilMaxDist          = 350
    VD.VeilSpearSpeed       = VD.VeilSpearSpeed or 165
    VD.VeilGravity          = VD.VeilGravity or 103
    VD.VeilAuraSpearSpeed   = VD.VeilAuraSpearSpeed or 165
    VD.VeilAuraSpearGravity = VD.VeilAuraSpearGravity or 96
    VD.VeilLeadMultiplier   = VD.VeilLeadMultiplier or 1.4

    -- Retire an older V2 runtime cleanly, then restore the saved V2 preference.
    -- V1 and V2 are mutually exclusive; V1 wins if both were saved ON.
    local requestedVeilV2Enabled = VD.VeilV2Enabled == true
    VD.VeilV3Enabled = false
    VD.VeilV3EngineEnabled = false
    do
        local innerW = type(W.W) == "table" and W.W or nil
        local oldV2 = W.MAWWW_VeilV2_API
            or (innerW and innerW.MAWWW_VeilV2_API)
            or W.N3K0P01_VeilV2_API
            or (innerW and innerW.N3K0P01_VeilV2_API)
        if oldV2 and type(oldV2.cleanup) == "function" then
            pcall(function() oldV2.cleanup() end)
        elseif oldV2 and type(oldV2.setEnabled) == "function" then
            pcall(function() oldV2.setEnabled(false) end)
        end
        local oldV3 = W.MAWWW_VeilV3_API
        if oldV3 and type(oldV3.setEnabled) == "function" then
            pcall(function() oldV3.setEnabled(false) end)
        end
        local oldEngine = W.MAWWW_VeilV3Engine
        if oldEngine and type(oldEngine.Cleanup) == "function" then
            pcall(function() oldEngine.Cleanup() end)
        end
        W.MAWWW_VeilV2_API = nil
        W.N3K0P01_VeilV2_API = nil
        if innerW then
            innerW.MAWWW_VeilV2_API = nil
            innerW.N3K0P01_VeilV2_API = nil
        end
        W.MAWWW_VeilV3_API = nil
        W.MAWWW_VeilV3Engine = nil
    end
    VD.VeilV2Enabled = requestedVeilV2Enabled and VD.VeilEnabled ~= true

    VD.SilentPistolV3Enabled  = VD.SilentPistolV3Enabled == true
    VD.TOFV3_TargetMode       = VD.TOFV3_TargetMode or "Killer"
    VD.TOFV3_FOV              = tonumber(VD.TOFV3_FOV) or 150
    VD.TOFV3_MaxDist          = tonumber(VD.TOFV3_MaxDist) or 300
    VD.TOFV3_ShowFOV          = VD.TOFV3_ShowFOV ~= false
    VD.TOFV3_ShowLaser        = VD.TOFV3_ShowLaser ~= false
    VD.TOFV3_WallCheck         = VD.TOFV3_WallCheck == true
    VD.TOFV3_BlockKnocked      = VD.TOFV3_BlockKnocked ~= false
    VD.TOFV3_AutoPredict       = VD.TOFV3_AutoPredict ~= false
    VD.TOFV3_PingLead          = tonumber(VD.TOFV3_PingLead) or 1.0

    -- Independent Silent Pistol/TOF engines: V1 keeps the prior main-file behavior; V2 is ported from vd.lua.
    VD.TOFV1_SilentAim  = VD.SilentPistolV2Enabled ~= true and (VD.TOFV1_SilentAim == true or VD.TOF_SilentAim == true)
    VD.TOFV1_TargetMode = VD.TOFV1_TargetMode or VD.TOF_TargetMode or "Killer"
    VD.TOFV1_Key        = VD.TOFV1_Key or VD.TOF_Key or "Q"
    if VD.TOFV1_Laser == nil then VD.TOFV1_Laser = VD.TOF_Laser == true end
    VD.TOFV1_WallCheck  = VD.TOFV1_WallCheck ~= false
    VD.TOFV1_BlockKnocked = VD.TOFV1_BlockKnocked ~= false
    VD.TOFV1_LockAim    = VD.TOFV1_LockAim == true

    VD.SilentPistolV2Enabled = VD.SilentPistolV2Enabled == true
    VD.TOFV2_TargetMode = VD.TOFV2_TargetMode or "Killer"
    VD.TOFV2_Key = VD.TOFV2_Key or "P"
    VD.TOFV2_Predict = VD.TOFV2_Predict == true
    -- Match the reference Silent Pistol defaults while preserving an explicit saved false.
    VD.TOFV2_BlockKnocked = VD.TOFV2_BlockKnocked ~= false
    VD.TOFV2_LockAim = VD.TOFV2_LockAim == true
    VD.TOFV2_WallCheck = VD.TOFV2_WallCheck ~= false
    VD.TOFV2_Laser = VD.TOFV2_Laser ~= false
    VD.TOFV2_ProjectileSpeed = tonumber(VD.TOFV2_ProjectileSpeed) or 500
    VD.TOFV2_PredictionEfficiency = tonumber(VD.TOFV2_PredictionEfficiency) or 0.85
    -- Internal compatibility defaults; the existing V2 panel remains unchanged.
    VD.TOFV2_TargetPart = VD.TOFV2_TargetPart or VD.AIM_TargetPart or "Torso"
    VD.TOFV2_AimOffset = tonumber(VD.TOFV2_AimOffset)
    if VD.TOFV2_AimOffset == nil then VD.TOFV2_AimOffset = -1 end

    VD.Invis_Enabled       = VD.Invis_Enabled       or false
    VD.Invis_ShowFloatBtn  = VD.Invis_ShowFloatBtn  or false
    VD.Invis_Hotkey        = VD.Invis_Hotkey        or "G"

    VD.KILLER_BypassLeap     = VD.KILLER_BypassLeap     or false
    VD.KILLER_InfGrab        = VD.KILLER_InfGrab        or false
    VD.KILLER_InfLakeMist    = VD.KILLER_InfLakeMist    or false
    VD.KILLER_InfPursuit     = VD.KILLER_InfPursuit     or false
    VD.KILLER_BypassCooldown = VD.KILLER_BypassCooldown or false
    VD.KILLER_InfFrenzy      = VD.KILLER_InfFrenzy      or false
    VD.KILLER_AntiBlind      = VD.KILLER_AntiBlind      or false
    VD.KILLER_DestroyPallets = VD.KILLER_DestroyPallets or false
    VD.KILLER_InfLunge       = VD.KILLER_InfLunge       or false
    VD.KILLER_AutoHook       = VD.KILLER_AutoHook       or false

    VD.KA_AutoStalk       = VD.KA_AutoStalk       or false
    VD.KA_AutoStalkRange  = VD.KA_AutoStalkRange  or 150
    VD.KA_AutoKillAll     = VD.KA_AutoKillAll     or false
    VD.KA_DropAllPallet   = VD.KA_DropAllPallet   or false
    VD.KA_BlockAllVault   = VD.KA_BlockAllVault   or false

    VD.SURV_FakeParry           = VD.SURV_FakeParry           or false
    VD.SURV_FakeParryAnim       = VD.SURV_FakeParryAnim       or "Enten"
    VD.SURV_FakeParryCooldown   = VD.SURV_FakeParryCooldown   or 0.4
    VD.SURV_FakeParryKey        = VD.SURV_FakeParryKey        or "V"
    VD.SURV_FakeParryShowBtn    = VD.SURV_FakeParryShowBtn    or false
    VD.SURV_FakeParryLocked     = VD.SURV_FakeParryLocked     or false

    VD.NoFallDamage         = VD.NoFallDamage or false
    VD.NextMapPredict       = VD.NextMapPredict or false
    VD.ManualGen            = VD.ManualGen or false
    VD.AutoGen              = VD.AutoGen or false
    VD.KillerEscapeDist     = VD.KillerEscapeDist or 30

    VD.Wisnu_IgnoredSkills   = VD.Wisnu_IgnoredSkills   or {}


    VD.AF_Enabled          = VD.AF_Enabled or false
    VD.AF_Mode             = VD.AF_Mode or "Auto"
    VD.AF_AutoReady        = VD.AF_AutoReady ~= false
    VD.AF_AutoRequeue      = VD.AF_AutoRequeue ~= false
    VD.AF_AutoEscapeNow    = VD.AF_AutoEscapeNow ~= false
    VD.AF_AutoHeal         = VD.AF_AutoHeal ~= false
    VD.AF_AutoAttack       = VD.AF_AutoAttack ~= false
    VD.AF_AutoHook         = VD.AF_AutoHook ~= false

    VD.KillerPerksDisplay   = VD.KillerPerksDisplay   or false
    VD.SpeedBoostEnabled    = VD.SpeedBoostEnabled    or false
    VD.SpeedBoostValue      = VD.SpeedBoostValue      or 30
    VD.CursorEnabled        = VD.CursorEnabled        or false

    W.InstantHealSelf = W.InstantHealSelf or false
    W.AutoHealAll     = W.AutoHealAll or false

    _G.GLUTO_ACCENT     = Color3.fromRGB(120, 120, 120)
    _G.GLUTO_ACCENT_BG  = Color3.fromRGB(0, 0, 0)
    _G.GLUTO_NEUTRAL    = Color3.fromRGB(90, 90, 90)
    _G.GLUTO_STROKE_OFF = Color3.fromRGB(25, 25, 25)
    _G.GLUTO_BG_OFF     = Color3.fromRGB(0, 0, 0)

    local function __Gluto_Init_Main__()

        local Players           = game:GetService("Players")
        local RunService        = game:GetService("RunService")
        local UserInputService  = game:GetService("UserInputService")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local Workspace         = game:GetService("Workspace")
        local CoreGui           = game:GetService("CoreGui")
        local CollectionService = game:GetService("CollectionService")
        local TweenService      = game:GetService("TweenService")
        local GuiService        = game:GetService("GuiService")
        local HttpService       = game:GetService("HttpService")
        local Lighting          = game:GetService("Lighting")

        local LocalPlayer = Players.LocalPlayer
        local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
        local VirtualInputManager = nil
        pcall(function() VirtualInputManager = game:GetService("VirtualInputManager") end)

        -- Auto Parry V1 settings are kept in the existing VD config table.
        local APV1Config = getgenv().VD or {}
        APV1Config.AutoParryV1 = APV1Config.AutoParryV1 == true
        APV1Config.AutoParryV1Safety = APV1Config.AutoParryV1Safety == true
        APV1Config.AutoParryV1Aggressive = APV1Config.AutoParryV1Aggressive == true
        APV1Config.AutoParryV1Circle = APV1Config.AutoParryV1Circle ~= false
        APV1Config.AutoParryV1KillerTriangle = APV1Config.AutoParryV1KillerTriangle ~= false
        APV1Config.AutoParryV1Radius = tonumber(APV1Config.AutoParryV1Radius) or 15
        APV1Config.AutoParryV1Face = tonumber(APV1Config.AutoParryV1Face) or 0.7
        APV1Config.AutoParryV1FaceEnabled = APV1Config.AutoParryV1FaceEnabled ~= false
        APV1Config.AutoParryV1IgnoredSkills = type(APV1Config.AutoParryV1IgnoredSkills) == "table" and APV1Config.AutoParryV1IgnoredSkills or {}

        -- Auto Parry V3 now uses a dedicated  engine with settings independent from V1/V2.
        local APV3 = { Config = getgenv().VD or {} }
        APV3.Config.AutoParryV3 = APV3.Config.AutoParryV3 == true
        APV3.Config.AutoParryV3Safety = APV3.Config.AutoParryV3Safety ~= false
        APV3.Config.AutoParryV3Radius = math.clamp(tonumber(APV3.Config.AutoParryV3Radius) or 15, 5, 25)
        APV3.Config.AutoParryV3Face = math.clamp(tonumber(APV3.Config.AutoParryV3Face) or 0.85, -1, 1)
        APV3.Config.AutoParryV3Circle = APV3.Config.AutoParryV3Circle ~= false
        APV3.Config.AutoParryV3IgnoredSkills = type(APV3.Config.AutoParryV3IgnoredSkills) == "table" and APV3.Config.AutoParryV3IgnoredSkills or {}
        APV3.Config.AutoParryV3IgnoreHiddenS1 = APV3.Config.AutoParryV3IgnoreHiddenS1 == true or APV3.Config.AutoParryV3IgnoredSkills["Hidden S1"] == true
        APV3.Config.AutoParryV3IgnoreAbyssalS1 = APV3.Config.AutoParryV3IgnoreAbyssalS1 == true or APV3.Config.AutoParryV3IgnoredSkills["Abyssal S1"] == true
        if APV3.Config.AutoParryV3IgnoreHiddenS1 then APV3.Config.AutoParryV3IgnoredSkills["Hidden S1"] = true end
        if APV3.Config.AutoParryV3IgnoreAbyssalS1 then APV3.Config.AutoParryV3IgnoredSkills["Abyssal S1"] = true end
        APV3.Config.AutoParryV3Aggressive = APV3.Config.AutoParryV3Aggressive == true
        APV3.Config.AutoParryV3GuiVisible = APV3.Config.AutoParryV3GuiVisible == true

        local UILib = __MAWWW_UI_ADAPTER
        if not UILib then
            warn("[MAWWW] Feature UI adapter tidak tersedia.")
            return
        end


        -- Auto Parry V2 engine ported from OXio Hub source.
        -- Kept separate from the existing Auto Parry V1 implementation.
        -- Auto Parry V3 is replaced below by the uploaded  V2-derived engine.
        local localPlayer = LocalPlayer
        local playerGui = localPlayer:WaitForChild("PlayerGui")
        local ox = _G.Ox or {}
        _G.Ox = ox

        ox.ParryV2 = ox.ParryV2 or {
            Enabled = false, SafetyParry = false, Mode = "Legit", Trigger = "Remote",
