                if not inst then return end
                if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
                    local txt = inst.Text
                    if txt and (string.find(txt, "Close Windows", 1, true) or string.find(txt, "Close Windows", 1, true)) then
                        pcall(function()
