        local function APV1_IsSafeToParry(character)
            if not APV1Config.AutoParryV1Safety then return true end
            if not character then return false end
            local check = character:FindFirstChild("CheckInterractable")
            if not check then return true end
            for _, attr in ipairs({ "isVaulting", "isRepairing", "isUnhooking", "isHealing", "isSliding" }) do
                if check:GetAttribute(attr) == true then return false end
            end
            return true
        end

        local function APV1_IsInKillerPOV(killerRoot, survivorRoot, threshold)
            if not killerRoot or not survivorRoot then return false end
            local delta = survivorRoot.Position - killerRoot.Position
            local flatDelta = Vector3.new(delta.X, 0, delta.Z)
            if flatDelta.Magnitude < 0.15 then return true end
            local look = Vector3.new(killerRoot.CFrame.LookVector.X, 0, killerRoot.CFrame.LookVector.Z)
            if look.Magnitude < 0.05 then return false end
            return look.Unit:Dot(flatDelta.Unit) >= (threshold or 0.35)
        end

        -- Geometry copied from APR's Killer POV triangle, kept inside the V1 engine.
        -- The triangle's half-width follows the existing Face Sensitivity setting so
        -- the visual guide and the V1 facing check stay aligned.
        local function APV1_GetKillerTriangleHalfWidth(length)
            local threshold = tonumber(APV1Config.AutoParryV1Face) or 0.7
            if threshold < 0.2 then threshold = 0.35 end
            threshold = math.clamp(threshold, 0.2, 0.99)
            local factor = math.sqrt(math.max(0, 1 - threshold * threshold)) / threshold
            factor = math.clamp(factor, 0.1, 3.0)
            return length * factor
        end

        local function APV1_IsInsideKillerTriangle(killerRoot, survivorRoot, length, halfWidth)
            if not killerRoot or not survivorRoot or not killerRoot.Parent or not survivorRoot.Parent then
                return false
            end
            local L = tonumber(length) or math.clamp(tonumber(APV1Config.AutoParryV1Radius) or 15, 5, 25)
            local W = tonumber(halfWidth) or APV1_GetKillerTriangleHalfWidth(L)
            if L <= 0 or W <= 0 then return false end

            local look = killerRoot.CFrame.LookVector
            local flatLook = Vector3.new(look.X, 0, look.Z)
            if flatLook.Magnitude < 0.001 then return false end
            flatLook = flatLook.Unit

            local delta = survivorRoot.Position - killerRoot.Position
            local flatDelta = Vector3.new(delta.X, 0, delta.Z)
            local localZ = flatDelta:Dot(flatLook)
            local right = Vector3.new(flatLook.Z, 0, -flatLook.X)
            local localX = flatDelta:Dot(right)
            if localZ < 0 or localZ > L then return false end
            local maxX = (localZ / L) * W
            return math.abs(localX) <= maxX
        end

        local function APV1_FaceCheckOk(killerRoot, survivorRoot)
            -- Keep Auto Parry V1's original detection path unchanged. The triangle is
            -- a visual guide only; its rendered length must not block parries that
            -- the existing V1 trigger window intentionally allows outside the radius.
            if not APV1Config.AutoParryV1FaceEnabled then return true end
            local threshold = tonumber(APV1Config.AutoParryV1Face) or 0.7
            if threshold < 0.2 then threshold = 0.35 end
            return APV1_IsInKillerPOV(killerRoot, survivorRoot, threshold)
        end

        local function APV1_TapMobileParryButton()
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if not playerGui then return end
            local survivorMob = playerGui:FindFirstChild("Survivor-mob")
            local controls = survivorMob and survivorMob:FindFirstChild("Controls")
            local guiMob = controls and controls:FindFirstChild("Gui-mob")

            if guiMob and guiMob.Visible and type(firesignal) == "function" then
                pcall(function()
                    firesignal(guiMob.MouseButton1Down)
                    task.wait(0.01)
                    firesignal(guiMob.MouseButton1Up)
                end)
                return
            end

            pcall(function()
                if type(mouse2click) == "function" then
                    mouse2click()
                elseif type(mouse2press) == "function" and type(mouse2release) == "function" then
                    mouse2press()
                    task.wait(0.01)
                    mouse2release()
                elseif VirtualInputManager then
                    VirtualInputManager:SendMouseButtonEvent(0, 0, 1, true, game, 0)
                    task.wait(0.01)
                    VirtualInputManager:SendMouseButtonEvent(0, 0, 1, false, game, 0)
                end
            end)
        end

        local function APV1_ExecuteParry()
            if APV1State.Cooldown then return end
            local remotes = ReplicatedStorage:FindFirstChild("Remotes")
            local items = remotes and remotes:FindFirstChild("Items")
            local dagger = items and items:FindFirstChild("Parrying Dagger")
            local parryRemote = dagger and dagger:FindFirstChild("parry")
            if parryRemote and parryRemote:IsA("RemoteEvent") then
                for _ = 1, 8 do
                    pcall(function() parryRemote:FireServer() end)
                end
            end
            task.spawn(APV1_TapMobileParryButton)
        end

        -- Initialize the standalone Auto Parry V3 engine and keep V1/V2 config independent.
        local VD = APV3.Config
        local APV3Env = (type(getgenv) == "function" and getgenv()) or _G

        -- Shut down prior V3 engines/connections from earlier executions before installing this one.
        if type(APV3Env.MAWWW_AutoParryV3Shutdown) == "function" then
            pcall(APV3Env.MAWWW_AutoParryV3Shutdown)
        end
        local oldAPV3SourceConnections = APV3Env.__MAWWW_APV3SourceConnections
        if type(oldAPV3SourceConnections) == "table" then
            for _, oldConnection in ipairs(oldAPV3SourceConnections) do
                pcall(function() oldConnection:Disconnect() end)
            end
        end
        APV3Env.__MAWWW_APV3SourceConnections = {}
        if APV3Env.__MAWWW_APV3StateSyncConnection then
            pcall(function() APV3Env.__MAWWW_APV3StateSyncConnection:Disconnect() end)
            APV3Env.__MAWWW_APV3StateSyncConnection = nil
        end

        -- Migrate saved settings from the previous V3 engine to the source engine's keys.
        if VD._AP3_Enabled == nil then VD._AP3_Enabled = VD.AutoParryV3 == true end
        if VD._AP3_Range == nil then VD._AP3_Range = tonumber(VD.AutoParryV3Radius) or 15 end
        if VD._AP3_Aggressive == nil then VD._AP3_Aggressive = VD.AutoParryV3Aggressive == true end
        if VD._AP3_Safety == nil then VD._AP3_Safety = VD.AutoParryV3Safety == true end
        if VD._AP3_FacingEnabled == nil then VD._AP3_FacingEnabled = VD.AutoParryV3IgnoreFacing ~= true end
        if VD._AP3_Facing == nil then VD._AP3_Facing = tonumber(VD.AutoParryV3Face) or 0.7 end
        if VD._AP3_ShowCircle == nil then VD._AP3_ShowCircle = VD.AutoParryV3Circle ~= false end
        if type(VD._AP3_IgnoreSkills) ~= "table" then
            VD._AP3_IgnoreSkills = type(VD.AutoParryV3IgnoredSkills) == "table" and VD.AutoParryV3IgnoredSkills or {}
        end
        -- Normalize either map-style or array-style saved ignore lists for the new toggles.
        do
            local normalizedIgnoreSkills = {}
            for key, value in pairs(VD._AP3_IgnoreSkills) do
                if type(key) == "string" and value == true then
                    normalizedIgnoreSkills[key] = true
                elseif type(value) == "string" then
                    normalizedIgnoreSkills[value] = true
                end
            end
            VD._AP3_IgnoreSkills = normalizedIgnoreSkills
        end
        if VD.AutoParryV3IgnoreHiddenS1 == true then VD._AP3_IgnoreSkills["Hidden S1"] = true end
        if VD.AutoParryV3IgnoreAbyssalS1 == true then VD._AP3_IgnoreSkills["Abyssal S1"] = true end
        VD._AP3_Range = math.clamp(tonumber(VD._AP3_Range) or 15, 5, 30)
        VD._AP3_Facing = math.clamp(tonumber(VD._AP3_Facing) or 0.7, -1, 1)

-- ===== MAWWW HUB · AUTO PARRY V3 ( V2 ENGINE PORT) =====
-- This is a separately namespaced  V2-derived engine. Existing V1/V2/V4+ code is left intact.
do
    local env = (type(getgenv) == "function" and getgenv()) or _G
    local AP3Players = game:GetService("Players")
    local AP3RunService = game:GetService("RunService")
    local AP3ReplicatedStorage = game:GetService("ReplicatedStorage")
    local AP3GuiService = game:GetService("GuiService")
    local AP3LocalPlayer = AP3Players.LocalPlayer
    local AP3State = {
        Alive = true,
        LastScan = 0,
        LastParry = 0,
        CooldownUntil = 0,
        PendingResultUntil = 0,
        CooldownConnection = nil,
        ProcessedTracks = setmetatable({}, { __mode = "k" }),
        AttachedAnimators = setmetatable({}, { __mode = "k" }),
        EventConnections = {},
        LastSensorRefresh = 0,
        ParryRemote = nil,
        LastRemoteLookup = 0,
        Circle = nil,
        Connection = nil,
    }

    local AP3Animations = {
        ["122812055447896"] = "Veil lunge",
        ["133963973694098"] = "Mayers Basic",
        ["117042998468241"] = "Mayers lunge",
        ["135002183282873"] = "cure lunge",
        ["121216847022485"] = "cure Basic",
        ["132817836308238"] = "Jeff Basic",
        ["129784271201071"] = "Jeff lunge",
        ["82666958311998"] = "Jeff Frenzy",
        ["78432063483146"] = "Abyssal Basic",
        ["118907603246885"] = "Abyssal lunge",
        ["139369275981139"] = "Jason Basic",
        ["110355011987939"] = "Jason lunge",
        ["111920872708571"] = "Masked Basic",
        ["105374834496520"] = "Masked lunge",
        ["138720291317243"] = "Masked Tony",
        ["106871536134254"] = "Masked Alex",
        ["130593238885843"] = "Masked Cobra",
        ["115244153053858"] = "Masked Cobra lunge",
        ["74968262036854"] = "Hidden Basic",
        ["113255068724446"] = "Hidden lunge",
        ["98163597193511"] = "Hidden S1",
        ["80411309607666"] = "Abyssal S1",
    }

    local function AP3GetParryRemote()
        local cached = AP3State.ParryRemote
        if cached and cached.Parent then return cached end
        local now = os.clock()
        if now - (AP3State.LastRemoteLookup or 0) < 0.25 then return nil end
        AP3State.LastRemoteLookup = now

        local function isParryRemote(instance)
            return instance ~= nil
                and string.lower(instance.Name or "") == "parry"
                and (instance:IsA("RemoteEvent") or instance:IsA("RemoteFunction"))
        end

        local remotes = AP3ReplicatedStorage:FindFirstChild("Remotes")
        local items = remotes and remotes:FindFirstChild("Items")
        local dagger = items and (items:FindFirstChild("Parrying Dagger")
            or items:FindFirstChild("Parry Dagger") or items:FindFirstChild("ParryingDagger"))
        local remote = dagger and dagger:FindFirstChild("parry")
        if isParryRemote(remote) then
            AP3State.ParryRemote = remote
            return remote
        end

        -- Some versions nest the actual remote inside the item folder.
        if dagger then
            for _, descendant in ipairs(dagger:GetDescendants()) do
                if isParryRemote(descendant) then
                    AP3State.ParryRemote = descendant
                    return descendant
                end
            end
        end

        -- Fallback is used only when the canonical item remote is absent.
        for _, descendant in ipairs(AP3ReplicatedStorage:GetDescendants()) do
            if isParryRemote(descendant) then
                AP3State.ParryRemote = descendant
                return descendant
            end
        end
        return nil
    end

    local function AP3AttachCooldownListener()
        if AP3State.CooldownConnection then
            local alive = false
            pcall(function() alive = AP3State.CooldownConnection.Connected end)
            if alive then return end
            AP3State.CooldownConnection = nil
        end

        local function findResultRemote()
            local remotes = AP3ReplicatedStorage:FindFirstChild("Remotes")
            local items = remotes and remotes:FindFirstChild("Items")
            local dagger = items and (items:FindFirstChild("Parrying Dagger")
                or items:FindFirstChild("Parry Dagger") or items:FindFirstChild("ParryingDagger"))
            local result = dagger and (dagger:FindFirstChild("parryResult") or dagger:FindFirstChild("ParryResult"))
            if result and result:IsA("RemoteEvent") then return result end
            if dagger then
                for _, descendant in ipairs(dagger:GetDescendants()) do
                    if string.lower(descendant.Name or "") == "parryresult" and descendant:IsA("RemoteEvent") then
                        return descendant
                    end
                end
            end
            return nil
        end

        local resultRemote = findResultRemote()
        if resultRemote then
            AP3State.CooldownConnection = resultRemote.OnClientEvent:Connect(function(result, durationArg)
                if (AP3State.PendingResultUntil or 0) <= 0 then return end
                local now = os.clock()
                local cooldown = tonumber(durationArg)
                if cooldown and cooldown > 5 then cooldown = cooldown / 100 end
                if not cooldown or cooldown <= 0 then
                    cooldown = (result == true) and 0.9 or 0.6
                end
                cooldown = math.clamp(cooldown, 0.1, 2)
                AP3State.CooldownUntil = now + cooldown
                AP3State.PendingResultUntil = 0
            end)
        end
    end

    local function AP3IsKiller(player)
        if not player or player == AP3LocalPlayer then return false end
        if player:GetAttribute("Role") == "Killer" or player:GetAttribute("IsKiller") == true then return true end
        local character = player.Character
        if character and (character:GetAttribute("Role") == "Killer" or character:GetAttribute("IsKiller") == true) then
            return true
        end
        local teamName = player.Team and string.lower(player.Team.Name or "") or ""
        return string.find(teamName, "killer", 1, true) ~= nil
            or string.find(teamName, "slasher", 1, true) ~= nil
            or string.find(teamName, "hunter", 1, true) ~= nil
            or string.find(teamName, "monster", 1, true) ~= nil
    end

    local function AP3IsBlocked(character)
        if not character or not character.Parent then return true end
        local alwaysBlocked = { "Knocked", "isKnocked", "IsHooked", "isHooked", "IsCarried", "isCarried", "Carried" }
        for _, attributeName in ipairs(alwaysBlocked) do
            if character:GetAttribute(attributeName) == true then return true end
        end
        local hum = character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return true end
        local player = AP3Players:GetPlayerFromCharacter(character)
        if player and player:GetAttribute("IsDead") == true then return true end
        if VD._AP3_Safety == true then
            local interactable = character:FindFirstChild("CheckInterractable")
            if interactable then
                local interactionFlags = { "isVaulting", "isSliding", "isDroppingPallet", "isRepairing", "isHealing", "isUnhooking", "isExiting" }
                for _, attributeName in ipairs(interactionFlags) do
                    if interactable:GetAttribute(attributeName) == true then return true end
                end
            end
        end
        return false
    end

    local function AP3IsIgnored(skillName)
        local ignored = VD._AP3_IgnoreSkills
        if type(ignored) ~= "table" then return false end
        for key, value in pairs(ignored) do
            if (type(key) == "string" and value == true and key == skillName)
                or (type(value) == "string" and value == skillName) then
                return true
            end
        end
        return false
    end

    local function AP3FacingPasses(myRoot, killerRoot)
        if VD._AP3_Aggressive == true or VD._AP3_FacingEnabled ~= true then
            return true
        end
        local toMe = Vector3.new(myRoot.Position.X - killerRoot.Position.X, 0, myRoot.Position.Z - killerRoot.Position.Z)
        local look = Vector3.new(killerRoot.CFrame.LookVector.X, 0, killerRoot.CFrame.LookVector.Z)
        if toMe.Magnitude < 0.001 or look.Magnitude < 0.001 then return true end
        local threshold = math.clamp(tonumber(VD._AP3_Facing) or 0.7, -1, 1)
        return look.Unit:Dot(toMe.Unit) >= threshold
    end

    local function AP3FireParry()
        local now = os.clock()
        if not AP3State.Alive or VD._AP3_Enabled ~= true then return false end
        if now < AP3State.CooldownUntil
            or ((AP3State.PendingResultUntil or 0) > 0 and now < AP3State.PendingResultUntil)
            or now - AP3State.LastParry < 0.24 then
            return false
        end

        -- Resolve and send first. Missing remotes must not consume the track/cooldown.
        local remote = AP3GetParryRemote()
        if not remote then return false end
        local sent = false
        if remote:IsA("RemoteEvent") then
            sent = pcall(function() remote:FireServer() end)
        elseif remote:IsA("RemoteFunction") then
            sent = true
            task.spawn(function()
                pcall(function() remote:InvokeServer() end)
            end)
        end
        if not sent then return false end

        now = os.clock()
        AP3State.LastParry = now
        AP3State.CooldownUntil = now + 0.24
        AP3State.PendingResultUntil = now + 0.65
        return true
    end

    local function AP3HandleAnimationTrack(killerPlayer, track)
        if not AP3State.Alive or VD._AP3_Enabled ~= true or not track then return end
        if AP3State.ProcessedTracks[track] then return end
        if not AP3IsKiller(killerPlayer) then return end
        local animation = track.Animation
        local animationId = animation and tostring(animation.AnimationId or ""):match("%d+")
        local skillName = animationId and AP3Animations[animationId]
        if not skillName or AP3IsIgnored(skillName) then return end

        local myCharacter = AP3LocalPlayer and AP3LocalPlayer.Character
        local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")
        local killerCharacter = killerPlayer.Character
        local killerRoot = killerCharacter and killerCharacter:FindFirstChild("HumanoidRootPart")
        if not myRoot or not killerRoot or AP3IsBlocked(myCharacter) then return end

        local range = math.clamp(tonumber(VD._AP3_Range) or 15, 5, 30)
        if VD._AP3_Aggressive == true then range = math.min(range + 5, 35) end
        local distance = (myRoot.Position - killerRoot.Position).Magnitude
        if distance > range or not AP3FacingPasses(myRoot, killerRoot) then return end

        if AP3FireParry() then
            AP3State.ProcessedTracks[track] = {
                LastPosition = tonumber(track.TimePosition) or 0,
                FiredAt = os.clock(),
                SkillName = skillName,
            }
        end
    end

    local function AP3RefreshKillerSensors()
        local now = os.clock()
        if now - (AP3State.LastSensorRefresh or 0) < 0.25 then return end
        AP3State.LastSensorRefresh = now
        for _, player in ipairs(AP3Players:GetPlayers()) do
            if AP3IsKiller(player) then
                local character = player.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator")
                    or humanoid:FindFirstChildWhichIsA("Animator"))
                if animator and not AP3State.AttachedAnimators[animator] then
                    AP3State.AttachedAnimators[animator] = true
                    local ok, connection = pcall(function()
                        return animator.AnimationPlayed:Connect(function(track)
                            -- Event-driven detection catches short attack tracks between heartbeat scans.
                            task.defer(function()
                                pcall(AP3HandleAnimationTrack, player, track)
                            end)
                        end)
                    end)
                    if ok and connection then
                        table.insert(AP3State.EventConnections, connection)
                    else
                        AP3State.AttachedAnimators[animator] = nil
                    end
                end
            end
        end
    end

    local function AP3UpdateCircle(myRoot)
        local shouldShow = VD._AP3_Enabled == true and VD._AP3_ShowCircle == true and myRoot ~= nil
        if not shouldShow then
            if AP3State.Circle then
                pcall(function() AP3State.Circle:Destroy() end)
                AP3State.Circle = nil
            end
            return
        end
        if not AP3State.Circle or not AP3State.Circle.Parent or AP3State.Circle.Adornee ~= myRoot then
            if AP3State.Circle then pcall(function() AP3State.Circle:Destroy() end) end
            local circle = Instance.new("CylinderHandleAdornment")
            circle.Name = "MawwwAP3RangeCircle"
            circle.Height = 0.05
            circle.Transparency = 0.35
            circle.Color3 = Color3.fromRGB(255, 170, 0)
            circle.Adornee = myRoot
            circle.AlwaysOnTop = false
            circle.ZIndex = 0
            circle.Parent = myRoot
            AP3State.Circle = circle
        end
        local radius = math.clamp(tonumber(VD._AP3_Range) or 15, 5, 30)
        if VD._AP3_Aggressive == true then radius = math.min(radius + 5, 35) end
        AP3State.Circle.Radius = radius
        AP3State.Circle.InnerRadius = math.max(0.1, radius - 0.15)
        AP3State.Circle.CFrame = CFrame.new(0, -3, 0) * CFrame.Angles(math.pi / 2, 0, 0)
    end

    local function AP3DisableOtherParries()
        -- Match the  behavior of avoiding simultaneous V1/V2 engines.
        for _, key in ipairs({ "REAPER_AP1_Enabled", "AP_V2_Enabled", "SURV_AutoParryV3" }) do
            VD[key] = false
            local element = VD_Elements and VD_Elements[key]
            if element and type(element.SetValue) == "function" then
                pcall(function() element:SetValue(false) end)
            end
        end
        -- Also stop this hub's concrete V1/V2 engines so the V3 engine cannot double-fire.
        VD.AutoParryV1 = false
        local oxState = _G.Ox
        if type(oxState) == "table" and type(oxState.ParryV2) == "table" then
            oxState.ParryV2.Enabled = false
            if oxState.ParryV2.RangeAdornment then
                pcall(function() oxState.ParryV2.RangeAdornment.Transparency = 1 end)
            end
        end
        local env = (type(getgenv) == "function" and getgenv()) or _G
        if type(env.MAWWW_AutoParryV2) == "table" and type(env.MAWWW_AutoParryV2.SetEnabled) == "function" then
            pcall(function() env.MAWWW_AutoParryV2.SetEnabled(false) end)
        end
    end

    AP3State.Connection = AP3RunService.Heartbeat:Connect(function()
        if not AP3State.Alive then return end
        local now = os.clock()
        if now - AP3State.LastScan < 0.05 then return end
        AP3State.LastScan = now
        AP3AttachCooldownListener()
        AP3RefreshKillerSensors()
        if (AP3State.PendingResultUntil or 0) > 0 and now >= AP3State.PendingResultUntil then
            -- A missing parryResult event must not leave the pending state latched;
            -- apply one bounded fallback cooldown, then allow later attack cycles.
            AP3State.PendingResultUntil = 0
            AP3State.CooldownUntil = math.max(AP3State.CooldownUntil, now + 0.55)
        end
        if VD._AP3_Enabled ~= true then
            AP3UpdateCircle(nil)
            return
        end
        local myCharacter = AP3LocalPlayer and AP3LocalPlayer.Character
        local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")
        AP3UpdateCircle(myRoot)
        if not myRoot or AP3IsBlocked(myCharacter) then return end

        local range = math.clamp(tonumber(VD._AP3_Range) or 15, 5, 30)
        if VD._AP3_Aggressive == true then range = math.min(range + 5, 35) end
        for _, killerPlayer in ipairs(AP3Players:GetPlayers()) do
            if AP3IsKiller(killerPlayer) then
                local killerCharacter = killerPlayer.Character
                local killerRoot = killerCharacter and killerCharacter:FindFirstChild("HumanoidRootPart")
                local killerHumanoid = killerCharacter and killerCharacter:FindFirstChildOfClass("Humanoid")
                local animator = killerHumanoid and killerHumanoid:FindFirstChildOfClass("Animator")
                if killerRoot and animator and killerCharacter and killerCharacter.Parent then
                    local okTracks, tracks = pcall(function()
                        return animator:GetPlayingAnimationTracks()
                    end)
                    if okTracks and type(tracks) == "table" then
                        for _, track in ipairs(tracks) do
                            if track and track.IsPlaying then
                                local trackPosition = tonumber(track.TimePosition) or 0
                                local processed = AP3State.ProcessedTracks[track]

                                -- Tracks can be reused between attacks. Re-arm after a clear
                                -- rewind instead of permanently suppressing later swings.
                                if type(processed) == "table" then
                                    local previousPosition = tonumber(processed.LastPosition)
                                    if previousPosition and previousPosition > 0.30
                                        and trackPosition < math.min(0.25, previousPosition - 0.12) then
                                        AP3State.ProcessedTracks[track] = nil
                                        processed = nil
                                    else
                                        processed.LastPosition = trackPosition
                                    end
                                elseif processed then
                                    -- Migrate any boolean latch to the current track record format.
                                    processed = { LastPosition = trackPosition, FiredAt = now }
                                    AP3State.ProcessedTracks[track] = processed
                                end

                                if not processed then
                                    local animation = track.Animation
                                    local animationId = animation and tostring(animation.AnimationId or ""):match("%d+")
                                    local skillName = animationId and AP3Animations[animationId]
                                    if skillName and not AP3IsIgnored(skillName) then
                                        local distance = (myRoot.Position - killerRoot.Position).Magnitude
                                        if distance <= range and AP3FacingPasses(myRoot, killerRoot) then
                                            -- Do not latch tracks encountered while the cooldown is
                                            -- active. Only record the track if the parry trigger fired.
                                            if AP3FireParry() then
                                                AP3State.ProcessedTracks[track] = {
                                                    LastPosition = trackPosition,
                                                    FiredAt = now,
                                                }
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        for track in pairs(AP3State.ProcessedTracks) do
            local okPlaying, playing = pcall(function() return track.IsPlaying end)
            if not okPlaying or not playing then AP3State.ProcessedTracks[track] = nil end
        end
    end)

    local function AP3Shutdown()
        AP3State.Alive = false
        AP3State.PendingResultUntil = 0
        if AP3State.Connection then
            pcall(function() AP3State.Connection:Disconnect() end)
            AP3State.Connection = nil
        end
        if AP3State.CooldownConnection then
            pcall(function() AP3State.CooldownConnection:Disconnect() end)
            AP3State.CooldownConnection = nil
        end
        for _, connection in ipairs(AP3State.EventConnections or {}) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(AP3State.EventConnections or {})
        AP3State.AttachedAnimators = setmetatable({}, { __mode = "k" })
        if AP3State.Circle then
            pcall(function() AP3State.Circle:Destroy() end)
            AP3State.Circle = nil
        end
        table.clear(AP3State.ProcessedTracks)
    end
    env.MAWWW_AutoParryV3Shutdown = AP3Shutdown
    env.MAWWW_AutoParryV3 = AP3State

    -- Bridge the source engine to the main hub's existing V3 enable/settings API.
    env.MAWWW_AutoParryV3SetEnabled = function(enabled)
        VD._AP3_Enabled = enabled == true
        if VD._AP3_Enabled then
            AP3DisableOtherParries()
        else
            AP3State.PendingResultUntil = 0
            AP3UpdateCircle(nil)
            table.clear(AP3State.ProcessedTracks)
        end
    end
    env.MAWWW_AutoParryV3UpdateCircle = function()
        local character = AP3LocalPlayer and AP3LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if VD._AP3_Enabled == true and VD._AP3_ShowCircle == true and root then
            AP3UpdateCircle(root)
        else
            AP3UpdateCircle(nil)
        end
    end
    env.MAWWW_AutoParryV3DestroyCircle = function()
        AP3UpdateCircle(nil)
    end

    if VD._AP3_Enabled == true then
        AP3DisableOtherParries()
    end
end

        -- Thin compatibility adapter: the isolated V3 engine owns detection, cooldown, and circle logic.
        local AP3Engine = APV3Env.MAWWW_AutoParryV3 or {}
        APV3.SourceModule = {
            State = AP3Engine,
            ForceRedraw = function()
                if type(APV3Env.MAWWW_AutoParryV3UpdateCircle) == "function" then
                    APV3Env.MAWWW_AutoParryV3UpdateCircle()
                end
            end,
            DestroyCircle = function()
                if type(APV3Env.MAWWW_AutoParryV3DestroyCircle) == "function" then
                    APV3Env.MAWWW_AutoParryV3DestroyCircle()
                end
            end,
            StartCooldown = function(seconds)
                AP3Engine.CooldownUntil = os.clock() + math.max(0, tonumber(seconds) or 0)
            end,
            ClearCooldown = function()
                AP3Engine.CooldownUntil = 0
                AP3Engine.PendingResultUntil = 0
            end,
        }
        APV3.State = {
            Cooldown = false,
            CooldownUntil = 0,
            IsResolving = false,
            AwaitingResult = false,
            Connection = nil,
            Circle = AP3Engine.Circle,
        }

        APV3.SyncLegacyConfig = function()
            APV3.Config.AutoParryV3 = VD._AP3_Enabled == true
            APV3.Config.AutoParryV3Radius = math.clamp(tonumber(VD._AP3_Range) or 15, 5, 30)
            APV3.Config.AutoParryV3Aggressive = VD._AP3_Aggressive == true
            APV3.Config.AutoParryV3Safety = VD._AP3_Safety == true
            APV3.Config.AutoParryV3IgnoreFacing = VD._AP3_FacingEnabled ~= true
            APV3.Config.AutoParryV3Face = math.clamp(tonumber(VD._AP3_Facing) or 0.7, -1, 1)
            APV3.Config.AutoParryV3Circle = VD._AP3_ShowCircle == true
            APV3.Config.AutoParryV3IgnoredSkills = type(VD._AP3_IgnoreSkills) == "table" and VD._AP3_IgnoreSkills or {}
            APV3.Config.AutoParryV3IgnoreHiddenS1 = APV3.Config.AutoParryV3IgnoredSkills["Hidden S1"] == true
            APV3.Config.AutoParryV3IgnoreAbyssalS1 = APV3.Config.AutoParryV3IgnoredSkills["Abyssal S1"] == true
        end
        APV3.BeginCooldown = function(seconds)
            if tonumber(seconds) and tonumber(seconds) > 0 then
                APV3.SourceModule.StartCooldown(seconds)
            else
                APV3.SourceModule.ClearCooldown()
            end
        end
        APV3.StartDetection = function()
            VD._AP3_Enabled = true
            if type(APV3Env.MAWWW_AutoParryV3SetEnabled) == "function" then
                APV3Env.MAWWW_AutoParryV3SetEnabled(true)
            end
            APV3.State.Connection = true
            APV3.SyncLegacyConfig()
        end
        APV3.StopDetection = function()
            VD._AP3_Enabled = false
            if type(APV3Env.MAWWW_AutoParryV3SetEnabled) == "function" then
                APV3Env.MAWWW_AutoParryV3SetEnabled(false)
            end
            APV3.State.Connection = nil
            APV3.State.AwaitingResult = false
            APV3.State.IsResolving = false
            APV3.SyncLegacyConfig()
        end
        APV3.UpdateCircle = function()
            if type(APV3Env.MAWWW_AutoParryV3UpdateCircle) == "function" then
                pcall(APV3Env.MAWWW_AutoParryV3UpdateCircle)
            end
            APV3.State.Circle = AP3Engine.Circle
        end
        APV3.SyncLegacyConfig()

        local APV3_StateSyncConnection = RunService.Heartbeat:Connect(function()
            local engine = APV3Env.MAWWW_AutoParryV3
            if not engine then return end
            local now = os.clock()
            local untilTime = tonumber(engine.CooldownUntil) or 0
            APV3.State.Cooldown = now < untilTime
            APV3.State.CooldownUntil = APV3.State.Cooldown and untilTime or 0
            APV3.State.AwaitingResult = (tonumber(engine.PendingResultUntil) or 0) > now
            APV3.State.IsResolving = APV3.State.AwaitingResult
            APV3.State.Circle = engine.Circle
            APV3.State.Connection = VD._AP3_Enabled == true and true or nil
            APV3.SyncLegacyConfig()
        end)
        APV3Env.__MAWWW_APV3StateSyncConnection = APV3_StateSyncConnection

        if VD._AP3_Enabled == true then
            APV3.StartDetection()
        end

        task.spawn(function()
            local ok, resultRemote = pcall(function()
                local remotes = ReplicatedStorage:WaitForChild("Remotes", 5)
                local items = remotes and remotes:WaitForChild("Items", 5)
                local dagger = items and items:WaitForChild("Parrying Dagger", 5)
                return dagger and dagger:WaitForChild("parryResult", 5)
            end)
            if not ok or not resultRemote or not resultRemote:IsA("RemoteEvent") then return end
            resultRemote.OnClientEvent:Connect(function(arg, arg2)
                local cooldown = tonumber(arg2) or (arg == true and 90 or 60)
                cooldown = math.max(0, cooldown)
                APV1State.Cooldown = true
                APV1State.CooldownUntil = os.clock() + cooldown
                if APV1State.CooldownThread then
                    pcall(function() task.cancel(APV1State.CooldownThread) end)
                end
                APV1State.CooldownThread = task.delay(cooldown, function()
                    APV1State.Cooldown = false
                    APV1State.CooldownUntil = 0
                    APV1State.CooldownThread = nil
                end)
            end)
        end)

        local function APV1_UpdateCircle()
            if not APV1Config.AutoParryV1 or not APV1Config.AutoParryV1Circle then
                if APV1State.Circle then pcall(function() APV1State.Circle:Destroy() end) end
                APV1State.Circle = nil
                return
            end
            local character = LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not root then
                if APV1State.Circle then pcall(function() APV1State.Circle:Destroy() end) end
                APV1State.Circle = nil
                return
            end
            if not APV1State.Circle or APV1State.Circle.Parent ~= root then
                if APV1State.Circle then pcall(function() APV1State.Circle:Destroy() end) end
                local adornment = Instance.new("CylinderHandleAdornment")
                adornment.Name = "MAWWW_AutoParryV1_Radius"
                adornment.Height = 0.05
                adornment.Transparency = 0.3
                adornment.Adornee = root
                adornment.Parent = root
                adornment.ZIndex = 0
                adornment.AlwaysOnTop = false
                APV1State.Circle = adornment
            end
            local circle = APV1State.Circle
            circle.Radius = math.clamp(tonumber(APV1Config.AutoParryV1Radius) or 15, 5, 25)
            circle.InnerRadius = math.max(0.1, circle.Radius - 0.15)
            circle.CFrame = CFrame.new(0, -3, 0) * CFrame.Angles(math.rad(90), 0, 0)
            -- Cyan range circle for Auto Parry V1 in every state.
            circle.Color3 = Color3.fromRGB(0, 255, 255)
        end

        local function APV1_DestroyKillerTriangle()
            if APV1State.KillerTriangleFolder then
                pcall(function() APV1State.KillerTriangleFolder:Destroy() end)
            end
            APV1State.KillerTriangleFolder = nil
            APV1State.KillerTriangleDashes = {}
            APV1State.KillerTriangleLocalCFs = {}
            APV1State.KillerTriangleLength = 0
            APV1State.KillerTriangleHalfWidth = 0
            APV1State.KillerTriangleLastCF = nil
            APV1State.KillerTriangleLastColor = nil
            APV1State.KillerTriangleLastKiller = nil
            APV1State.KillerTriangleLastUpdate = 0
        end

        local function APV1_BuildKillerTriangle(length, halfWidth)
            APV1_DestroyKillerTriangle()
            local folder = Instance.new("Folder")
            folder.Name = "MAWWW_AutoParryV1_KillerPOV_Triangle"

            local L, W = length, halfWidth
            local vertices = {
                Vector3.new(0, 0, 0),
                Vector3.new(W, 0, -L),
                Vector3.new(-W, 0, -L),
            }
            local edges = {
                {vertices[1], vertices[2]},
                {vertices[2], vertices[3]},
                {vertices[3], vertices[1]},
            }
            local dashes, localCFs = {}, {}
            local dashThickness, dashGapRatio = 0.05, 0.28

            for _, edge in ipairs(edges) do
                local startPos, endPos = edge[1], edge[2]
                local edgeVec = endPos - startPos
                local edgeLen = edgeVec.Magnitude
                if edgeLen > 0.05 then
                    local edgeDir = edgeVec.Unit
                    -- Cap dash count to keep the visual lightweight on mobile.
                    local numDashes = math.clamp(math.floor(edgeLen / 0.8), 6, 15)
                    local slotLen = edgeLen / numDashes
                    local dashLen = slotLen * (1 - dashGapRatio)
                    for i = 1, numDashes do
                        local t = (i - 0.5) / numDashes
                        local midPos = startPos + edgeVec * t
                        local part = Instance.new("Part")
                        part.Name = "KillerPOVDash"
                        part.Anchored = true
                        part.CanCollide = false
                        part.CanTouch = false
                        part.CanQuery = false
                        part.CastShadow = false
                        part.Material = Enum.Material.Neon
                        part.Color = Color3.fromRGB(255, 140, 60)
                        part.Transparency = 0
                        part.Size = Vector3.new(dashThickness, dashThickness, dashLen)
                        part.TopSurface = Enum.SurfaceType.Smooth
                        part.BottomSurface = Enum.SurfaceType.Smooth
                        part.Parent = folder
                        dashes[#dashes + 1] = part
                        localCFs[#localCFs + 1] = CFrame.lookAt(midPos, midPos + edgeDir)
                    end
                end
            end

            folder.Parent = Workspace
            APV1State.KillerTriangleFolder = folder
            APV1State.KillerTriangleDashes = dashes
            APV1State.KillerTriangleLocalCFs = localCFs
            APV1State.KillerTriangleLength = L
            APV1State.KillerTriangleHalfWidth = W
        end

        local function APV1_UpdateKillerTriangle()
            local now = os.clock()
            if now - (APV1State.KillerTriangleLastUpdate or 0) < (1 / 30) then return end
            APV1State.KillerTriangleLastUpdate = now

            if not APV1Config.AutoParryV1 or not APV1Config.AutoParryV1KillerTriangle then
                if APV1State.KillerTriangleFolder then APV1_DestroyKillerTriangle() end
                return
            end

            local myCharacter = LocalPlayer.Character
            local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")
            if not myRoot then
                if APV1State.KillerTriangleFolder then APV1_DestroyKillerTriangle() end
                return
            end

            local length = math.clamp(tonumber(APV1Config.AutoParryV1Radius) or 15, 5, 25)
            local halfWidth = APV1_GetKillerTriangleHalfWidth(length)
            local nearestRoot, nearestDistance = nil, math.huge
            for _, killerPlayer in ipairs(Players:GetPlayers()) do
                if killerPlayer ~= LocalPlayer and killerPlayer.Team and killerPlayer.Team.Name == "Killer" then
                    local killerCharacter = killerPlayer.Character
                    local killerHumanoid = killerCharacter and killerCharacter:FindFirstChildOfClass("Humanoid")
                    local killerRoot = killerCharacter and killerCharacter:FindFirstChild("HumanoidRootPart")
                    if killerRoot and killerHumanoid and killerHumanoid.Health > 0 then
                        local distance = (myRoot.Position - killerRoot.Position).Magnitude
                        if distance <= length and distance < nearestDistance then
                            nearestRoot, nearestDistance = killerRoot, distance
                        end
                    end
                end
            end

            if not nearestRoot then
                if APV1State.KillerTriangleFolder then APV1_DestroyKillerTriangle() end
                return
            end

            if not APV1State.KillerTriangleFolder
                or not APV1State.KillerTriangleFolder.Parent
                or APV1State.KillerTriangleLength ~= length
                or math.abs(APV1State.KillerTriangleHalfWidth - halfWidth) > 0.02 then
                APV1_BuildKillerTriangle(length, halfWidth)
            end

            local look = nearestRoot.CFrame.LookVector
            local flatLook = Vector3.new(look.X, 0, look.Z)
            if flatLook.Magnitude < 0.001 then flatLook = Vector3.new(0, 0, 1) end
            flatLook = flatLook.Unit
            local tipPosition = nearestRoot.Position - Vector3.new(0, 3, 0)
            local baseCF = CFrame.lookAt(tipPosition, tipPosition + flatLook)

            local inside = APV1_IsInsideKillerTriangle(nearestRoot, myRoot, length, halfWidth)
            if APV1Config.AutoParryV1FaceEnabled then
                local threshold = tonumber(APV1Config.AutoParryV1Face) or 0.7
                if threshold < 0.2 then threshold = 0.35 end
                inside = inside and APV1_IsInKillerPOV(nearestRoot, myRoot, threshold)
            end
            local targetColor = inside and Color3.fromRGB(255, 40, 40) or Color3.fromRGB(255, 140, 60)

            local lastCF = APV1State.KillerTriangleLastCF
            local moved = not lastCF or (lastCF.Position - baseCF.Position).Magnitude > 0.02
            if not moved and lastCF then moved = lastCF.LookVector:Dot(baseCF.LookVector) < 0.9995 end
            local colorChanged = APV1State.KillerTriangleLastColor ~= targetColor
            local killerChanged = APV1State.KillerTriangleLastKiller ~= nearestRoot
            if not moved and not colorChanged and not killerChanged then return end

            APV1State.KillerTriangleLastCF = baseCF
            APV1State.KillerTriangleLastColor = targetColor
            APV1State.KillerTriangleLastKiller = nearestRoot
            for i, part in ipairs(APV1State.KillerTriangleDashes) do
                if part and part.Parent then
                    part.CFrame = baseCF * APV1State.KillerTriangleLocalCFs[i]
                    part.Color = targetColor
                end
            end
        end

        -- Remove a stale triangle from an earlier execution before installing this one.
        pcall(function()
            local staleTriangle = Workspace:FindFirstChild("MAWWW_AutoParryV1_KillerPOV_Triangle")
            if staleTriangle then staleTriangle:Destroy() end
        end)

        APV1State.CircleConn = RunService.Heartbeat:Connect(function()
            pcall(APV1_UpdateCircle)
            pcall(APV1_UpdateKillerTriangle)
        end)

        -- Shared draggable live-status UI for Auto Parry V1, V2, and the dedicated  V3 engine.
        -- No floating image buttons: each remaining status panel is controlled ONLY by its Show Panel toggle.
        -- Auto Parry ON/OFF controls the parry engine and never forces a panel to show or hide.
        -- Both status panels reuse the existing BACKGROUND asset provided by the user and are draggable on PC/mobile.
        local AP_LiveGui = nil
        local AP_LiveRefs = {}

        -- Store each panel's own position outside the GUI so hide/show and safe script
        -- re-execution do not reset it to the screen center.
        local AP_LivePositions = getgenv().__MAWWW_APLivePanelPositions
        if type(AP_LivePositions) ~= "table" then
            AP_LivePositions = {}
            getgenv().__MAWWW_APLivePanelPositions = AP_LivePositions
        end

        local function AP_LivePanelKey(panel)
            if not panel then return nil end
            if panel.Name == "AutoParryV1LivePanel" then return "V1" end
            if panel.Name == "AutoParryV2LivePanel" then return "V2" end
            if panel.Name == "AutoParryV3LivePanel" then return "V3" end
            return nil
        end

        local function AP_ClampLivePanelPosition(panel, x, y)
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize or Vector2.new(360, 720)
            local size = panel and panel.AbsoluteSize or Vector2.new(280, 136)
            if panel and size.X <= 0 then size = Vector2.new(panel.Size.X.Offset, size.Y) end
            if panel and size.Y <= 0 then size = Vector2.new(size.X, panel.Size.Y.Offset) end
            local anchor = panel and panel.AnchorPoint or Vector2.new(0.5, 0)
            local minX = size.X * anchor.X
            local maxX = viewport.X - size.X * (1 - anchor.X)
            if maxX < minX then maxX = minX end
            x = math.clamp(tonumber(x) or viewport.X * 0.5, minX, maxX)
            y = math.clamp(tonumber(y) or 150, 0, math.max(0, viewport.Y - size.Y))
            return x, y
        end

        local function AP_SaveLivePanelPosition(panel)
            local key = AP_LivePanelKey(panel)
            if not key or not panel then return end
            local x, y = AP_ClampLivePanelPosition(panel, panel.Position.X.Offset, panel.Position.Y.Offset)
            panel.Position = UDim2.fromOffset(x, y)
            AP_LivePositions[key] = {X = x, Y = y}
        end

        local AP_LiveStatusConn = nil
        local AP_LiveConnections = getgenv().__MAWWW_APLiveConnections or {}
        for _, connection in ipairs(AP_LiveConnections) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(AP_LiveConnections)
        getgenv().__MAWWW_APLiveConnections = AP_LiveConnections

        local APV1_SetEnabled, APV2_SetEnabled
        local APV1EnableControl, APV2EnableControl
        local APV1PanelControl, APV2PanelControl

        local function AP_SyncHubToggle(control, enabled)
            if not control then return end
            local registry = getgenv().__MAWWW_ToggleStateSync
            local entry = type(registry) == "table" and registry[control] or nil
            if entry and type(entry.Set) == "function" then
                pcall(entry.Set, enabled == true, true)
            end
        end

        local function AP_GetNearestKillerDistance()
            local myCharacter = LocalPlayer.Character
            local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")
            if not myRoot then return nil end

            local nearestDistance, nearestName = nil, nil
            for _, otherPlayer in ipairs(Players:GetPlayers()) do
                if otherPlayer ~= LocalPlayer and otherPlayer.Team and otherPlayer.Team.Name == "Killer" then
                    local killerCharacter = otherPlayer.Character
                    local killerRoot = killerCharacter and killerCharacter:FindFirstChild("HumanoidRootPart")
                    local killerHumanoid = killerCharacter and killerCharacter:FindFirstChildOfClass("Humanoid")
                    if killerRoot and (not killerHumanoid or killerHumanoid.Health > 0) then
                        local distance = (killerRoot.Position - myRoot.Position).Magnitude
                        if nearestDistance == nil or distance < nearestDistance then
                            nearestDistance = distance
                            nearestName = otherPlayer.DisplayName or otherPlayer.Name
                        end
                    end
                end
            end
            return nearestDistance, nearestName
        end

        local function AP_SetKillerDistanceLabel(label, killerDistance, killerName)
            if not label or not label.Parent then return end
            if killerDistance then
                label.Text = string.format("KILLER  %s  •  %.1f STUDS", tostring(killerName or "Killer"), killerDistance)
                label.TextColor3 = killerDistance <= 15 and Color3.fromRGB(255, 120, 120)
                    or (killerDistance <= 35 and Color3.fromRGB(255, 190, 95) or Color3.fromRGB(120, 225, 255))
            else
                label.Text = "KILLER DISTANCE  •  NO KILLER"
                label.TextColor3 = Color3.fromRGB(170, 180, 195)
            end
        end

        local function AP_UpdateStatusPanel()
            local now = os.clock()
            local v1Enabled = APV1Config.AutoParryV1 == true
            local v1Remaining = math.max(0, (tonumber(APV1State.CooldownUntil) or 0) - now)
            local v1Text, v1Color
            if not v1Enabled then
                v1Text, v1Color = "PARRY COOLDOWN  •  OFF", Color3.fromRGB(170, 180, 195)
            elseif APV1State.Cooldown then
                v1Text = string.format("PARRY COOLDOWN  •  %.1fs", v1Remaining)
                v1Color = Color3.fromRGB(255, 173, 66)
            else
                v1Text, v1Color = "PARRY COOLDOWN  •  READY", Color3.fromRGB(82, 231, 154)
            end

            local parryV2 = _G.Ox and _G.Ox.ParryV2
            local v2Enabled = parryV2 and parryV2.Enabled == true
            local v2Remaining = math.max(0, (parryV2 and tonumber(parryV2.CooldownUntil) or 0) - now)
            local v2Text, v2Color
            if not v2Enabled then
                v2Text, v2Color = "PARRY COOLDOWN  •  OFF", Color3.fromRGB(170, 180, 195)
            elseif parryV2.IsOnCooldown then
                v2Text = string.format("PARRY COOLDOWN  •  %.1fs", v2Remaining)
                v2Color = Color3.fromRGB(255, 173, 66)
            elseif parryV2.IsResolving then
                v2Text, v2Color = "PARRY COOLDOWN  •  PARRYING", Color3.fromRGB(255, 255, 255)
            else
                v2Text, v2Color = "PARRY COOLDOWN  •  READY", Color3.fromRGB(71, 224, 255)
            end

            local v3Enabled = VD._AP3_Enabled == true
            local v3Engine = APV3Env.MAWWW_AutoParryV3
            local v3CooldownUntil = v3Engine and tonumber(v3Engine.CooldownUntil) or 0
            local v3PendingUntil = v3Engine and tonumber(v3Engine.PendingResultUntil) or 0
            local v3Remaining = math.max(0, v3CooldownUntil - now)
            local v3Text, v3Color
            if not v3Enabled then
                v3Text, v3Color = "PARRY COOLDOWN  •  OFF", Color3.fromRGB(170, 180, 195)
            elseif v3PendingUntil > now then
                v3Text, v3Color = "PARRY COOLDOWN  •  PARRYING", Color3.fromRGB(120, 225, 255)
            elseif v3Remaining > 0 then
                v3Text = string.format("PARRY COOLDOWN  •  %.1fs", v3Remaining)
                v3Color = Color3.fromRGB(255, 173, 66)
            else
                v3Text, v3Color = "PARRY COOLDOWN  •  READY", Color3.fromRGB(82, 231, 154)
            end

            local killerDistance, killerName = AP_GetNearestKillerDistance()
            if AP_LiveRefs.V1Cooldown and AP_LiveRefs.V1Cooldown.Parent then
                AP_LiveRefs.V1Cooldown.Text = v1Text
                AP_LiveRefs.V1Cooldown.TextColor3 = v1Color
            end
            if AP_LiveRefs.V2Cooldown and AP_LiveRefs.V2Cooldown.Parent then
                AP_LiveRefs.V2Cooldown.Text = v2Text
                AP_LiveRefs.V2Cooldown.TextColor3 = v2Color
            end
            if AP_LiveRefs.V3Cooldown and AP_LiveRefs.V3Cooldown.Parent then
                AP_LiveRefs.V3Cooldown.Text = v3Text
                AP_LiveRefs.V3Cooldown.TextColor3 = v3Color
            end
            AP_SetKillerDistanceLabel(AP_LiveRefs.V1KillerDistance, killerDistance, killerName)
            AP_SetKillerDistanceLabel(AP_LiveRefs.V2KillerDistance, killerDistance, killerName)
            AP_SetKillerDistanceLabel(AP_LiveRefs.V3KillerDistance, killerDistance, killerName)

            if AP_LiveRefs.V1Toggle and AP_LiveRefs.V1Toggle.Parent then
                AP_LiveRefs.V1Toggle.Text = v1Enabled and "ON" or "OFF"
                AP_LiveRefs.V1Toggle.BackgroundColor3 = v1Enabled and Color3.fromRGB(19, 83, 61) or Color3.fromRGB(48, 36, 43)
                AP_LiveRefs.V1Toggle.TextColor3 = v1Enabled and Color3.fromRGB(190, 255, 215) or Color3.fromRGB(230, 220, 225)
            end
            if AP_LiveRefs.V2Toggle and AP_LiveRefs.V2Toggle.Parent then
                AP_LiveRefs.V2Toggle.Text = v2Enabled and "ON" or "OFF"
                AP_LiveRefs.V2Toggle.BackgroundColor3 = v2Enabled and Color3.fromRGB(15, 74, 91) or Color3.fromRGB(36, 39, 52)
                AP_LiveRefs.V2Toggle.TextColor3 = v2Enabled and Color3.fromRGB(190, 245, 255) or Color3.fromRGB(220, 225, 235)
            end
            if AP_LiveRefs.V3Toggle and AP_LiveRefs.V3Toggle.Parent then
                AP_LiveRefs.V3Toggle.Text = v3Enabled and "ON" or "OFF"
                AP_LiveRefs.V3Toggle.BackgroundColor3 = v3Enabled and Color3.fromRGB(19, 83, 61) or Color3.fromRGB(48, 36, 43)
                AP_LiveRefs.V3Toggle.TextColor3 = v3Enabled and Color3.fromRGB(190, 255, 215) or Color3.fromRGB(230, 220, 225)
            end
        end

        local function AP_UpdateGuiVisibility()
            if not AP_LiveGui or not AP_LiveGui.Parent then return end
            local showV1 = APV1State.GuiVisible == true
            local showV2 = APV2State.GuiVisible == true
            local showV3 = APV3.Config.AutoParryV3GuiVisible == true
            if AP_LiveRefs.V1Panel then AP_LiveRefs.V1Panel.Visible = showV1 end
            if AP_LiveRefs.V2Panel then AP_LiveRefs.V2Panel.Visible = showV2 end
            if AP_LiveRefs.V3Panel then AP_LiveRefs.V3Panel.Visible = showV3 end
            AP_LiveGui.Enabled = showV1 or showV2 or showV3

            -- IMPORTANT: showing/hiding a panel must never reposition it.
            -- Preserve the last user-dragged position and only clamp if the screen resized.
            if AP_LiveRefs.V1Panel then
                AP_SaveLivePanelPosition(AP_LiveRefs.V1Panel)
            end
            if AP_LiveRefs.V2Panel then
                AP_SaveLivePanelPosition(AP_LiveRefs.V2Panel)
            end
            if AP_LiveRefs.V3Panel then
                AP_SaveLivePanelPosition(AP_LiveRefs.V3Panel)
            end
        end

        local function AP_MakeDraggablePanel(panel, dragHandle)
            if not panel or not dragHandle then return end
            dragHandle.Active = true
            local activeInput, startInputPosition, startPanelPosition = nil, nil, nil

            dragHandle.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    activeInput = input
                    startInputPosition = input.Position
                    startPanelPosition = panel.Position
                end
            end)

            local changedConn = UserInputService.InputChanged:Connect(function(input)
                if not activeInput or not panel.Parent then return end
                if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end

                local delta = input.Position - startInputPosition
                local camera = workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(360, 720)
                local panelSize = panel.AbsoluteSize
                local x = (startPanelPosition.X.Scale * viewport.X) + startPanelPosition.X.Offset + delta.X
                local y = (startPanelPosition.Y.Scale * viewport.Y) + startPanelPosition.Y.Offset + delta.Y

                -- Keep the draggable status panel inside the screen on both desktop and mobile.
                -- Use the same clamp helper for touch and mouse coordinates.
                x, y = AP_ClampLivePanelPosition(panel, x, y)
                panel.Position = UDim2.fromOffset(x, y)
                AP_SaveLivePanelPosition(panel)
            end)

            local endedConn = UserInputService.InputEnded:Connect(function(input)
                if not activeInput then return end
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    AP_SaveLivePanelPosition(panel)
                    activeInput, startInputPosition, startPanelPosition = nil, nil, nil
                end
            end)
            table.insert(AP_LiveConnections, changedConn)
            table.insert(AP_LiveConnections, endedConn)
        end

        local function AP_CreateLiveGUI()
            if AP_LiveGui and AP_LiveGui.Parent then return end

            -- Clean up previous versions, allowing safe re-execution.
            for _, parent in ipairs({CoreGui, LocalPlayer:FindFirstChildOfClass("PlayerGui")}) do
                if parent then
                    for _, oldName in ipairs({"MAWWW_AutoParryV1_Button", "MAWWW_AutoParryV2_Button", "MAWWW_AutoParryV3_Button", "MAWWW_AutoParryLiveUI"}) do
                        local old = parent:FindFirstChild(oldName)
                        if old then pcall(function() old:Destroy() end) end
                    end
                end
            end

            local screenGui = Instance.new("ScreenGui")
            screenGui.Name = "MAWWW_AutoParryLiveUI"
            screenGui.ResetOnSpawn = false
            screenGui.IgnoreGuiInset = true
            screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            screenGui.DisplayOrder = 999
            local parented = pcall(function() screenGui.Parent = CoreGui end)
            if not parented or not screenGui.Parent then
                local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
                if playerGui then screenGui.Parent = playerGui else screenGui:Destroy(); return end
            end
            AP_LiveGui = screenGui
            APV1State.CustomGui = screenGui
            APV2State.CustomGui = screenGui

            local function makeStatusPanel(name, titleText, positionY, accent, subtitleText)
                local camera = workspace.CurrentCamera
                local viewportWidth = (camera and camera.ViewportSize.X) or 360
                local panelWidth = math.max(240, math.min(viewportWidth - 20, 350))
                local panelHeight = 136

                local panel = Instance.new("Frame")
                panel.Name = name
                panel.AnchorPoint = Vector2.new(0.5, 0)
                panel.Position = UDim2.new(0.5, 0, 0, positionY or 150)
                panel.Size = UDim2.fromOffset(panelWidth, panelHeight)
                panel.BackgroundColor3 = Color3.fromRGB(10, 8, 24)
                panel.BackgroundTransparency = 0
                panel.BorderSizePixel = 0
                panel.ClipsDescendants = true
                panel.Visible = false
                panel.ZIndex = 100
                panel.Parent = screenGui

                local positionKey = AP_LivePanelKey(panel)
                local savedPosition = positionKey and AP_LivePositions[positionKey]
                local defaultX = viewportWidth * 0.5
                local defaultY = tonumber(positionY) or 150
                local targetX, targetY = defaultX, defaultY
                if type(savedPosition) == "table" then
                    targetX = tonumber(savedPosition.X) or targetX
                    targetY = tonumber(savedPosition.Y) or targetY
                end
                targetX, targetY = AP_ClampLivePanelPosition(panel, targetX, targetY)
                panel.Position = UDim2.fromOffset(targetX, targetY)
