            local localMakeV1Line
            AP_LiveRefs.V1Panel, localMakeV1Line = makeStatusPanel(
                "AutoParryV1LivePanel", "AUTO PARRY V1", 150,
                Color3.fromRGB(171, 91, 255), "Cooldown • killer distance")
            AP_LiveRefs.V1Cooldown = localMakeV1Line(
                "Cooldown", "PARRY COOLDOWN  •  READY", 48, Color3.fromRGB(82, 231, 154))
            AP_LiveRefs.V1KillerDistance = localMakeV1Line(
                "KillerDistance", "KILLER DISTANCE  •  SCANNING...", 88, Color3.fromRGB(120, 225, 255))

            local localMakeV2Line
            AP_LiveRefs.V2Panel, localMakeV2Line = makeStatusPanel(
                "AutoParryV2LivePanel", "AUTO PARRY V2", 296,
                Color3.fromRGB(71, 224, 255), "Cooldown • killer distance")
            AP_LiveRefs.V2Cooldown = localMakeV2Line(
                "Cooldown", "PARRY COOLDOWN  •  READY", 48, Color3.fromRGB(71, 224, 255))
            AP_LiveRefs.V2KillerDistance = localMakeV2Line(
                "KillerDistance", "KILLER DISTANCE  •  SCANNING...", 88, Color3.fromRGB(120, 225, 255))

            local localMakeV3Line
            AP_LiveRefs.V3Panel, localMakeV3Line = makeStatusPanel(
                "AutoParryV3LivePanel", "AUTO PARRY V3", 442,
                Color3.fromRGB(255, 170, 64), " engine • cooldown • killer distance")
            AP_LiveRefs.V3Cooldown = localMakeV3Line(
                "Cooldown", "PARRY COOLDOWN  •  READY", 48, Color3.fromRGB(82, 231, 154))
            AP_LiveRefs.V3KillerDistance = localMakeV3Line(
                "KillerDistance", "KILLER DISTANCE  •  SCANNING...", 88, Color3.fromRGB(120, 225, 255))

            local function makeToggle(parentObject, name, text, accent)
                local button = Instance.new("TextButton")
                button.Name = name
                button.AnchorPoint = Vector2.new(1, 0)
                button.Position = UDim2.new(1, -8, 0, 49)
                button.Size = UDim2.fromOffset(68, 70)
                button.BackgroundColor3 = Color3.fromRGB(48, 36, 43)
                button.BorderSizePixel = 0
                button.Text = text
                button.Font = Enum.Font.GothamBold
                button.TextSize = 11
                button.TextColor3 = Color3.fromRGB(230, 220, 225)
                button.AutoButtonColor = false
                -- Parent-panel visibility controls this button; it is never a separate floating widget.
                button.Visible = true
                button.ZIndex = 105
                button.Parent = parentObject
                Instance.new("UICorner", button).CornerRadius = UDim.new(0, 9)
                local outline = Instance.new("UIStroke")
                outline.Color = accent
                outline.Thickness = 1.1
                outline.Transparency = 0.15
                outline.Parent = button
                return button
            end
            AP_LiveRefs.V1Toggle = makeToggle(AP_LiveRefs.V1Panel, "AutoParryV1Toggle", "OFF", Color3.fromRGB(82, 231, 154))
            AP_LiveRefs.V2Toggle = makeToggle(AP_LiveRefs.V2Panel, "AutoParryV2Toggle", "OFF", Color3.fromRGB(71, 224, 255))
            AP_LiveRefs.V3Toggle = makeToggle(AP_LiveRefs.V3Panel, "AutoParryV3Toggle", "OFF", Color3.fromRGB(255, 170, 64))
            AP_LiveRefs.V1Toggle.Activated:Connect(function()
                if APV1_SetEnabled then APV1_SetEnabled(not (APV1Config.AutoParryV1 == true), false) end
            end)
            AP_LiveRefs.V2Toggle.Activated:Connect(function()
                local enabled = _G.Ox and _G.Ox.ParryV2 and _G.Ox.ParryV2.Enabled == true
                if APV2_SetEnabled then APV2_SetEnabled(not enabled, false) end
            end)
            AP_LiveRefs.V3Toggle.Activated:Connect(function()
                if APV3.SetEnabled then APV3.SetEnabled(VD._AP3_Enabled ~= true, false) end
            end)

            AP_UpdateStatusPanel()
            if AP_LiveStatusConn then pcall(function() AP_LiveStatusConn:Disconnect() end) end
            local lastRefresh = 0
            AP_LiveStatusConn = RunService.Heartbeat:Connect(function()
                if not AP_LiveGui or not AP_LiveGui.Parent then
                    if AP_LiveStatusConn then AP_LiveStatusConn:Disconnect(); AP_LiveStatusConn = nil end
                    return
                end
                if os.clock() - lastRefresh >= 0.12 then
                    lastRefresh = os.clock()
                    AP_UpdateStatusPanel()
                end
            end)
            table.insert(AP_LiveConnections, AP_LiveStatusConn)
            AP_UpdateGuiVisibility()
        end

        local function APV1_UpdateCustomButton()
            AP_UpdateStatusPanel()
        end

        APV1_SetEnabled = function(enabled, silent)
            APV1Config.AutoParryV1 = enabled == true

            -- Do not change GuiVisible here. The separate Show Panel toggle owns panel visibility.
            AP_SyncHubToggle(APV1EnableControl, APV1Config.AutoParryV1)
            APV1_UpdateCustomButton()
            AP_UpdateStatusPanel()
            if not silent then
                VD_Notify("Auto Parry V1", APV1Config.AutoParryV1 and "Enabled" or "Disabled", 2)
            end
        end

        local function APV1_CreateCustomGUI()
            AP_CreateLiveGUI()
            AP_UpdateGuiVisibility()
            AP_UpdateStatusPanel()
        end

        local function APV1_SetCustomGUIVisible(visible)
            APV1State.GuiVisible = visible == true
            AP_SyncHubToggle(APV1PanelControl, APV1State.GuiVisible)
            if APV1State.GuiVisible then
                APV1_CreateCustomGUI()
                if AP_LiveRefs.V1Panel then AP_LiveRefs.V1Panel.Visible = true end
            end
            AP_UpdateGuiVisibility()
            AP_UpdateStatusPanel()
        end

        local function APV2_UpdateCustomButton()
            AP_UpdateStatusPanel()
        end

        APV2_SetEnabled = function(enabled, silent)
            local parryV2 = _G.Ox and _G.Ox.ParryV2
            if not parryV2 then return end
            parryV2.Enabled = enabled == true
            if not parryV2.Enabled then
                if type(V2_ResetCooldown) == "function" then V2_ResetCooldown() end
                _G.Ox._V2ParryLastRoot = nil
                _G.Ox._V2ParryLastRadius = -1
                if parryV2.RangeAdornment then
                    parryV2.RangeAdornment.Transparency = 1
                end
            else
                _G.Ox._V2ParryLastRadius = -1
            end
            -- Do not change GuiVisible here. The separate Show Panel toggle owns panel visibility.
            AP_SyncHubToggle(APV2EnableControl, parryV2.Enabled)
            APV2_UpdateCustomButton()
            AP_UpdateStatusPanel()
            if not silent then
                VD_Notify("Auto Parry V2", parryV2.Enabled and "Enabled" or "Disabled", 2)
            end
        end

        local function APV2_CreateCustomGUI()
            AP_CreateLiveGUI()
            AP_UpdateGuiVisibility()
            AP_UpdateStatusPanel()
        end

        local function APV2_SetCustomGUIVisible(visible)
            APV2State.GuiVisible = visible == true
            AP_SyncHubToggle(APV2PanelControl, APV2State.GuiVisible)
            if APV2State.GuiVisible then
                APV2_CreateCustomGUI()
                if AP_LiveRefs.V2Panel then AP_LiveRefs.V2Panel.Visible = true end
            end
            AP_UpdateGuiVisibility()
            AP_UpdateStatusPanel()
        end

        APV3.SetCustomGUIVisible = function(visible)
            APV3.Config.AutoParryV3GuiVisible = visible == true
            AP_SyncHubToggle(APV3.PanelControl, APV3.Config.AutoParryV3GuiVisible)
            if APV3.Config.AutoParryV3GuiVisible then
                AP_CreateLiveGUI()
                if AP_LiveRefs.V3Panel then AP_LiveRefs.V3Panel.Visible = true end
            end
            AP_UpdateGuiVisibility()
            AP_UpdateStatusPanel()
        end

        APV3.SetEnabled = function(enabled, silent)
            APV3.Config.AutoParryV3 = enabled == true
            if APV3.Config.AutoParryV3 then
                APV3.StartDetection()
                AP_SyncHubToggle(APV1EnableControl, false)
                AP_SyncHubToggle(APV2EnableControl, false)
            else
                APV3.StopDetection()
                if APV3.State.AwaitingResult then
                    APV3.BeginCooldown(0)
                end
            end
            APV3.UpdateCircle()
            AP_SyncHubToggle(APV3.EnableControl, APV3.Config.AutoParryV3)
            AP_UpdateStatusPanel()
            if not silent then
                VD_Notify("Auto Parry V3", APV3.Config.AutoParryV3 and "Enabled" or "Disabled", 2)
            end
        end

        -- V3 uses its own floating live-status panel, separate from its engine-enable toggle.

        function IsKiller(p) return p and p.Team and p.Team.Name == "Killer" end

        function AttachParrySensor(kChar)
            if not kChar or APV1State.Attached[kChar] then return end
            APV1State.Attached[kChar] = true
            local humanoid = kChar:FindFirstChild("Humanoid") or kChar:WaitForChild("Humanoid", 5)
            if not humanoid then APV1State.Attached[kChar] = nil; return end
            local animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5)
            if not animator then APV1State.Attached[kChar] = nil; return end

            humanoid.ChildAdded:Connect(function(child)
                if child:IsA("Animator") then
                    APV1State.Attached[kChar] = nil
                    AttachParrySensor(kChar)
                end
            end)
            kChar.AncestryChanged:Connect(function(_, parent)
                if not parent then APV1State.Attached[kChar] = nil end
            end)

            animator.AnimationPlayed:Connect(function(track)
                local animId = track.Animation and track.Animation.AnimationId or ""
                local id = animId:match("%d+")
                local skillName = APV1SkillAnimations[id]
                if not skillName then return end

                -- Preserve the hub's existing Auto Crouch Dodge behavior.
                if id == "80411309607666" and VD.AutoCrouch then
                    local myChar = LocalPlayer.Character
                    if not APV1_IsDowned(myChar) then
                        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                        local killerRoot = kChar:FindFirstChild("HumanoidRootPart")
                        if myRoot and killerRoot and (myRoot.Position - killerRoot.Position).Magnitude <= 40 then
                            TriggerCrouch()
                        end
                    end
                    return
                end

                if not APV1Config.AutoParryV1 or APV1State.Cooldown then return end
                if LocalPlayer.Team and LocalPlayer.Team.Name == "Killer" then return end
                if APV1Config.AutoParryV1IgnoredSkills and APV1Config.AutoParryV1IgnoredSkills[skillName] then return end

                local character = LocalPlayer.Character
                if APV1_IsDowned(character) or not APV1_IsSafeToParry(character) then return end
                local myRoot = character and character:FindFirstChild("HumanoidRootPart")
                local killerRoot = kChar:FindFirstChild("HumanoidRootPart")
                if not myRoot or not killerRoot then return end
                local distance = (myRoot.Position - killerRoot.Position).Magnitude
                local radius = math.clamp(tonumber(APV1Config.AutoParryV1Radius) or 15, 5, 25)

                if APV1Config.AutoParryV1Aggressive then
                    if distance > radius + 5 then return end
                    local function aggressiveCheck()
                        if APV1State.Cooldown or APV1_IsDowned(character) then return true end
                        if not myRoot.Parent or not killerRoot.Parent then return true end
                        if (myRoot.Position - killerRoot.Position).Magnitude > 12 or not APV1_FaceCheckOk(killerRoot, myRoot) then
                            return false
                        end
                        APV1_ExecuteParry()
                        return true
                    end
                    if aggressiveCheck() then return end
                    local started = os.clock()
                    local connection
                    connection = RunService.Heartbeat:Connect(function()
                        if os.clock() - started >= 0.85 or aggressiveCheck() then
                            if connection then connection:Disconnect() end
                        end
                    end)
                else
                    local triggerRadius = radius + 2
                    if distance > radius + 6 then return end
                    if distance <= triggerRadius and APV1_FaceCheckOk(killerRoot, myRoot) then
                        APV1_ExecuteParry()
                        return
                    end
                    local started = os.clock()
                    local connection
                    connection = RunService.Heartbeat:Connect(function()
                        if os.clock() - started < 0.28 and not APV1State.Cooldown
                            and myRoot and killerRoot and myRoot.Parent and killerRoot.Parent
                            and not APV1_IsDowned(character) then
                            if (myRoot.Position - killerRoot.Position).Magnitude <= triggerRadius
                                and APV1_FaceCheckOk(killerRoot, myRoot) then
                                APV1_ExecuteParry()
                                if connection then connection:Disconnect() end
                            end
                        else
                            if connection then connection:Disconnect() end
                        end
                    end)
                end
            end)
        end

        function TryAttach(p)
            if p ~= LocalPlayer and IsKiller(p) and p.Character then AttachParrySensor(p.Character) end
        end

        function SetupPlayer(p)
            if p == LocalPlayer then return end
            p.CharacterAdded:Connect(function() TryAttach(p) end)
            p:GetPropertyChangedSignal("Team"):Connect(function() TryAttach(p) end)
            if p.Character then TryAttach(p) end
        end

        for _, p in ipairs(Players:GetPlayers()) do SetupPlayer(p) end
        Players.PlayerAdded:Connect(SetupPlayer)
        task.spawn(function()
            while true do
                task.wait(5)
                for _, p in ipairs(Players:GetPlayers()) do TryAttach(p) end
            end
        end)

        LocalPlayer.CharacterAdded:Connect(function()
            task.wait(1)
            APV1_UpdateCustomButton()
            APV1_UpdateCircle()
            pcall(APV1_UpdateKillerTriangle)
            if APV1State.GuiVisible and APV1State.CustomGui then APV1State.CustomGui.Enabled = true end
        end)

        local lastAutoAttack = 0
        function W.KA_AutoAttack()
            if not VD.KILLER_AutoAttack then return end
            if GetRole() ~= "Killer" then return end
            local now = tick()
            if now - lastAutoAttack < (VD.KILLER_AutoAttackCooldown or 0.15) then return end
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not root then return end
            local closest, shortest = nil, VD.KILLER_AutoAttackRange or 12
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= LocalPlayer and TeamIs(plr, "Survivor") and plr.Character then
                    local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                    local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                    if hum and hrp and hum.Health > 35 then
                        local d = (hrp.Position - root.Position).Magnitude
                        if d <= shortest then shortest = d; closest = plr end
                    end
                end
            end
            if closest then
                lastAutoAttack = now
                pcall(function()
                    local attacks = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("Attacks")
                    local basic = attacks and attacks:FindFirstChild("BasicAttack")
                    if basic then basic:FireServer(false) end
                end)
            end
        end

        local lastAutoFlee = 0
        function W.SURV_AutoFlee()
            if not VD.SURV_AutoFlee then return end
            if GetRole() ~= "Survivor" then return end
            local now = tick()
            if now - lastAutoFlee < (VD.SURV_AutoFleeCooldown or 1.5) then return end
            local myChar = LocalPlayer.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local hum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myRoot or not hum or hum.Health <= 0 then return end
            local killerRoot = nil
            local nearest = math.huge
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= LocalPlayer and TeamIs(plr, "Killer") and plr.Character then
                    local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local d = (hrp.Position - myRoot.Position).Magnitude
                        if d < nearest then nearest = d; killerRoot = hrp end
                    end
                end
            end
            if not killerRoot then return end
            if nearest > (VD.SURV_AutoFleeDist or 40) then return end
            lastAutoFlee = now
            local bestPt, bestDist = nil, 0
            local mf = Workspace:FindFirstChild("Map")
            if mf then
                for _, obj in ipairs(mf:GetDescendants()) do
                    if obj:IsA("BasePart") and string.find(obj.Name, "^GeneratorPoint%d+$") then
                        local d = (obj.Position - killerRoot.Position).Magnitude
                        if d > bestDist then bestDist = d; bestPt = obj end
                    end
                end
            end
            if bestPt then
                pcall(function() myRoot.CFrame = bestPt.CFrame + Vector3.new(0, 5, 0) end)
                VD_Notify("Auto Flee", "Teleported away from killer!", 2)
            end
        end

        task.spawn(function()
            while true do
                local attackEnabled = VD.KILLER_AutoAttack == true
                local fleeEnabled = VD.SURV_AutoFlee == true
                if attackEnabled then pcall(W.KA_AutoAttack) end
                if fleeEnabled then pcall(W.SURV_AutoFlee) end
                task.wait((attackEnabled or fleeEnabled) and 0.1 or 1.25)
            end
        end)

