pcall(function() VeilV12DrawingAvailable = typeof(Drawing) == "table" and type(Drawing.new) == "function" end);

local VeilV12CirclePool = {};
local VeilV12TextPool = {};

local function VeilV12GetCircleFromPool(index)
    if not VeilV12CirclePool[index] then
        local circle = Drawing.new("Circle");
        circle.Thickness = 1.5;
        circle.Filled = false;
        circle.Visible = false;
        VeilV12CirclePool[index] = circle;
    end;
    return VeilV12CirclePool[index];
end;

local function VeilV12GetTextFromPool(index)
    if not VeilV12TextPool[index] then
        local text = Drawing.new("Text");
        text.Size = 14;
        text.Center = true;
        text.Outline = true;
        text.OutlineColor = Color3.new(0, 0, 0);
        text.Visible = false;
        VeilV12TextPool[index] = text;
    end;
    return VeilV12TextPool[index];
end;

