                    V.FOVMainRing = Drawing.new("Circle"); V.FOVMainRing.Color = ACCENT; V.FOVMainRing.Thickness = 1.6; V.FOVMainRing.Filled = false; V.FOVMainRing.Transparency = 0.85; V.FOVMainRing.Visible = false; V.FOVMainRing.NumSides = 90
                    V.FOVInnerRing = Drawing.new("Circle"); V.FOVInnerRing.Color = ACCENT; V.FOVInnerRing.Thickness = 1; V.FOVInnerRing.Filled = false; V.FOVInnerRing.Transparency = 0.35; V.FOVInnerRing.Visible = false; V.FOVInnerRing.NumSides = 90
                    V.FOVCrossLines = {}; for i = 1, 4 do local line = Drawing.new("Line"); line.Color = WHITE; line.Thickness = 1.5; line.Transparency = 0.9; line.Visible = false; V.FOVCrossLines[i] = line end
                    V.FOVTicks = {}; for i = 1, 4 do local line = Drawing.new("Line"); line.Color = ACCENT; line.Thickness = 2.2; line.Transparency = 0.95; line.Visible = false; V.FOVTicks[i] = line end
                    V.TrackerOuterRing = Drawing.new("Circle"); V.TrackerOuterRing.Color = BLACK; V.TrackerOuterRing.Thickness = 3; V.TrackerOuterRing.Filled = false; V.TrackerOuterRing.Transparency = 0.3; V.TrackerOuterRing.NumSides = 40; V.TrackerOuterRing.Visible = false
                    V.TrackerMainRing = Drawing.new("Circle"); V.TrackerMainRing.Color = ACCENT; V.TrackerMainRing.Thickness = 1.6; V.TrackerMainRing.Filled = false; V.TrackerMainRing.Transparency = 0.9; V.TrackerMainRing.NumSides = 40; V.TrackerMainRing.Visible = false
                    V.TrackerDotFill = Drawing.new("Circle"); V.TrackerDotFill.Color = ACCENT; V.TrackerDotFill.Thickness = 1; V.TrackerDotFill.Filled = true; V.TrackerDotFill.Transparency = 0.9; V.TrackerDotFill.Radius = 3; V.TrackerDotFill.NumSides = 20; V.TrackerDotFill.Visible = false
                    V.TrackerDotOutline = Drawing.new("Circle"); V.TrackerDotOutline.Color = BLACK; V.TrackerDotOutline.Thickness = 3; V.TrackerDotOutline.Filled = false; V.TrackerDotOutline.Transparency = 0.3; V.TrackerDotOutline.Radius = 6; V.TrackerDotOutline.NumSides = 20; V.TrackerDotOutline.Visible = false
                    V.TrackerLine = Drawing.new("Line"); V.TrackerLine.Color = ACCENT; V.TrackerLine.Thickness = 1.5; V.TrackerLine.Transparency = 0.6; V.TrackerLine.Visible = false
                end)
                local function Veil_IsSurvivorVeil(p)
                    if not p or not p.Team or not p.Team.Name then return false end
                    return string.find(string.lower(p.Team.Name), "survivor", 1, true) ~= nil
                end
                local function Veil_solvePitch(p, d, dy)
                    d = math.max(d, 0.1)
                    local s2 = p.v0 * p.v0
                    local root = s2 * s2 - p.g * (p.g * d * d + 2 * dy * s2)
                    if root < 0 then root = 0 end
                    local tanTheta = (s2 - math.sqrt(root)) / (p.g * d)
                    local theta = math.atan(tanTheta)
                    local t = d / (p.v0 * math.cos(theta))
                    return theta, t
                end
                local function Veil_getCharacterVelocity(char)
                    local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
                    if not root or not root:IsA("BasePart") then return Vector3.zero end
                    local now = os.clock()
                    local last = VeilState.velHistory[char]
                    local measured = Vector3.zero
                    if last and now - last.t > 0.02 then
                        measured = (root.Position - last.pos) / (now - last.t)
                        if measured.Magnitude > 150 then measured = last.smooth or Vector3.zero end
                    end
                    local smooth = last and last.smooth or measured
                    smooth = smooth:Lerp(measured, 0.65)
                    VeilState.velHistory[char] = { pos = root.Position, t = now, smooth = smooth }
                    if smooth.Magnitude < 1 then return Vector3.zero end
                    return Vector3.new(smooth.X, 0, smooth.Z)
                end
                local VeilV2PlayerRemoving = Players.PlayerRemoving:Connect(function(p)
                    if p.Character then VeilState.velHistory[p.Character] = nil end
                end)
                local function Veil_HideFOV()
                    local V = VeilVisuals
                    local OFF = Vector2.new(-9999, -9999)
                    if V.FOVOuterRing then V.FOVOuterRing.Visible = false; V.FOVOuterRing.Position = OFF; V.FOVOuterRing.Radius = 0; V.FOVOuterRing.Transparency = 1 end
                    if V.FOVMainRing then V.FOVMainRing.Visible = false; V.FOVMainRing.Position = OFF; V.FOVMainRing.Radius = 0; V.FOVMainRing.Transparency = 1 end
                    if V.FOVInnerRing then V.FOVInnerRing.Visible = false; V.FOVInnerRing.Position = OFF; V.FOVInnerRing.Radius = 0; V.FOVInnerRing.Transparency = 1 end
                    if V.FOVCrossLines then for _, s in ipairs(V.FOVCrossLines) do s.Visible = false; s.From = OFF; s.To = OFF end end
                    if V.FOVTicks then for _, s in ipairs(V.FOVTicks) do s.Visible = false; s.From = OFF; s.To = OFF end end
                end
                local function Veil_HideTracker()
                    local V = VeilVisuals
                    local OFF = Vector2.new(-9999, -9999)
                    if V.TrackerOuterRing then V.TrackerOuterRing.Visible = false; V.TrackerOuterRing.Position = OFF; V.TrackerOuterRing.Radius = 0; V.TrackerOuterRing.Transparency = 1 end
                    if V.TrackerMainRing then V.TrackerMainRing.Visible = false; V.TrackerMainRing.Position = OFF; V.TrackerMainRing.Radius = 0; V.TrackerMainRing.Transparency = 1 end
                    if V.TrackerDotFill then V.TrackerDotFill.Visible = false; V.TrackerDotFill.Position = OFF; V.TrackerDotFill.Radius = 0 end
                    if V.TrackerDotOutline then V.TrackerDotOutline.Visible = false; V.TrackerDotOutline.Position = OFF; V.TrackerDotOutline.Radius = 0 end
                    if V.TrackerLine then V.TrackerLine.Visible = false; V.TrackerLine.From = OFF; V.TrackerLine.To = OFF end
                end
                local function Veil_HideAllVisuals() Veil_HideFOV(); Veil_HideTracker() end
                local function Veil_UpdateFOVVisuals(center)
                    local V = VeilVisuals
                    if not V.FOVOuterRing then return end
                    local radius = VD.VeilV2FOV or 150
                    local t = tick()
                    local pulse = (math.sin(t * 3) + 1) * 0.5
                    local slowPulse = (math.sin(t * 1.2) + 1) * 0.5
                    V.FOVOuterRing.Position = center; V.FOVOuterRing.Radius = radius + 2; V.FOVOuterRing.Transparency = 0.3 + pulse * 0.15; V.FOVOuterRing.Visible = true
                    V.FOVMainRing.Position = center; V.FOVMainRing.Radius = radius; V.FOVMainRing.Transparency = 0.7 + pulse * 0.25; V.FOVMainRing.Visible = true
                    V.FOVInnerRing.Position = center; V.FOVInnerRing.Radius = radius - 10; V.FOVInnerRing.Transparency = 0.25 + slowPulse * 0.2; V.FOVInnerRing.Visible = true
                    local gap, armLen = 4, 12
                    V.FOVCrossLines[1].From = Vector2.new(center.X, center.Y - gap); V.FOVCrossLines[1].To = Vector2.new(center.X, center.Y - gap - armLen); V.FOVCrossLines[1].Visible = true
                    V.FOVCrossLines[2].From = Vector2.new(center.X, center.Y + gap); V.FOVCrossLines[2].To = Vector2.new(center.X, center.Y + gap + armLen); V.FOVCrossLines[2].Visible = true
                    V.FOVCrossLines[3].From = Vector2.new(center.X - gap, center.Y); V.FOVCrossLines[3].To = Vector2.new(center.X - gap - armLen, center.Y); V.FOVCrossLines[3].Visible = true
                    V.FOVCrossLines[4].From = Vector2.new(center.X + gap, center.Y); V.FOVCrossLines[4].To = Vector2.new(center.X + gap + armLen, center.Y); V.FOVCrossLines[4].Visible = true
                    local tickLen = 9
                    for i = 1, 4 do
                        local angle = (i - 1) * math.pi / 2
                        local dirX, dirY = math.cos(angle), math.sin(angle)
                        V.FOVTicks[i].From = Vector2.new(center.X + dirX * radius, center.Y + dirY * radius)
                        V.FOVTicks[i].To = Vector2.new(center.X + dirX * (radius - tickLen), center.Y + dirY * (radius - tickLen))
                        V.FOVTicks[i].Visible = true
                    end
                end
                local function Veil_UpdateTrackerVisuals(targetScreenPos, dist)
                    local V = VeilVisuals
                    if not V.TrackerOuterRing then return end
                    local t = tick()
                    local pulse = (math.sin(t * 4) + 1) * 0.5
                    local baseRadius = math.clamp(1000 / math.max(dist, 1), 20, 48)
                    V.TrackerOuterRing.Position = targetScreenPos; V.TrackerOuterRing.Radius = baseRadius + 3; V.TrackerOuterRing.Transparency = 0.25 + pulse * 0.15; V.TrackerOuterRing.Visible = true
                    V.TrackerMainRing.Position = targetScreenPos; V.TrackerMainRing.Radius = baseRadius; V.TrackerMainRing.Transparency = 0.75 + pulse * 0.2; V.TrackerMainRing.Visible = true
                    V.TrackerDotFill.Position = targetScreenPos; V.TrackerDotFill.Radius = 2.5 + pulse * 1.2; V.TrackerDotFill.Transparency = 0.85 + pulse * 0.15; V.TrackerDotFill.Visible = true
                    V.TrackerDotOutline.Position = targetScreenPos; V.TrackerDotOutline.Radius = 5 + pulse * 1.5; V.TrackerDotOutline.Transparency = 0.35; V.TrackerDotOutline.Visible = true
                end
                local function Veil_UpdateAimbot()
                    if GetRole() ~= "Killer" then
                        VeilState.target = nil; VeilState.lookVector = nil
                        Veil_HideAllVisuals(); return
                    end
                    local cam = Workspace.CurrentCamera
                    if not cam then return end
                    local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
                    if VD.VeilV2ShowFOV and VD.VeilV2Enabled then Veil_UpdateFOVVisuals(center)
                    else Veil_HideFOV() end
                    if not VD.VeilV2Enabled then VeilState.target = nil; VeilState.lookVector = nil; Veil_HideTracker(); return end
                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    local nearest, nearestPart = nil, nil
                    local bestDist = VD.VeilV2FOV or 150
                    local bestStudDist = VD.VeilV2MaxDist or 500
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LocalPlayer and Veil_IsSurvivorVeil(p) and p.Character then
                            local pc = p.Character
                            local isDown = pc:GetAttribute("Knocked") == true or pc:GetAttribute("HookProgressDepleting") == true
                            if not isDown then
                                local hum = pc:FindFirstChildOfClass("Humanoid")
                                local targetPart = pc:FindFirstChild("UpperTorso") or pc:FindFirstChild("Torso") or pc:FindFirstChild("HumanoidRootPart")
                                if hum and hum.Health > 0 and targetPart then
                                    local sp, on = cam:WorldToViewportPoint(targetPart.Position)
                                    if on and sp.Z > 0 then
                                        local sd = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                        if sd < bestDist then
                                            local studDist = (targetPart.Position - hrp.Position).Magnitude
                                            if studDist <= bestStudDist then bestDist = sd; nearest = p; nearestPart = targetPart end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if nearest and nearest.Character and nearestPart then
                        local tp = nearestPart.Position
                        local hand = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")
                        local origin = (hand and hand:IsA("BasePart")) and hand.Position or hrp.Position
                        local dir = tp - origin
                        local dist = dir.Magnitude
                        if dist > 0.1 and dist <= (VD.VeilV2MaxDist or 500) then
                            local isAuraActive = char:GetAttribute("special") == true
                            local prof
                            if isAuraActive then
                                prof = { v0 = VD.VeilV2AuraSpearSpeed or 165, g = VD.VeilV2AuraSpearGravity or 96.5, windup = 0.10, latency = 0.04, maxlead = 25, scale = VD.VeilV2LeadMultiplier or 1.4 }
                            else
                                prof = { v0 = VD.VeilV2SpearSpeed or 165, g = VD.VeilV2Gravity or 103, windup = 0.10, latency = 0.04, maxlead = 45, scale = VD.VeilV2LeadMultiplier or 1.4 }
                            end
                            local aimPoint = tp
                            if VD.VeilV2AutoPredict then
                                local vel = Veil_getCharacterVelocity(nearest.Character)
                                if vel.Magnitude > 0.5 then
                                    local h0 = Vector3.new(dir.X, 0, dir.Z)
                                    local _, tFlight = Veil_solvePitch(prof, h0.Magnitude, dir.Y)
                                    local ping = 0.08
                                    pcall(function() ping = math.clamp(LocalPlayer:GetNetworkPing(), 0, 0.35) end)
                                    local delay = tFlight + prof.windup + ping + prof.latency
                                    for _ = 1, 2 do
                                        local lead = vel * delay * prof.scale
                                        local maxLead = math.clamp(dist * 0.6, 3, prof.maxlead)
                                        if lead.Magnitude > maxLead then lead = lead.Unit * maxLead end
                                        aimPoint = tp + lead
                                        local ad = aimPoint - origin
                                        local ah = Vector3.new(ad.X, 0, ad.Z)
                                        local _, t2 = Veil_solvePitch(prof, math.max(ah.Magnitude, 0.1), ad.Y)
                                        delay = t2 + prof.windup + ping + prof.latency
                                    end
                                end
                            end
                            local adir = aimPoint - origin
                            local ah = Vector3.new(adir.X, 0, adir.Z)
                            local ahDist = ah.Magnitude
                            local pitch = Veil_solvePitch(prof, ahDist, adir.Y)
                            if ahDist > 0.001 then VeilState.lookVector = ah.Unit * math.cos(pitch) + Vector3.new(0, math.sin(pitch), 0)
                            else VeilState.lookVector = adir.Unit end
                            VeilState.target = nearest
                            if VD.VeilV2ShowTracker then
                                local sp, vis = cam:WorldToViewportPoint(tp)
                                if vis and sp.Z > 0 then
                                    local screenDist = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                    if screenDist <= (VD.VeilV2FOV or 150) + 100 then
                                        Veil_UpdateTrackerVisuals(Vector2.new(sp.X, sp.Y), dist)
                                        local bottomCenter = Vector2.new(center.X, cam.ViewportSize.Y)
                                        local V = VeilVisuals
                                        if V.TrackerLine then V.TrackerLine.From = bottomCenter; V.TrackerLine.To = Vector2.new(sp.X, sp.Y); V.TrackerLine.Visible = true end
                                    else Veil_HideTracker() end
                                end
                            else Veil_HideTracker() end
                        end
                    else VeilState.target = nil; VeilState.lookVector = nil; Veil_HideTracker() end
                end

            local function VeilV2_setupInterceptor()
                if VeilV2HookState.remoteHooked then return end
                if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" or type(checkcaller) ~= "function" then return end
                task.spawn(function()
                    pcall(function()
                        local oldNamecall
                        oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
                            local method = getnamecallmethod()
                            if not checkcaller() and method == "FireServer" then
                                if self.Name == "Spearthrow" and VeilV2RuntimeToken.active and W.MAWWW_VeilV2RuntimeToken == VeilV2RuntimeToken and VD.VeilV2Enabled and typeof(VeilState.lookVector) == "Vector3" and GetRole() == "Killer" then
                                    local args = {...}
                                    if typeof(args[1]) == "Vector3" then args[1] = VeilState.lookVector end
                                    return oldNamecall(self, unpack(args))
                                end
                            end
                            return oldNamecall(self, ...)
                        end)
                        VeilV2HookState.remoteHooked = true
                    end)
                end)
            end

            VeilV2_setupInterceptor()
            VeilV2Connection = RunService.RenderStepped:Connect(function()
                if not VeilV2Connection then return end
                pcall(Veil_UpdateAimbot)
            end)

            local function VeilV2RemoveDrawings(obj)
                if type(obj) == "table" then
                    for _, child in pairs(obj) do VeilV2RemoveDrawings(child) end
                elseif obj ~= nil then
                    pcall(function() obj:Remove() end)
                end
            end
            local V2API = {
                setEnabled = function(v)
                    local enabled = v == true
                    if enabled then
                        -- Disable V1 first, including its charging state and drawings.
                        if W.MAWWW_VeilV1_API and type(W.MAWWW_VeilV1_API.setEnabled) == "function" then
                            pcall(function() W.MAWWW_VeilV1_API.setEnabled(false) end)
                        else
                            VD.VeilEnabled = false
                        end
                    end
                    VD.VeilV2Enabled = enabled
                    if not enabled then
                        pcall(Veil_HideAllVisuals)
                        VeilState.target = nil
                        VeilState.lookVector = nil
                    end
                end,
                setFOV = function(v) VD.VeilV2FOV = tonumber(v) or VD.VeilV2FOV end,
                setMaxDistance = function(v) VD.VeilV2MaxDist = tonumber(v) or VD.VeilV2MaxDist end,
                setSpeed = function(v) VD.VeilV2SpearSpeed = tonumber(v) or VD.VeilV2SpearSpeed end,
                setGravity = function(v) VD.VeilV2Gravity = tonumber(v) or VD.VeilV2Gravity end,
                setAuraSpeed = function(v) VD.VeilV2AuraSpearSpeed = tonumber(v) or VD.VeilV2AuraSpearSpeed end,
                setAuraGravity = function(v) VD.VeilV2AuraSpearGravity = tonumber(v) or VD.VeilV2AuraSpearGravity end,
                setLead = function(v) VD.VeilV2LeadMultiplier = tonumber(v) or VD.VeilV2LeadMultiplier end,
                setAutoPredict = function(v) VD.VeilV2AutoPredict = v == true end,
                setTracker = function(v) VD.VeilV2ShowTracker = v == true end,
                setShowFOV = function(v) VD.VeilV2ShowFOV = v == true end,
                cleanup = function()
                    VD.VeilV2Enabled = false
                    VeilV2RuntimeToken.active = false
                    if VeilV2Connection then pcall(function() VeilV2Connection:Disconnect() end); VeilV2Connection = nil end
                    if VeilV2PlayerRemoving then pcall(function() VeilV2PlayerRemoving:Disconnect() end); VeilV2PlayerRemoving = nil end
                    pcall(Veil_HideAllVisuals)
                    VeilV2RemoveDrawings(VeilVisuals)
                    VeilState.target = nil
                    VeilState.lookVector = nil
                    if W.MAWWW_VeilV2RuntimeToken == VeilV2RuntimeToken then W.MAWWW_VeilV2RuntimeToken = nil end
                end,
            }
            W.MAWWW_VeilV2_API = V2API
            W.N3K0P01_VeilV2_API = nil
            local innerW = type(W.W) == "table" and W.W or nil
            if innerW then innerW.MAWWW_VeilV2_API = V2API; innerW.N3K0P01_VeilV2_API = nil end
        end



-- Dedicated Silent Pistol/TOF V3 reference engine. This is the sole pistol V3 implementation.
do
    local env = getgenv()
    local VD = env.VD or {}
    local W = env.W or {}
    env.VD, env.W = VD, W

    -- Cache Auto Load intent, but start the source engine only after V1/V2 are constructed.
    W.MAWWW_PistolV3ShouldAutoEnable = VD.SilentPistolV3Enabled == true
    -- Bridge the source-module state into the main hub environment used by its UI callbacks.
    getgenv().MAWWW_PistolV3ShouldAutoEnable = W.MAWWW_PistolV3ShouldAutoEnable
    if type(W.SetToFSilentAim) == "function" then pcall(function() W.SetToFSilentAim(false) end) end
    VD.SilentPistolV3Enabled = W.MAWWW_PistolV3ShouldAutoEnable == true
    if W.MAWWW_PistolV3ShouldAutoEnable == true then
        VD.TOFV1_SilentAim = false
        VD.SilentPistolV2Enabled = false
    end
    VD.TOFV3SRC_SilentAim = false
    VD.TOFV3SRC_TargetMode = VD.TOFV3_TargetMode or "Killer"
    VD.TOFV3SRC_Key = VD.TOFV3_Key or "Q"
    VD.TOFV3SRC_FOV = tonumber(VD.TOFV3_FOV) or 150
    VD.TOFV3SRC_MaxDistance = tonumber(VD.TOFV3_MaxDist) or 300
    VD.TOFV3SRC_LeadMultiplier = tonumber(VD.TOFV3_LeadMultiplier) or 1.4
    VD.TOFV3SRC_PingLead = tonumber(VD.TOFV3_PingLead) or 1.0
    VD.TOFV3SRC_Laser = VD.TOFV3_ShowLaser ~= false
    VD.TOFV3SRC_ShowFOV = VD.TOFV3_ShowFOV ~= false
    VD.TOFV3SRC_WallCheck = VD.TOFV3_WallCheck == true
    VD.TOFV3SRC_BlockKnocked = VD.TOFV3_BlockKnocked ~= false
    VD.TOFV3SRC_AutoPredict = VD.TOFV3_AutoPredict ~= false
    VD.TOFV3SRC_SmartPredict = VD.TOFV3SRC_SmartPredict ~= false
    VD.TOFV3SRC_UseTravel = VD.TOFV3SRC_UseTravel ~= false
    VD.TOFV3SRC_UseSnap = VD.TOFV3SRC_UseSnap ~= false
    VD.TOFV3SRC_LineSmooth = tonumber(VD.TOFV3SRC_LineSmooth) or 70
end

do
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local TweenService = game:GetService("TweenService")
local LocalPlayer = Players.LocalPlayer

getgenv().VD = getgenv().VD or {}
getgenv().W = getgenv().W or {}
local VD = getgenv().VD
local W = getgenv().W
local ToFRuntimeToken = tick()
VD.TOFV3SRC_RuntimeToken = ToFRuntimeToken
local function ToF_IsCurrentRuntime()
    return VD.TOFV3SRC_RuntimeToken == ToFRuntimeToken
end

local function VD_Notify(title, content, duration)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = tostring(title), Text = tostring(content), Duration = duration or 2,
        })
    end)
end

local function TeamIs(plr, role)
    if not plr or not plr.Team or not plr.Team.Name then return false end
    local tn = string.lower(plr.Team.Name)
    if role == "Killer" then return string.find(tn, "killer", 1, true) ~= nil end
    if role == "Survivor" then return string.find(tn, "survivor", 1, true) ~= nil end
    return false
end

VD.TOFV3SRC_SilentAim = VD.TOFV3SRC_SilentAim or false
VD.TOFV3SRC_TargetMode = VD.TOFV3SRC_TargetMode or "KILLER"
VD.TOFV3SRC_Key = VD.TOFV3SRC_Key or "Q"
VD.TOFV3SRC_FOV = VD.TOFV3SRC_FOV or 250
VD.TOFV3SRC_MaxDistance = VD.TOFV3SRC_MaxDistance or 500
VD.TOFV3SRC_AimPart = VD.TOFV3SRC_AimPart or "Torso"
VD.TOFV3SRC_LeadMultiplier = VD.TOFV3SRC_LeadMultiplier or 1.4
VD.TOFV3SRC_PredictHorizOnly = VD.TOFV3SRC_PredictHorizOnly ~= false
VD.TOFV3SRC_AutoPredict = VD.TOFV3SRC_AutoPredict ~= false
VD.TOFV3SRC_SmartPredict = VD.TOFV3SRC_SmartPredict ~= false
VD.TOFV3SRC_Windup = VD.TOFV3SRC_Windup or 0.3
VD.TOFV3SRC_WindupAutoOn = VD.TOFV3SRC_WindupAutoOn ~= false
VD.TOFV3SRC_LineSmooth = VD.TOFV3SRC_LineSmooth or 70
VD.TOFV3SRC_UseSnap = VD.TOFV3SRC_UseSnap ~= false
VD.TOFV3SRC_UseTravel = VD.TOFV3SRC_UseTravel ~= false
VD.TOFV3SRC_AntiSalto = VD.TOFV3SRC_AntiSalto or false

do
    local ToFState = {
        Connection = nil, LaserBeam = nil, TargetGui = nil,
        TargetDragConnections = {}, TargetModeButtons = {},
        InputBegan = nil, InputEnded = nil, TouchInput = nil,
        IsAiming = false, SavedUIPos = UDim2.new(0, 12, 0.5, -80),
        SCPCache = {}, SCPCacheTimer = 0, FOVGui = nil, FOVCircle = nil
    }
    local ToFKeyCodes = {
        None=nil, Q=Enum.KeyCode.Q, E=Enum.KeyCode.E, R=Enum.KeyCode.R,
        T=Enum.KeyCode.T, F=Enum.KeyCode.F, G=Enum.KeyCode.G,
        H=Enum.KeyCode.H, J=Enum.KeyCode.J, K=Enum.KeyCode.K,
        L=Enum.KeyCode.L, X=Enum.KeyCode.X, Z=Enum.KeyCode.Z
    }
    VD.TOFV3SRC_Laser        = VD.TOFV3SRC_Laser        ~= false
    VD.TOFV3SRC_WallCheck    = VD.TOFV3SRC_WallCheck    ~= false
    VD.TOFV3SRC_BlockKnocked = VD.TOFV3SRC_BlockKnocked ~= false
    VD.TOFV3SRC_TargetMode   = VD.TOFV3SRC_TargetMode   or "Killer"
    if VD.TOFV3SRC_TargetMode == "KILLER" or VD.TOFV3SRC_TargetMode == "killer" then VD.TOFV3SRC_TargetMode = "Killer" end
    if VD.TOFV3SRC_TargetMode == "SURVIVOR" or VD.TOFV3SRC_TargetMode == "survivor" then VD.TOFV3SRC_TargetMode = "Survivors" end

    local function ToF_IsDowned(c)
        if not c then return true end
        local hrp = c:FindFirstChild("HumanoidRootPart"); if not hrp then return true end
        local h = c:FindFirstChildOfClass("Humanoid"); if h and h.Health<=0 then return true end
        if c:GetAttribute("Knocked")==true then return true end
        if c:GetAttribute("IsHooked")==true then return true end
        if c:GetAttribute("IsCarried")==true then return true end
        return false
    end
    local function ToF_GameWouldBlock()
        local c = LocalPlayer.Character
        if not c then return false end
        if LocalPlayer:GetAttribute("IsDead") then return true end
        if c:GetAttribute("IsCarried") or c:GetAttribute("IsHooked") or c:GetAttribute("Knocked") then return true end
        local h = c:FindFirstChildOfClass("Humanoid")
        if h and h.Health < h.MaxHealth * 0.5 then return true end
        return false
    end
    local function ToF_IsBlocked()
        if VD.TOFV3SRC_BlockKnocked == false then return false end
        local c = LocalPlayer.Character
        if not c then return true end
        return ToF_IsDowned(c)
    end
    local function ToF_GetEvent()
        local r = ReplicatedStorage:FindFirstChild("Remotes")
        local i = r and r:FindFirstChild("Items")
        local t = i and i:FindFirstChild("Twist of Fate")
        local f = t and t:FindFirstChild("Fire")
        if f and f:IsA("RemoteEvent") then return f end
        return nil
    end
    local function ToF_GetGun()
        local c = LocalPlayer.Character
        if not c then return nil end
        local b = c:FindFirstChild("Twist of Fate", true)
        if not b then return nil end
        local ra = b:FindFirstChild("Right Arm")
        if ra then
            local g = ra:FindFirstChild("gun"); if g then return g end
            local e = ra:FindFirstChild("EmperorGun"); if e then return e end
        end
        return b
    end
    local function ToF_IsVisible(op, tp, tc)
        local d = tp - op; local dist = d.Magnitude
        if dist < 0.1 then return true end
        local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude
        local ex = {}
        local lc = LocalPlayer.Character
        if lc then table.insert(ex, lc) end
        if tc and tc ~= lc then table.insert(ex, tc) end
        if ToFState.LaserBeam then table.insert(ex, ToFState.LaserBeam) end
        rp.FilterDescendantsInstances = ex
        return workspace:Raycast(op, d.Unit * dist, rp) == nil
    end
    local function ToF_GetSCPs()
        if tick() - ToFState.SCPCacheTimer < 0.5 then return ToFState.SCPCache end
        local nt = {}
        local mf = workspace:FindFirstChild("Map")
        if mf then
            for _, c in pairs(mf:GetDescendants()) do
                if c:IsA("Model") then
                    local a = c:GetAttributes()
                    if c:GetAttribute("CorpseCreated0492") or next(a) ~= nil then
                        local r = c:FindFirstChild("HumanoidRootPart"); if r then table.insert(nt, r) end
                    end
                end
            end
        end
        ToFState.SCPCache = nt; ToFState.SCPCacheTimer = tick()
        return nt
    end

    local ToF_Track = setmetatable({}, { __mode = "k" })
    local function ToF_Ping()
        local p = 0.08
        pcall(function() p = math.clamp(LocalPlayer:GetNetworkPing(), 0, 0.35) end)
        return p
    end

    local ToF_Shot, ToF_LastPred = nil, nil
    local ToF_LastReal = nil
    local ToF_RawMode = false
    local ToF_LastVel, ToF_LastMult, ToF_LastBase, ToF_LastVB = nil, 1, 0, 200
    local function ToF_Band(d) return d < 15 and "N" or (d < 35 and "M" or "F") end
    local function ToF_Delay()
        if tonumber(VD.TOFV3SRC_DelayAuto) then
            return math.clamp(VD.TOFV3SRC_DelayAuto, 0.05, 1.5)
        end
        local pingScale = math.clamp(tonumber(VD.TOFV3SRC_PingLead) or 1, 0, 2)
        return (tonumber(VD.TOFV3SRC_Windup) or 0.3) + ToF_Ping() * pingScale
    end
    local ToF_BulletHooked = setmetatable({}, { __mode = "k" })
    local function ToF_HookBullet(r)
        if ToF_BulletHooked[r] then return end
        ToF_BulletHooked[r] = true
        r.OnClientEvent:Connect(function(origin, endp, spd)
            if not ToF_IsCurrentRuntime() then return end
            local sh = ToF_Shot
            if not sh or sh.used or typeof(origin) ~= "Vector3" or typeof(endp) ~= "Vector3" then return end
            local dt = os.clock() - sh.t
            if dt < 0.05 or dt > 1.6 then return end
            local ch = LocalPlayer.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not hrp or (origin - hrp.Position).Magnitude > 15 then return end
            sh.used = true
            if type(spd) == "number" and spd > 5 then VD.TOFV3SRC_BulletSpeed = spd end
            local cur = tonumber(VD.TOFV3SRC_DelayAuto)
            VD.TOFV3SRC_DelayAuto = cur and (cur + (dt - cur) * 0.3) or dt
            if sh.real and sh.aim and sh.tc and sh.vel then
                task.delay(0.1, function()
                    local root = sh.tc:FindFirstChild("HumanoidRootPart") or sh.tc:FindFirstChild("Torso")
                    if not (root and root.Parent) then return end
                    local real, aim = sh.real, sh.aim
                    local L = Vector3.new(aim.X - real.X, 0, aim.Z - real.Z)
                    local D = Vector3.new(root.Position.X - real.X, 0, root.Position.Z - real.Z)
                    local vh = Vector3.new(sh.vel.X, 0, sh.vel.Z)
                    if L.Magnitude <= 2 or vh.Magnitude <= 2 or D.Magnitude < 0.5 then return end
                    if D:Dot(vh) <= 0 or D.Unit:Dot(vh.Unit) < 0.6 then return end
                    local vb = sh.vb or 200
                    local travel = (sh.d or 0) / vb
                    if VD.TOFV3SRC_UseTravel and travel >= 0.1 then
                        local tTrue = D:Dot(vh) / vh:Dot(vh)
                        local tUsed = tTrue / math.max(sh.mult or 1, 0.2)
                        local kTrue = (tUsed - (sh.base or 0)) / travel
                        local k = tonumber(VD.TOFV3SRC_TravelK) or 0.5
                        VD.TOFV3SRC_TravelK = math.clamp(k + (math.clamp(kTrue, 0, 2.5) - k) * 0.25, 0, 2.5)
                    else
                        local ratio = math.clamp(D:Dot(L) / L:Dot(L), 0, 2.5)
                        local key = "TOFV3SRC_HitGain" .. (sh.band or "M")
                        local g = tonumber(VD[key]) or 1
                        VD[key] = math.clamp(g + (g * ratio - g) * 0.3, 0.3, 2)
                    end
                end)
            end
        end)
    end
    local function ToF_IsRemote(d) return d:IsA("RemoteEvent") or d.ClassName == "UnreliableRemoteEvent" end
    for _, d in ipairs(ReplicatedStorage:GetDescendants()) do
        if d.Name == "VisualizeBullet" and ToF_IsRemote(d) then pcall(ToF_HookBullet, d) end
    end
    ReplicatedStorage.DescendantAdded:Connect(function(d)
        if not ToF_IsCurrentRuntime() then return end
        if d.Name == "VisualizeBullet" and ToF_IsRemote(d) then pcall(ToF_HookBullet, d) end
    end)

    local function ToF_ArcDisp(vel, omega, T)
        local N = 6
        local dt = T / N
        local rot = CFrame.Angles(0, omega * dt, 0)
        local pos, dir = Vector3.zero, vel
        for _ = 1, N do
            pos = pos + dir * dt
            dir = rot:VectorToWorldSpace(dir)
        end
        return pos
    end
    local function ToF_ConfEff(S)
        if math.abs(S.omega or 0) > 0.35 then return math.max(S.conf, 0.6) end
        return S.conf
    end
    local ToF_SnapBuf = {}
    task.spawn(function()
        local r = ReplicatedStorage:WaitForChild("Remotes", 15)
        r = r and r:WaitForChild("Mechanics", 15)
        r = r and r:WaitForChild("NetRemote", 15)
        if not r then return end
        r.OnClientEvent:Connect(function(pkt)
            if not VD.TOFV3SRC_SilentAim then return end
            if type(pkt) ~= "table" or pkt.kind ~= "Snapshot" then return end
            local dd = pkt.data
            if type(dd) ~= "table" or type(dd.players) ~= "table" or type(dd.t) ~= "number" then return end
            local nowc = os.clock()
            for _, pe in pairs(dd.players) do
                if type(pe) == "table" and typeof(pe.pos) == "Vector3" and type(pe.id) == "number" then
                    local e = ToF_SnapBuf[pe.id]
                    if not e then e = { s = {} }; ToF_SnapBuf[pe.id] = e end
                    local sb = e.s
                    local last = sb[#sb]
                    if not last or dd.t > last.ts then
                        if last and (pe.pos - last.pos).Magnitude / math.max(dd.t - last.ts, 0.001) > 250 then
                            e.s = {}; sb = e.s
                        end
                        sb[#sb + 1] = { ts = dd.t, pos = pe.pos, tl = nowc }
                        while #sb > 24 do table.remove(sb, 1) end
                    end
                end
            end
        end)
    end)
    local function ToF_GetSnap(char)
        local pl = char and Players:GetPlayerFromCharacter(char)
        local e = pl and ToF_SnapBuf[pl.UserId]
        if not e then return nil end
        local sb = e.s
        local n = #sb
        if n < 3 then return nil end
        local last = sb[n]
        if os.clock() - last.tl > 0.4 then return nil end
        local function seg(t0, t1)
            local a, b
            for i = 1, n do
                local x = sb[i]
                local age = last.ts - x.ts
                if age >= t0 and age <= t1 then
                    if not a then a = x end
                    b = x
                end
            end
            if a and b and b.ts - a.ts >= 0.07 then
                local v = (b.pos - a.pos) / (b.ts - a.ts)
                return Vector3.new(v.X, 0, v.Z), v.Y
            end
        end
        local w0, vy = seg(0, 0.15)
        if not w0 then return nil end
        local vNow = seg(0, 0.1)
        local vs = vNow or w0
        if vs.Magnitude < 1 then vs = Vector3.zero end
        local w1 = seg(0.15, 0.3)
        local w2 = seg(0.3, 0.45)
        local conf, omega = 1, 0
        local function turn(a, b)
            if not (a and b) or a.Magnitude < 2 or b.Magnitude < 2 then return nil end
            local phi = math.atan2(a.Z, a.X) - math.atan2(b.Z, b.X)
            if phi > math.pi then phi = phi - 2 * math.pi elseif phi < -math.pi then phi = phi + 2 * math.pi end
            return phi
        end
        local flips = 0
        if w0 and w1 and w0.Magnitude > 2 and w1.Magnitude > 2 and w0.Unit:Dot(w1.Unit) < 0.2 then flips = flips + 1 end
        if w1 and w2 and w1.Magnitude > 2 and w2.Magnitude > 2 and w1.Unit:Dot(w2.Unit) < 0.2 then flips = flips + 1 end
        if flips >= 2 then
            local net = seg(0, 0.45)
            vs = net or Vector3.zero
            if vs.Magnitude < 1.5 then vs = Vector3.zero end
            return { pos = last.pos, tl = last.tl, vel = vs, vy = vy or 0, conf = 0.6, omega = 0 }
        end
        local p1, p2 = turn(w1, w0), turn(w2, w1)
        if p1 and p2 and math.abs(p1) > 0.08 and math.abs(p2) > 0.08 then
            if p1 * p2 > 0 then
                omega = math.clamp((p1 + p2) / 2 / 0.15, -8, 8)
            else
                conf = 0.5
            end
        end
        return { pos = last.pos, tl = last.tl, vel = vs, vy = vy or 0, conf = conf, omega = omega }
    end

    local function ToF_SampleVel(char)
        local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
        if not (root and root:IsA("BasePart")) then return end
        local S = ToF_Track[char]
        if not S then
            S = { s = {}, pend = {}, mAuto = 1, conf = 1, omega = 0, vShort = Vector3.zero, lead = Vector3.zero, leadT = 0, lastPend = 0 }
            ToF_Track[char] = S
        end
        local now, pos = os.clock(), root.Position
        local s = S.s
        local last = s[#s]
        if last then
            if now - last.t < 0.004 then return end
            if (pos - last.pos).Magnitude / (now - last.t) > 200 then
                S.s = {}; S.pend = {}; S.lead = Vector3.zero; s = S.s
            end
        end
        s[#s + 1] = { t = now, pos = pos }
        while #s > 2 and now - s[1].t > 0.45 do table.remove(s, 1) end

        local function seg(t0, t1)
            local a, b
            for i = 1, #s do
                local e = s[i]
                if e.t >= now - t1 and e.t <= now - t0 then
                    if not a then a = e end
                    b = e
                end
            end
            if a and b and b.t - a.t >= 0.04 then
                local v = (b.pos - a.pos) / (b.t - a.t)
                return Vector3.new(v.X, 0, v.Z), v.Y
            end
        end
        local vs, vy = seg(0, 0.15)
        vs = vs or Vector3.zero
        S.vy = vy or 0
        if vs.Magnitude < 1 then vs = Vector3.zero end
        local vl = seg(0.15, 0.4)
        local conf = 1
        if vl and vs.Magnitude > 1 and vl.Magnitude > 1 then
            conf = math.clamp(vs.Unit:Dot(vl.Unit), 0.25, 1)
        end
        S.vShort, S.conf = vs, conf
        if vl and vs.Magnitude > 2 and vl.Magnitude > 2 then
            local phi = math.atan2(vl.Z, vl.X) - math.atan2(vs.Z, vs.X)
            if phi > math.pi then phi = phi - 2 * math.pi elseif phi < -math.pi then phi = phi + 2 * math.pi end
            S.omega = S.omega * 0.5 + math.clamp(phi / 0.2, -8, 8) * 0.5
        else
            S.omega = S.omega * 0.8
        end

        S.vIn, S.stopping, S.air = nil, false, false
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            local md = hum.MoveDirection
            local mdh = Vector3.new(md.X, 0, md.Z)
            if mdh.Magnitude > 0.1 then
                if not S.hadInput then S.inT0 = now; S.holdT0 = now end
                local dirNow = mdh.Unit
                if S.inDir and S.inDir:Dot(dirNow) < 0.9 then S.inT0 = now end
                S.inDir = dirNow
                S.hadInput = true
                local wsNow = hum.WalkSpeed
                if wsNow > 0 and (now - (S.holdT0 or now)) > 0.15 and vs.Magnitude < 0.3 * wsNow then
                    if not S.blocked then S.blocked = true; S.blockDir = dirNow end
                elseif wsNow > 0 and vs.Magnitude >= 0.5 * wsNow then
                    S.blocked = false
                end
                if vs.Magnitude > 2 then S.mdWorks = true end
                if vs.Magnitude > 2 then
                    S.vIn = mdh.Unit * vs.Magnitude
                elseif hum.WalkSpeed > 0 then
                    S.vIn = mdh.Unit * hum.WalkSpeed * 0.6
                end
            else
                S.hadInput = false
                S.blocked, S.inDir = false, nil
                if S.mdWorks then S.stopping = true end
            end
            local okf, fm = pcall(function() return hum.FloorMaterial end)
            S.air = okf and fm == Enum.Material.Air
        end

        local pend = S.pend
        if VD.TOFV3SRC_SmartPredict then
            if vs.Magnitude > 2 and conf > 0.7 and now - S.lastPend > 0.06 and #pend < 24 then
                local tau = ToF_Delay()
                S.lastPend = now
                pend[#pend + 1] = { due = now + tau, base = pos, vl = vs * tau }
            end
            local i = 1
            while i <= #pend do
                local pd = pend[i]
                if now >= pd.due then
                    local disp = pos - pd.base
                    disp = Vector3.new(disp.X, 0, disp.Z)
                    local den = pd.vl:Dot(pd.vl)
                    if den > 1 then
                        local m = math.clamp(disp:Dot(pd.vl) / den, 0, 2.5)
                        S.mAuto = S.mAuto + (m - S.mAuto) * 0.12
                    end
                    table.remove(pend, i)
                else
                    i = i + 1
                end
            end
        elseif #pend > 0 then
            S.pend = {}
        end
    end

    local ToF_MUZZLE = Vector3.new(0.70, 1.37, -2.50)
    local function ToF_Muzzle(hrp, face)
        local pos = hrp.Position
        local cf = hrp.CFrame
        if face then
            local fl = Vector3.new(face.X - pos.X, 0, face.Z - pos.Z)
            if fl.Magnitude > 0.5 then cf = CFrame.lookAt(pos, pos + fl) end
        end
        return cf:PointToWorldSpace(ToF_MUZZLE)
    end

    local function ToF_TargetWithinLimits(targetPart, originPos)
        if not (targetPart and targetPart.Parent) then return false end
        local maxDistance = math.max(tonumber(VD.TOFV3SRC_MaxDistance) or 500, 1)
        local distOrigin = typeof(originPos) == "Vector3" and originPos or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") and LocalPlayer.Character.HumanoidRootPart.Position)
        if distOrigin and (targetPart.Position - distOrigin).Magnitude > maxDistance then return false end
        local camera = workspace.CurrentCamera
        if camera then
            local projected, onScreen = camera:WorldToViewportPoint(targetPart.Position)
            if not onScreen then return false end
            local center = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y * 0.5)
            local screenPos = Vector2.new(projected.X, projected.Y)
            local radius = math.clamp(tonumber(VD.TOFV3SRC_FOV) or 250, 10, 1200)
            if (screenPos - center).Magnitude > radius then return false end
        end
        return true
    end

    local function ToF_GetTarget()
        local g = ToF_GetGun(); local c = LocalPlayer.Character
        if not (g and c) then return nil,nil,nil,nil end
        local hrp = c:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil,nil,nil,nil end
        local mp = hrp.Position
        local op
        if c:GetAttribute("IsCarried") then op = hrp.Position + (hrp.CFrame.LookVector * 2)
        else
            op = ToF_Muzzle(hrp)
        end
        local function predict(t, tc)
            local tp = t.Position
            if not ToF_TargetWithinLimits(t, op) then return nil,nil,nil,nil end
            if VD.TOFV3SRC_WallCheck and not ToF_IsVisible(op, tp, tc) then return nil,nil,nil,nil end
            local rp = tc and (tc:FindFirstChild("HumanoidRootPart") or t)
            local dr = tp - op; local d = dr.Magnitude
            if d < 0.1 then return nil,nil,nil,nil end
            if d < 5 then
                ToF_LastPred = nil
                local op2 = c:GetAttribute("IsCarried") and op or ToF_Muzzle(hrp, tp)
                local dr2 = tp - op2
                if dr2.Magnitude < 0.1 then return nil,nil,nil,nil end
                return dr2.Unit, g, op2, tp
            end
            local aimPos = tp
            ToF_LastReal = nil
            if VD.TOFV3SRC_AutoPredict and tc then
                ToF_SampleVel(tc)
                local S = ToF_Track[tc]
                local SN = VD.TOFV3SRC_UseSnap and ToF_GetSnap(tc) or nil
                local hrpR = tc:FindFirstChild("HumanoidRootPart")
                if SN and (not hrpR or (SN.pos - hrpR.Position).Magnitude > 50) then SN = nil end
                if S and SN then
                    S.vShort, S.vy, S.omega, S.conf = SN.vel, SN.vy, SN.omega, SN.conf
                end
                local vel = S and S.vShort or Vector3.zero
                local nowc = os.clock()
                if S then
                    if S.vIn then
                        local startingUp = S.inT0 and (nowc - S.inT0) < 0.25
                        local exiting = S.blocked and S.blockDir and S.vIn.Magnitude > 0.1
                            and S.vIn.Unit:Dot(S.blockDir) < 0.85
                        if exiting then
                            vel = S.vIn.Unit * math.max(vel.Magnitude, (S.vIn.Magnitude) * 0.8)
                        elseif startingUp or vel.Magnitude >= 0.5 * S.vIn.Magnitude then
                            vel = vel:Lerp(S.vIn, startingUp and 0.6 or 0.5)
                        end
                    elseif S.stopping then
                        vel = vel * 0.3
                    end
                end
                local vy = S and S.vy or 0
                if S and (vel.Magnitude > 1 or (S.air and math.abs(vy) > 1)) then
                    local ping = ToF_Ping()
                    local mult
                    if VD.TOFV3SRC_SmartPredict then
                        mult = math.clamp(math.clamp(S.mAuto, 0.2, 1.8) * ToF_ConfEff(S) * (tonumber(VD["TOFV3SRC_HitGain" .. ToF_Band(d)]) or 1), 0.3, 1.6)
                    else
                        mult = tonumber(VD.TOFV3SRC_LeadMultiplier) or 1.4
                    end
                    local base = ToF_Delay()
                    local vb = math.max(tonumber(VD.TOFV3SRC_BulletSpeed) or 200, 50)
                    local kT = VD.TOFV3SRC_UseTravel and math.clamp(tonumber(VD.TOFV3SRC_TravelK) or 0.5, 0, 2.5) or 0
                    local om = S.omega or 0
                    local ex, snapOff, realBase = 0, Vector3.zero, tp
                    if SN then
                        ex = math.clamp(os.clock() - SN.tl, 0, 0.15)
                        local off = hrpR and (tp - hrpR.Position) or Vector3.zero
                        realBase = SN.pos + off
                        snapOff = realBase - tp
                    end
                    local function leadFor(dl0)
                        local dl = dl0 + ex
                        local ld = vel * dl * mult
                        if vel.Magnitude > 2 and math.abs(om) > 0.35 then
                            local lim = math.rad(100) / math.max(dl, 0.05)
                            local omE = math.clamp(om * 0.7, -lim, lim)
                            ld = ToF_ArcDisp(vel, omE, dl) * mult
                        end
                        local cap = math.clamp(math.max(d * 0.6, vel.Magnitude * dl * mult * 1.2), 3, 120)
                        if ld.Magnitude > cap then ld = ld.Unit * cap end
                        return ld
                    end
                    local delay = base + kT * d / vb
                    local lead = leadFor(delay)
                    if kT > 0 then
                        for _ = 1, 2 do
                            delay = base + kT * (tp + lead - op).Magnitude / vb
                            lead = leadFor(delay)
                        end
                    end
                    local dy = 0
                    if S.air then
                        dy = vy * delay - 0.5 * workspace.Gravity * delay * delay
                        local okr, hit = pcall(function()
                            local rp2 = RaycastParams.new()
                            rp2.FilterType = Enum.RaycastFilterType.Exclude
                            rp2.FilterDescendantsInstances = { tc, LocalPlayer.Character }
                            return workspace:Raycast(tp, Vector3.new(0, -300, 0), rp2)
                        end)
                        if okr and hit then
                            dy = math.max(dy, -((tp.Y - hit.Position.Y) - 1))
                        end
                        dy = math.clamp(dy, -40, 25)
                    end
                    local lh = Vector3.new(lead.X, 0, lead.Z)
                    if lh.Magnitude > 1.5 then
                        local okw, wh = pcall(function()
                            local rp3 = RaycastParams.new()
                            rp3.FilterType = Enum.RaycastFilterType.Exclude
                            rp3.RespectCanCollide = true
                            local ex2 = { tc, LocalPlayer.Character }
                            for _, pl2 in ipairs(Players:GetPlayers()) do
                                if pl2.Character then ex2[#ex2 + 1] = pl2.Character end
                            end
                            rp3.FilterDescendantsInstances = ex2
                            return workspace:Raycast(realBase, lh, rp3)
                        end)
                        if okw and wh then
                            local wd = math.max((wh.Position - realBase).Magnitude - 1.2, 0)
                            lead = lh.Unit * math.min(wd, lh.Magnitude) + Vector3.new(0, lead.Y, 0)
                        end
                    end
                    lead = lead + snapOff
                    lead = Vector3.new(lead.X, dy + snapOff.Y, lead.Z)
                    ToF_LastReal = realBase
                    ToF_LastVel, ToF_LastMult, ToF_LastBase, ToF_LastVB = vel, mult, base, vb
                    local dt = math.clamp(nowc - S.leadT, 0, 0.2)
                    S.leadT = nowc
                    local sm = math.clamp((tonumber(VD.TOFV3SRC_LineSmooth) or 70) / 100, 0, 1)
                    local rate = 80 * (1 - sm) + 8 * sm
                    S.lead = S.lead:Lerp(lead, math.clamp(dt * rate, 0.05, 1))
                    aimPos = tp + (ToF_RawMode and lead or S.lead)
                elseif S then
                    S.lead = Vector3.zero; S.leadT = nowc
                end
            end
            local opF = c:GetAttribute("IsCarried") and op or ToF_Muzzle(hrp, aimPos)
            local fd = aimPos - opF
            if fd.Magnitude < 0.1 then return nil,nil,nil,nil end
            ToF_LastPred = { tc = tc, real = ToF_LastReal or tp, aim = aimPos, band = ToF_Band(d), vel = ToF_LastVel, mult = ToF_LastMult, base = ToF_LastBase, d = d, vb = ToF_LastVB }
            return fd.Unit, g, opF, aimPos
        end
        local mode = VD.TOFV3SRC_TargetMode or "Killer"
        if mode=="Killer" then
            local bt, bc, bs = nil, nil, math.huge
            for _,p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and TeamIs(p, "Killer") and p.Character then
                    local t = p.Character:FindFirstChild("Torso")
                        or p.Character:FindFirstChild("UpperTorso")
                        or p.Character:FindFirstChild("HumanoidRootPart")
                    if t and ToF_TargetWithinLimits(t, mp) then
                        local d = (mp-t.Position).Magnitude
                        if d < bs then bs=d; bt=t; bc=p.Character end
                    end
                end
            end
            if not bt then return nil,nil,nil,nil end
            return predict(bt, bc)
        elseif mode=="Survivors" then
            local bt, bc, bd = nil, nil, -math.huge
            local cam = workspace.CurrentCamera
            local cl = cam.CFrame.LookVector
            for _,p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and TeamIs(p, "Survivor") and p.Character then
                    local t = p.Character:FindFirstChild("Torso")
                        or p.Character:FindFirstChild("UpperTorso")
                        or p.Character:FindFirstChild("HumanoidRootPart")
                    if t and ToF_TargetWithinLimits(t, mp) then
                        local dt = t.Position - cam.CFrame.Position
                        if dt.Magnitude>0.1 then
                            local dot = cl:Dot(dt.Unit)
                            if dot>0.5 and dot>bd then bd=dot; bt=t; bc=p.Character end
                        end
                    end
                end
            end
            if not bt then return nil,nil,nil,nil end
            return predict(bt, bc)
        elseif mode=="Zombie" then
            local bp, bd = nil, -math.huge
            local cam = workspace.CurrentCamera
            local cl = cam.CFrame.LookVector
            for _,r in ipairs(ToF_GetSCPs()) do
                if r and r.Parent and ToF_TargetWithinLimits(r, mp) then
                    local dt = r.Position - cam.CFrame.Position
                    if dt.Magnitude>0.1 then
                        local dot = cl:Dot(dt.Unit)
                        if dot>0.5 and dot>bd then bd=dot; bp=r end
                    end
                end
            end
            if not bp then return nil,nil,nil,nil end
            return predict(bp, bp.Parent)
        end
        return nil,nil,nil,nil
    end
    RunService.RenderStepped:Connect(function()
        if not ToF_IsCurrentRuntime() then return end
        if not (VD.TOFV3SRC_SilentAim and VD.TOFV3SRC_AutoPredict) then return end
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= LocalPlayer and pl.Character then ToF_SampleVel(pl.Character) end
        end
        if VD.TOFV3SRC_TargetMode == "Zombie" then
            for _, r in ipairs(ToF_GetSCPs()) do
                if r and r.Parent then ToF_SampleVel(r.Parent) end
            end
        end
    end)
    local function ToF_UpdateLaser(op, tp)
        if not ToFState.LaserBeam then
            local l = Instance.new("Part")
            l.Name="ToFLaser"; l.Anchored=true; l.CanCollide=false
            l.CanTouch=false; l.CastShadow=false
            l.Material=Enum.Material.Neon
            l.Color=Color3.fromRGB(0, 212, 255)
            l.Parent=workspace
            ToFState.LaserBeam = l
        end
        local d = (tp-op).Magnitude
        ToFState.LaserBeam.Size = Vector3.new(0.05,0.05,d)
        ToFState.LaserBeam.CFrame = CFrame.new((op+tp)/2, tp)
        ToFState.LaserBeam.Transparency = 0
    end
    local function ToF_UpdateFOV()
        local parent = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if type(gethui) == "function" then
            local ok, hui = pcall(gethui)
            if ok and hui then parent = hui end
        end
        if not parent then return end
        if not ToFState.FOVGui or not ToFState.FOVGui.Parent then
            local stale = parent:FindFirstChild("ToFV3FOVOverlay")
            if stale then pcall(function() stale:Destroy() end) end
            local gui = Instance.new("ScreenGui")
            gui.Name = "ToFV3FOVOverlay"
            gui.ResetOnSpawn = false
            gui.IgnoreGuiInset = true
            gui.DisplayOrder = 997
            gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            gui.Parent = parent
            local circle = Instance.new("Frame")
            circle.Name = "FOVCircle"
            circle.BackgroundTransparency = 1
            circle.BorderSizePixel = 0
            circle.AnchorPoint = Vector2.new(0.5, 0.5)
            circle.Position = UDim2.fromScale(0.5, 0.5)
            circle.Parent = gui
            Instance.new("UICorner", circle).CornerRadius = UDim.new(1, 0)
            local stroke = Instance.new("UIStroke")
            stroke.Color = Color3.fromRGB(64, 224, 255) -- Bright light-blue POV ring
            stroke.Thickness = 1.5
            stroke.Transparency = 0.12
            stroke.Parent = circle
            ToFState.FOVGui, ToFState.FOVCircle = gui, circle
        end
        local radius = math.clamp(tonumber(VD.TOFV3SRC_FOV) or 250, 10, 1200)
        ToFState.FOVCircle.Size = UDim2.fromOffset(radius * 2, radius * 2)
        ToFState.FOVCircle.Visible = VD.TOFV3SRC_SilentAim == true and VD.TOFV3SRC_ShowFOV == true
    end

    local function ToF_ClearLaser()
        if ToFState.LaserBeam then
            pcall(function() ToFState.LaserBeam:Destroy() end)
            ToFState.LaserBeam=nil
        end
    end
    local function ToF_GetMobileBtn()
        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        local sm = pg and pg:FindFirstChild("Survivor-mob")
        local ct = sm and sm:FindFirstChild("Controls")
        local gm = ct and ct:FindFirstChild("Gui-mob")
        if not gm then return nil end
        for _,n in ipairs({"attack","Attack","shoot","Shoot","fire","Fire"}) do
            local b = gm:FindFirstChild(n,true)
            if b and b:IsA("GuiObject") then return b end
        end
        for _,o in ipairs(gm:GetDescendants()) do
            if o:IsA("GuiButton") and o.Visible then return o end
        end
        return gm:IsA("GuiObject") and gm or nil
    end
    local function ToF_IsTouchShoot(input)
        local sb = ToF_GetMobileBtn()
        if not (sb and sb.Visible) then return false end
        local p = input.Position; local ap = sb.AbsolutePosition; local az = sb.AbsoluteSize
        return p.X>=ap.X and p.X<=ap.X+az.X and p.Y>=ap.Y and p.Y<=ap.Y+az.Y
    end
    local ToF_HookActive = false
    local function ToF_Shoot()
        if not VD.TOFV3SRC_SilentAim then return end
        if ToF_HookActive and not ToF_GameWouldBlock() then return end
        if ToF_IsBlocked() then return end
        local since = os.clock() - (ToFState.LastFaceMove or 0)
        if since < 0.1 then
            pcall(function()
                local c = LocalPlayer.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                local _, _, _, tp0 = ToF_GetTarget()
                if hrp and tp0 and not c:GetAttribute("IsCarried") then
                    hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp0.X, hrp.Position.Y, tp0.Z))
                end
            end)
            task.wait(0.1 - since)
            if not VD.TOFV3SRC_SilentAim or ToF_IsBlocked() then return end
        end
        ToF_RawMode = true
        local okT, td, g, op, tp = pcall(ToF_GetTarget)
        ToF_RawMode = false
        if not (okT and td and g and tp and op) then return end
        local e = ToF_GetEvent()
        if not e then return end
        local fd = tp - op
        if fd.Magnitude < 0.1 then return end
        pcall(function()
            local c = LocalPlayer.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            if hrp and not c:GetAttribute("IsCarried") then
                hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z))
            end
        end)
        local lp = ToF_LastPred
        ToF_Shot = { t = os.clock(), tc = lp and lp.tc, real = lp and lp.real, aim = lp and lp.aim, band = lp and lp.band, vel = lp and lp.vel, mult = lp and lp.mult, base = lp and lp.base, d = lp and lp.d, vb = lp and lp.vb, used = false }
        pcall(function() e:FireServer(g, fd.Unit) end)
    end

    task.spawn(function()
        pcall(function()
            if not ToF_IsCurrentRuntime() then return end
            if typeof(hookmetamethod) ~= "function" or typeof(getnamecallmethod) ~= "function" then return end
            local remote
            for _ = 1, 40 do
                remote = ToF_GetEvent()
                if remote then break end
                task.wait(0.5)
            end
            if not remote then return end
            local oldNC
            oldNC = hookmetamethod(game, "__namecall", function(self, ...)
                local method = getnamecallmethod()
                if ToF_IsCurrentRuntime() and self == remote and method == "FireServer" and type(checkcaller) == "function" and not checkcaller() and VD.TOFV3SRC_SilentAim then
                    local args = table.pack(...)
                    local newDir
                    pcall(function()
                        if ToF_IsBlocked() then return end
                        ToF_RawMode = true
                        local td, g, op, tp = ToF_GetTarget()
                        ToF_RawMode = false
                        if td and tp and op then
                            local fd = tp - op
                            if fd.Magnitude > 0.1 then
                                newDir = fd.Unit
                                local lp = ToF_LastPred
                                ToF_Shot = { t = os.clock(), tc = lp and lp.tc, real = lp and lp.real, aim = lp and lp.aim, band = lp and lp.band, vel = lp and lp.vel, mult = lp and lp.mult, base = lp and lp.base, d = lp and lp.d, vb = lp and lp.vb, used = false }
                                local c = LocalPlayer.Character
                                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                                if hrp and not c:GetAttribute("IsCarried") then
                                    hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z))
                                end
                            end
                        end
                    end)
                    ToF_RawMode = false
                    if newDir then args[2] = newDir end
                    if typeof(setnamecallmethod) == "function" then pcall(setnamecallmethod, "FireServer") end
                    return oldNC(self, table.unpack(args, 1, args.n))
                end
                return oldNC(self, ...)
            end)
            ToF_HookActive = true
        end)
    end)

    -- V3 uses its own floating target selector; it does not reuse V1/V2 GUI objects.
    local ToF3_ModeConfig = {
        Killer = {Label = "KILLER", Hint = "K", Color = Color3.fromRGB(255, 90, 90)},
        Survivors = {Label = "SURVIVOR", Hint = "J", Color = Color3.fromRGB(120, 200, 255)},
        Zombie = {Label = "ZOMBIE", Hint = "L", Color = Color3.fromRGB(120, 255, 150)},
    }

    local function ToF3_RefreshTargetButtons()
        for mode, button in pairs(ToFState.TargetModeButtons) do
            if button and button.Parent then
                local active = mode == (VD.TOFV3SRC_TargetMode or "Killer")
                local config = ToF3_ModeConfig[mode]
                button.BackgroundColor3 = active and Color3.fromRGB(37, 44, 55) or Color3.fromRGB(24, 24, 30)
                button.TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(145, 145, 158)
                local stroke = button:FindFirstChildOfClass("UIStroke")
                if stroke then
                    stroke.Color = active and config.Color or Color3.fromRGB(52, 52, 65)
                    stroke.Transparency = active and 0.05 or 0.45
                end
            end
        end
    end

    local function ToF_SetTargetMode(mode, notify)
        if type(mode) == "table" then mode = mode[1] end
        if mode ~= "Killer" and mode ~= "Survivors" and mode ~= "Zombie" then return end
        VD.TOFV3SRC_TargetMode = mode
        VD.TOFV3_TargetMode = mode
        ToF3_RefreshTargetButtons()
        if notify then VD_Notify("Silent Pistol V3", "Target: " .. mode, 2) end
    end

    local function ToF3_DestroyTargetUI()
        for _, connection in ipairs(ToFState.TargetDragConnections) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(ToFState.TargetDragConnections)
        if ToFState.TargetGui then
            pcall(function() ToFState.TargetGui:Destroy() end)
            ToFState.TargetGui = nil
        end
        table.clear(ToFState.TargetModeButtons)
    end

