                dragStart = input.Position
                startPos = frame.Position
            end
        end)
        table.insert(ToFState.TargetDragConnections, UserInputService.InputChanged:Connect(function(input)
            if not dragInput or not frame.Parent or not dragStart or not startPos then return end
            local isMouseMove = input.UserInputType == Enum.UserInputType.MouseMovement
            local isThisTouch = input.UserInputType == Enum.UserInputType.Touch and input == dragInput
            if not isMouseMove and not isThisTouch then return end
            local delta = input.Position - dragStart
            local newPos = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            frame.Position = newPos
            ToFState.SavedUIPos = newPos
        end))
        table.insert(ToFState.TargetDragConnections, UserInputService.InputEnded:Connect(function(input)
            if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragInput, dragStart, startPos = nil, nil, nil
            end
        end))

        gui.Parent = parent
        ToFState.TargetGui = gui
        ToF3_RefreshTargetButtons()
    end

    local function ToF_RemoveLegacyUI()
        local parents = {}
        local seen = {}
        local function addParent(parent)
            if parent and not seen[parent] then
                seen[parent] = true
                table.insert(parents, parent)
            end
        end
        pcall(function()
            if type(gethui) == "function" then addParent(gethui()) end
        end)
        pcall(function() addParent(game:GetService("CoreGui")) end)
        pcall(function() addParent(LocalPlayer:FindFirstChild("PlayerGui")) end)
        for _, parent in ipairs(parents) do
            for _, guiName in ipairs({"ToFSettingsPanel", "ToFTargetSelector", "PistolV3TargetSelector"}) do
                pcall(function()
                    local gui = parent:FindFirstChild(guiName)
                    if gui then gui:Destroy() end
                end)
            end
        end
        ToF3_DestroyTargetUI()
    end

    -- Clear panels left behind by an earlier execution before the hub UI is shown.
    ToF_RemoveLegacyUI()

    local function ToF_StartConn()
        if ToFState.Connection then return end
        ToFState.Connection = RunService.RenderStepped:Connect(function()
            if not ToF_IsCurrentRuntime() then
                pcall(function() ToFState.Connection:Disconnect() end)
                ToFState.Connection = nil
                return
            end
            if ToF_IsBlocked() then
                ToFState.IsAiming = false
                if ToFState.TouchInput then ToFState.TouchInput = nil end
                if ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
                return
            end
            if not VD.TOFV3SRC_SilentAim or not ToFState.IsAiming then
                if ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
                return
            end
            local _, _, op, tp = ToF_GetTarget()
            if op and tp then
                pcall(function()
                    local c = LocalPlayer.Character
                    local hrp = c and c:FindFirstChild("HumanoidRootPart")
                    if hrp and not c:GetAttribute("IsCarried") then
                        local before = hrp.CFrame.LookVector
                        hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z))
                        if before:Dot(hrp.CFrame.LookVector) < 0.9986 then ToFState.LastFaceMove = os.clock() end
                    end
                end)
                if VD.TOFV3SRC_Laser then ToF_UpdateLaser(op, tp)
                elseif ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
            elseif ToFState.LaserBeam then
                ToFState.LaserBeam.Transparency = 1
            end
        end)
    end

    local function ToF_StopConn()
        if ToFState.Connection then
            pcall(function() ToFState.Connection:Disconnect() end)
            ToFState.Connection = nil
        end
        ToFState.IsAiming = false
        ToF_ClearLaser()
    end

    local SetToFSilentAim
    local function ToF_EnsureInputs()
        if not ToFState.InputBegan then
            ToFState.InputBegan = UserInputService.InputBegan:Connect(function(inp, gp)
                if not ToF_IsCurrentRuntime() or gp then return end
                local k = ToFKeyCodes[VD.TOFV3SRC_Key or "None"]
                if k and inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == k then
                    SetToFSilentAim(not VD.TOFV3SRC_SilentAim); return
                end
                if not VD.TOFV3SRC_SilentAim then return end
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or (inp.UserInputType == Enum.UserInputType.Touch and ToF_IsTouchShoot(inp)) then
                    if ToF_IsBlocked() then ToFState.IsAiming = false; return end
                    ToFState.IsAiming = true
                    if inp.UserInputType == Enum.UserInputType.Touch then ToFState.TouchInput = inp end
                    return
                end
                if inp.UserInputType == Enum.UserInputType.Keyboard then
                    if inp.KeyCode == Enum.KeyCode.K then ToF_SetTargetMode("Killer", true)
                    elseif inp.KeyCode == Enum.KeyCode.J then ToF_SetTargetMode("Survivors", true)
                    elseif inp.KeyCode == Enum.KeyCode.L then ToF_SetTargetMode("Zombie", true) end
                end
            end)
        end
        if not ToFState.InputEnded then
            ToFState.InputEnded = UserInputService.InputEnded:Connect(function(inp)
                if not ToF_IsCurrentRuntime() then return end
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or (inp.UserInputType == Enum.UserInputType.Touch and inp == ToFState.TouchInput) then
                    local wa = ToFState.IsAiming
                    ToFState.IsAiming = false
                    if inp == ToFState.TouchInput then ToFState.TouchInput = nil end
                    if ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
                    if wa then
                        if ToF_IsBlocked() then return end
                        ToF_Shoot()
                    end
                end
            end)
        end
    end

    SetToFSilentAim = function(en)
        VD.TOFV3SRC_SilentAim = en and true or false
        VD.SilentPistolV3Enabled = VD.TOFV3SRC_SilentAim
        if VD.TOFV3SRC_SilentAim then
            VD.TOFV1_SilentAim = false
            if type(W.SetToFSilentAimV1) == "function" then pcall(function() W.SetToFSilentAimV1(false) end) end
            VD.SilentPistolV2Enabled = false
            if type(W.SetPistolV2Enabled) == "function" then pcall(function() W.SetPistolV2Enabled(false) end) end
        end
        ToF_EnsureInputs()
        if VD.TOFV3SRC_SilentAim then
            ToF_RemoveLegacyUI()
            ToF3_CreateTargetUI()
            ToF_StartConn()
        else
            ToF_RemoveLegacyUI()
            ToF_StopConn()
        end
        ToF_UpdateFOV()
        if type(W.ToF_RefreshSettings) == "function" then pcall(W.ToF_RefreshSettings) end
    end

    W.SetToFSilentAim = SetToFSilentAim
    W.ToF_ClearLaser = ToF_ClearLaser
    W.ToF_SetTargetMode = ToF_SetTargetMode
    W.ToF_GetTargetMode = function() return VD.TOFV3SRC_TargetMode end
    W.ToF_UpdateFOV = ToF_UpdateFOV
    -- Mirror public helpers so the main hub's legacy W=getgenv() scope reaches this source engine.
    do
        local globalEnv = getgenv()
        globalEnv.SetToFSilentAim = W.SetToFSilentAim
        globalEnv.ToF_ClearLaser = W.ToF_ClearLaser
        globalEnv.ToF_SetTargetMode = W.ToF_SetTargetMode
        globalEnv.ToF_GetTargetMode = W.ToF_GetTargetMode
        globalEnv.ToF_UpdateFOV = W.ToF_UpdateFOV
    end
    ToF_EnsureInputs()

    ToF_UpdateFOV()
end


end

