            frameBg.Position = UDim2.fromScale(0, 0)
            frameBg.BackgroundTransparency = 1
            frameBg.BorderSizePixel = 0
            frameBg.Image = FLOATING_BUTTON_BACKGROUND
            frameBg.ScaleType = Enum.ScaleType.Crop
            frameBg.ImageTransparency = 0
            frameBg.Active = false
            frameBg.ZIndex = 1
            frameBg.Parent = frame
            Instance.new("UICorner", frameBg).CornerRadius = UDim.new(0, 10)
            task.spawn(PreloadFloatingPhoto, frameBg)

            local outline = Instance.new("UIStroke")
            outline.Color = Color3.fromRGB(255, 170, 64)
            outline.Thickness = 1.2
            outline.Transparency = 0.2
            outline.Parent = frame

            local header = Instance.new("Frame")
            header.Name = "Header"
            header.Size = UDim2.new(1, 0, 0, 38)
            header.BackgroundColor3 = Color3.fromRGB(23, 23, 29)
            header.BackgroundTransparency = 1
            header.BorderSizePixel = 0
            header.Active = true
            header.Parent = frame
            Instance.new("UICorner", header).CornerRadius = UDim.new(0, 10)
            local title = Instance.new("TextLabel")
            title.Name = "Title"
            title.Position = UDim2.fromOffset(10, 3)
            title.Size = UDim2.new(1, -48, 0, 17)
            title.BackgroundTransparency = 1
            title.Font = Enum.Font.GothamBold
            title.Text = "SILENT PISTOL V2"
            title.TextColor3 = Color3.fromRGB(245, 245, 250)
            title.TextSize = 11
            title.TextXAlignment = Enum.TextXAlignment.Left
            title.Parent = header
            local subtitle = Instance.new("TextLabel")
            subtitle.Name = "Subtitle"
            subtitle.Position = UDim2.fromOffset(10, 19)
            subtitle.Size = UDim2.new(1, -18, 0, 12)
            subtitle.BackgroundTransparency = 1
            subtitle.Font = Enum.Font.Gotham
            subtitle.Text = "DRAG HEADER  •  SELECT TARGET"
            subtitle.TextColor3 = Color3.fromRGB(145, 145, 160)
            subtitle.TextSize = 8
            subtitle.TextXAlignment = Enum.TextXAlignment.Left
            subtitle.Parent = header
            local minimize = Instance.new("TextButton")
            minimize.Name = "Minimize"
            minimize.AnchorPoint = Vector2.new(1, 0)
            minimize.Position = UDim2.new(1, -6, 0, 7)
            minimize.Size = UDim2.fromOffset(22, 22)
            minimize.BackgroundColor3 = Color3.fromRGB(35, 35, 44)
            minimize.BorderSizePixel = 0
            minimize.Text = "—"
            minimize.Font = Enum.Font.GothamBold
            minimize.TextSize = 13
            minimize.TextColor3 = Color3.fromRGB(245, 245, 250)
            minimize.Parent = header
            Instance.new("UICorner", minimize).CornerRadius = UDim.new(0, 5)

            local body = Instance.new("Frame")
            body.Name = "Modes"
            body.Position = UDim2.fromOffset(8, 43)
            body.Size = UDim2.new(1, -16, 0, 100)
            body.BackgroundTransparency = 1
            body.Parent = frame
            for index, mode in ipairs({"Killer", "Survivors", "Zombie"}) do
                local button = Instance.new("TextButton")
                button.Name = "Mode_" .. mode
                button.Size = UDim2.new(1, 0, 0, 27)
                button.Position = UDim2.fromOffset(0, (index - 1) * 31)
                button.BackgroundColor3 = Color3.fromRGB(24, 24, 30)
                button.BorderSizePixel = 0
                button.AutoButtonColor = false
                button.Font = Enum.Font.GothamBold
                button.Text = string.upper(mode)
                button.TextSize = 10
                button.TextColor3 = Color3.fromRGB(145, 145, 158)
                button.Parent = body
                Instance.new("UICorner", button).CornerRadius = UDim.new(0, 6)
                local buttonStroke = Instance.new("UIStroke")
                buttonStroke.Color = Color3.fromRGB(52, 52, 65)
                buttonStroke.Thickness = 1
                buttonStroke.Transparency = 0.45
                buttonStroke.Parent = button
                PistolV2State.TargetModeButtons[mode] = button
                button.Activated:Connect(function() PistolV2State.SetTargetMode(mode, false) end)
            end

            local minimized = false
            minimize.Activated:Connect(function()
                minimized = not minimized
                body.Visible = not minimized
                frame.Size = UDim2.fromOffset(200, minimized and 38 or 152)
                minimize.Text = minimized and "+" or "—"
            end)
            local dragInput, dragStart, startPos, startAbs
            header.Active = true
            header.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragInput = input
                    dragStart = input.Position
                    startPos = frame.Position
                    startAbs = frame.AbsolutePosition
                end
            end)
            table.insert(PistolV2State.TargetDragConnections, UserInputService.InputChanged:Connect(function(input)
                if not dragInput or not frame.Parent or not startAbs or not startPos then return end
                local isMouseMove = input.UserInputType == Enum.UserInputType.MouseMovement
                local isThisTouch = input.UserInputType == Enum.UserInputType.Touch and input == dragInput
                if not isMouseMove and not isThisTouch then return end
                local delta = input.Position - dragStart
                local camera = workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(360, 720)
                local desiredX = startAbs.X + delta.X
                local desiredY = startAbs.Y + delta.Y
                local clampedX = math.clamp(desiredX, 0, math.max(0, viewport.X - frame.AbsoluteSize.X))
                local clampedY = math.clamp(desiredY, 0, math.max(0, viewport.Y - frame.AbsoluteSize.Y))
                frame.Position = UDim2.new(
                    startPos.X.Scale, startPos.X.Offset + (clampedX - startAbs.X),
                    startPos.Y.Scale, startPos.Y.Offset + (clampedY - startAbs.Y)
                )
                PistolV2State.SavedUIPos = frame.Position
            end))
            table.insert(PistolV2State.TargetDragConnections, UserInputService.InputEnded:Connect(function(input)
                local releaseMouse = input.UserInputType == Enum.UserInputType.MouseButton1
                local releaseTouch = input.UserInputType == Enum.UserInputType.Touch and input == dragInput
                if dragInput and (releaseMouse or releaseTouch) then
                    dragInput, dragStart, startPos, startAbs = nil, nil, nil, nil
                end
            end))
            PistolV2State.TargetGui = gui
            PistolV2State.RefreshTargetButtons()
        end

        local function PistolV2_UpdateLaser(origin, target)
            if not PistolV2State.Laser then
                local part = Instance.new("Part")
                part.Name = "PistolV2Laser"; part.Anchored = true; part.CanCollide = false; part.CanTouch = false; part.CanQuery = false
                part.CastShadow = false; part.Material = Enum.Material.Neon; part.Color = Color3.fromRGB(255, 50, 50); part.Parent = workspace
                PistolV2State.Laser = part
            end
            local delta = target - origin
            local distance = math.max(delta.Magnitude, 0.1)
            PistolV2State.Laser.Size = Vector3.new(0.05, 0.05, distance)
            PistolV2State.Laser.CFrame = CFrame.new((origin + target) / 2, target)
            PistolV2State.Laser.Transparency = 0
        end
        local function PistolV2_Shoot()
            if not VD.SilentPistolV2Enabled or PistolV2_IsBlocked() then return end
            local direction, gun, origin, target = PistolV2_GetTarget()
            if not (direction and gun and origin and target) then return end
            local remote = PistolV2_GetEvent()
            if not (remote and remote:IsA("RemoteEvent")) then return end
            -- Match reference V1 exactly: Items["Twist of Fate"].Fire:FireServer(gun, unitDirection).
            pcall(function() remote:FireServer(gun, direction) end)
        end
        local function PistolV2_StartConnection()
            if PistolV2State.Connection then return end
            PistolV2State.Connection = RunService.RenderStepped:Connect(function()
                if not VD.SilentPistolV2Enabled or not PistolV2State.Aiming or PistolV2_IsBlocked() then
                    if PistolV2State.Laser then PistolV2State.Laser.Transparency = 1 end
                    return
                end
                local _, _, origin, target = PistolV2_GetTarget()
                if origin and target then
                    pcall(function()
                        if VD.TOFV2_LockAim and workspace.CurrentCamera then
                            local camera = workspace.CurrentCamera
                            camera.CFrame = camera.CFrame:Lerp(CFrame.lookAt(camera.CFrame.Position, target), 0.15)
                        end
                    end)
                    if VD.TOFV2_Laser then PistolV2_UpdateLaser(origin, target)
                    elseif PistolV2State.Laser then PistolV2State.Laser.Transparency = 1 end
                elseif PistolV2State.Laser then PistolV2State.Laser.Transparency = 1 end
            end)
        end
        local function PistolV2_StopConnection()
            if PistolV2State.Connection then pcall(function() PistolV2State.Connection:Disconnect() end); PistolV2State.Connection = nil end
            PistolV2State.Aiming = false
            PistolV2_ClearLaser()
        end
        local SetPistolV2Enabled
        local function PistolV2_EnsureInputs()
            if not PistolV2State.InputBegan then
                PistolV2State.InputBegan = UserInputService.InputBegan:Connect(function(input, processed)
                    if processed then return end
                    if input.UserInputType == Enum.UserInputType.Keyboard then
                        local toggleKeyName = VD.TOFV2_Key or "P"
                        local toggleKey = nil
                        if toggleKeyName ~= "None" then
                            pcall(function() toggleKey = Enum.KeyCode[toggleKeyName] end)
                        end
                        if toggleKey and input.KeyCode == toggleKey and SetPistolV2Enabled then
                            SetPistolV2Enabled(not VD.SilentPistolV2Enabled)
                            return
                        end
                    end
                    if not VD.SilentPistolV2Enabled then return end
                    if input.UserInputType == Enum.UserInputType.Keyboard then
                        if input.KeyCode == Enum.KeyCode.X then PistolV2State.Aiming = false; if PistolV2State.Laser then PistolV2State.Laser.Transparency = 1 end; return end
                        if input.KeyCode == Enum.KeyCode.K then PistolV2State.SetTargetMode("Killer", false)
                        elseif input.KeyCode == Enum.KeyCode.J then PistolV2State.SetTargetMode("Survivors", false)
                        elseif input.KeyCode == Enum.KeyCode.L then PistolV2State.SetTargetMode("Zombie", false) end
                    end
                    if input.UserInputType == Enum.UserInputType.MouseButton2 then
                        -- Match the reference's aim-then-fire input: hold RMB to aim.
                        if PistolV2_IsBlocked() then
                            PistolV2State.Aiming = false
                            return
                        end
                        PistolV2State.Aiming = true
                    elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
                        -- The reference fires only when a shot is made while RMB aim is held.
                        if PistolV2State.Aiming and not PistolV2_IsBlocked() then
                            PistolV2_Shoot()
                        end
                    end
                end)
            end
            if not PistolV2State.InputEnded then
                PistolV2State.InputEnded = UserInputService.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton2 then
                        PistolV2State.Aiming = false
                        if PistolV2State.Laser then PistolV2State.Laser.Transparency = 1 end
                    end
                end)
            end
        end
        local function PistolV2_AttachMobile()
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local mobile = playerGui and playerGui:FindFirstChild("Survivor-mob")
            local controls = mobile and mobile:FindFirstChild("Controls")
            local guiMob = controls and controls:FindFirstChild("Gui-mob")
            if not (guiMob and guiMob:IsA("GuiObject")) then return false end
            if PistolV2State.MobileGui == guiMob and PistolV2State.MobileBegan and PistolV2State.MobileBegan.Connected then return true end
            if PistolV2State.MobileBegan then pcall(function() PistolV2State.MobileBegan:Disconnect() end) end
            if PistolV2State.MobileEnded then pcall(function() PistolV2State.MobileEnded:Disconnect() end) end
            PistolV2State.MobileGui = guiMob
            PistolV2State.MobileBegan = guiMob.InputBegan:Connect(function(input)
                if not VD.SilentPistolV2Enabled then return end
                if input.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                if PistolV2_IsBlocked() then PistolV2State.Aiming = false; return end
                PistolV2State.Aiming = true
                PistolV2_Shoot()
            end)
            PistolV2State.MobileEnded = guiMob.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                    PistolV2State.Aiming = false
                    if PistolV2State.Laser then PistolV2State.Laser.Transparency = 1 end
                end
            end)
            return true
        end

