        W.JerkTool = W.JerkTool or { Enabled = false, ToolName = "Jerk Off" }
        do
            local JerkTool = W.JerkTool
            JerkTool.SoundMode = JerkTool.SoundMode or "Both"
            local currentJerkTool = nil
            local currentJerkSound = nil
            local currentJerkFemaleSound = nil
            local jerkRunning = false

            function W.JerkOff_Destroy()
                if currentJerkSound then
                    pcall(function() currentJerkSound:Stop() end)
                    pcall(function() currentJerkSound:Destroy() end)
                    currentJerkSound = nil
                end
                if currentJerkFemaleSound then
                    pcall(function() currentJerkFemaleSound:Stop() end)
                    pcall(function() currentJerkFemaleSound:Destroy() end)
                    currentJerkFemaleSound = nil
                end
                if currentJerkTool then pcall(function() currentJerkTool:Destroy() end); currentJerkTool = nil end
            end

            function W.JerkOff_Create()
                W.JerkOff_Destroy()
                local character = LocalPlayer.Character
                if not character then return end
                local humanoid = character:FindFirstChildWhichIsA("Humanoid")
                local backpack = LocalPlayer:FindFirstChildWhichIsA("Backpack")
                if not humanoid or not backpack then return end

                local tool = Instance.new("Tool")
                tool.Name = JerkTool.ToolName
                tool.ToolTip = 'in the stripped club. straight up "jorking it" . and by "it" , haha, well. let\'s just say. My peanits.'
                tool.RequiresHandle = false
                tool.Parent = backpack
                currentJerkTool = tool

                -- Local-only anime-style gasp SFX. If the audio is unavailable, the emote still works.
                local soundParent = character:FindFirstChild("HumanoidRootPart") or character
                local soundOK, gaspSound = pcall(function()
                    local snd = Instance.new("Sound")
                    snd.Name = "MawwwJerkAnimeGasp"
                    snd.SoundId = "rbxassetid://5941361789" -- Shocked Gasp Sound Effect
                    snd.Volume = 0.55
                    snd.PlaybackSpeed = 1.08
                    snd.Looped = false
                    snd.RollOffMaxDistance = 35
                    snd.Parent = soundParent
                    return snd
                end)
                currentJerkSound = soundOK and gaspSound or nil

                -- Additional non-explicit female anime gasp; repeats once per second while equipped.
                local femaleSoundOK, femaleSound = pcall(function()
                    local snd = Instance.new("Sound")
                    snd.Name = "MawwwJerkFemaleAnimeVoice"
                    snd.SoundId = "rbxassetid://117008841852907" -- Girl gasp sound effect
                    snd.Volume = 0.48
                    snd.PlaybackSpeed = 1.0
                    snd.Looped = false
                    snd.RollOffMaxDistance = 35
                    snd.Parent = soundParent
                    return snd
                end)
                currentJerkFemaleSound = femaleSoundOK and femaleSound or nil
                local lastGaspAt = -math.huge
                local lastFemaleVoiceAt = -math.huge

                local jorkin = false
                local track = nil

                local function stopTomfoolery()
                    jorkin = false
                    if track then pcall(function() track:Stop() end); track = nil end
                    if currentJerkSound then pcall(function() currentJerkSound:Stop() end) end
                    if currentJerkFemaleSound then pcall(function() currentJerkFemaleSound:Stop() end) end
                end

                tool.Equipped:Connect(function() jorkin = true end)
                tool.Unequipped:Connect(stopTomfoolery)
                if humanoid.Died then humanoid.Died:Connect(stopTomfoolery) end

                task.spawn(function()
                    while jerkRunning do
                        task.wait()
                        if not JerkTool.Enabled or not jorkin then
                            if track then pcall(function() track:Stop() end) end
                            continue
                        end
                        local isR15 = humanoid.RigType == Enum.HumanoidRigType.R15
                        if not track then
                            local anim = Instance.new("Animation")
                            anim.AnimationId = not isR15 and "rbxassetid://72042024" or "rbxassetid://698251653"
                            track = humanoid:LoadAnimation(anim)
                        end
                        track:Play()
                        track:AdjustSpeed(isR15 and 0.7 or 0.65)
                        track.TimePosition = 0.6

                        -- Play only the sound option selected in the Misc UI.
                        local selectedSoundMode = JerkTool.SoundMode or "Both"
                        if (selectedSoundMode == "Anime Gasp" or selectedSoundMode == "Both")
                            and currentJerkSound and (os.clock() - lastGaspAt) >= 2.4 then
                            local played = false
                            pcall(function()
                                if currentJerkSound and currentJerkSound.Parent and not currentJerkSound.IsPlaying then
                                    currentJerkSound.TimePosition = 0
                                    currentJerkSound:Play()
                                    played = true
                                end
                            end)
                            if played then lastGaspAt = os.clock() end
                        end

                        -- Repeat the female anime voice every 1 second only when selected.
                        if (selectedSoundMode == "Female Anime Voice" or selectedSoundMode == "Both")
                            and currentJerkFemaleSound and (os.clock() - lastFemaleVoiceAt) >= 1.0 then
                            local playedFemale = false
                            pcall(function()
                                if currentJerkFemaleSound and currentJerkFemaleSound.Parent then
                                    if currentJerkFemaleSound.IsPlaying then
                                        currentJerkFemaleSound:Stop()
                                    end
                                    currentJerkFemaleSound.TimePosition = 0
                                    currentJerkFemaleSound:Play()
                                    playedFemale = true
                                end
                            end)
                            if playedFemale then lastFemaleVoiceAt = os.clock() end
                        end

                        task.wait(0.1)
                        while track and track.TimePosition < (not isR15 and 0.65 or 0.7) do
                            task.wait(0.1)
                        end
                        if track then pcall(function() track:Stop() end) end
                    end
                end)
            end

            function W.JerkOff_SetEnabled(v)
                JerkTool.Enabled = v and true or false
                jerkRunning = JerkTool.Enabled
                if v then W.JerkOff_Create() else W.JerkOff_Destroy() end
            end

            function W.JerkOff_SetSoundMode(mode)
                local validModes = {
                    ["Off"] = true,
                    ["Anime Gasp"] = true,
                    ["Female Anime Voice"] = true,
                    ["Both"] = true,
                }
                if not validModes[mode] then mode = "Both" end
                JerkTool.SoundMode = mode
                if mode == "Off" or mode == "Female Anime Voice" then
                    if currentJerkSound then pcall(function() currentJerkSound:Stop() end) end
                end
                if mode == "Off" or mode == "Anime Gasp" then
