                if direction == 0 then hum.AutoRotate=true; MW_RemoveAlign(root); MW.Rotation=0; return end
                hum.AutoRotate=false; local align=MW_CreateAlign(root)
                local look=camera.CFrame.LookVector; local flat=Vector3.new(look.X,0,look.Z)
                if flat.Magnitude < 0.001 then return end
                flat=flat.Unit*direction; local yaw=math.atan2(flat.X,flat.Z); local sway=0
                if MW.Mode == "Sway" and hum.MoveDirection.Magnitude > 0.01 then
                    local interval=1.2/math.max(1,MW.SwaySpeed)
                    if os.clock()-MW.LastFlip >= interval then MW.LastFlip=os.clock(); MW.SwaySign=-MW.SwaySign end
                    local target=MW.SwaySign*MW.SwayWidth; MW.Rotation=MW.Rotation+(target-MW.Rotation)*math.clamp((dt or 0.016)*14,0,1); sway=MW.Rotation
                else MW.Rotation=0 end
                align.CFrame=CFrame.Angles(0,yaw+sway,0)
            end)

            -- Anti Slow Vault: narrowly filters the configured Fall remote when executor hooks exist,
            -- and restores the Humanoid's normal run state after falling/landing.
            local AS={Enabled=false,FallRemote=nil,HookInstalled=false,Character=nil,Humanoid=nil,BaseSpeed=16,StateConnection=nil,CharacterConnection=nil}
            W.MAWWW_AntiSlowVault=AS
            local function AS_ResolveRemote()
                local remotes=ReplicatedStorage:FindFirstChild("Remotes"); local mechanics=remotes and remotes:FindFirstChild("Mechanics")
                AS.FallRemote=mechanics and mechanics:FindFirstChild("Fall") or nil
            end
            local function AS_InstallHook()
                if AS.HookInstalled or type(hookmetamethod)~="function" or type(getnamecallmethod)~="function" then return end
                local originalNamecall
                local wrap=(type(newcclosure)=="function") and newcclosure or function(fn) return fn end
                local ok=pcall(function()
                    originalNamecall=hookmetamethod(game,"__namecall",wrap(function(self,...)
                        local method=""; pcall(function() method=getnamecallmethod() end)
                        if AS.Enabled and method=="FireServer" and AS.FallRemote and rawequal(self,AS.FallRemote) then return nil end
                        return originalNamecall(self,...)
                    end))
                end)
                AS.HookInstalled=ok and type(originalNamecall)=="function"
            end
            local function AS_BindChar(char)
                if AS.StateConnection then pcall(function() AS.StateConnection:Disconnect() end); AS.StateConnection=nil end
                AS.Character=char; AS.Humanoid=char and (char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid",4)) or nil
                local hum=AS.Humanoid; if not hum then return end
                AS.BaseSpeed=math.max(tonumber(hum.WalkSpeed) or 16,16)
                pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,not AS.Enabled) end)
                AS.StateConnection=hum.StateChanged:Connect(function(_, state)
                    if not AS.Enabled or hum.Health<=0 then return end
                    if state==Enum.HumanoidStateType.Landed or state==Enum.HumanoidStateType.GettingUp or state==Enum.HumanoidStateType.FallingDown then
                        task.defer(function() if AS.Enabled and hum.Parent then pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end); if hum.WalkSpeed>0 and hum.WalkSpeed<AS.BaseSpeed then hum.WalkSpeed=AS.BaseSpeed end end end)
                    end
                end)
            end
            function AS.SetEnabled(value)
                AS.Enabled=value==true
                if AS.Enabled then
                    AS_ResolveRemote(); AS_InstallHook(); AS_BindChar(LocalPlayer.Character)
                    if AS.CharacterConnection then pcall(function() AS.CharacterConnection:Disconnect() end) end
                    AS.CharacterConnection=LocalPlayer.CharacterAdded:Connect(function(char) task.wait(0.25); if AS.Enabled then AS_BindChar(char) end end)
                else
                    if AS.StateConnection then pcall(function() AS.StateConnection:Disconnect() end); AS.StateConnection=nil end
                    if AS.CharacterConnection then pcall(function() AS.CharacterConnection:Disconnect() end); AS.CharacterConnection=nil end
                    if AS.Humanoid and AS.Humanoid.Parent then pcall(function() AS.Humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown,true) end) end
                end
            end
            RunService.Heartbeat:Connect(function()
                if not AS.Enabled then return end
                if not AS.FallRemote then AS_ResolveRemote() end
                local char=LocalPlayer.Character; local hum=char and char:FindFirstChildOfClass("Humanoid")
                if not char or not hum or hum.Health<=0 then return end
                if AS.Character~=char then AS_BindChar(char) end
                local blocked=char:GetAttribute("IsHooked")==true or char:GetAttribute("IsCarried")==true
                local interact=char:FindFirstChild("CheckInterractable")
                if interact then for _,attr in ipairs({"isRepairing","isHealing","isUnhooking","isSliding"}) do if interact:GetAttribute(attr)==true then blocked=true; break end end end
                if not blocked and hum.WalkSpeed>0 and hum.WalkSpeed<AS.BaseSpeed-0.05 then pcall(function() hum.WalkSpeed=AS.BaseSpeed end) end
            end)

            -- Fast Vault: point scan + movement boost and guarded client-module wrappers.
            local FV={Enabled=false,Points={},PointSet={},HookedActions=nil,HookedFacing=nil,HookReady=false}
            W.MAWWW_FastVault=FV
            local function FV_IsPoint(obj) return obj and obj:IsA("BasePart") and (obj.Name=="VaultTrigger" or obj.Name=="VaultPoint") end
            local function FV_AddPoint(obj)
                if not FV_IsPoint(obj) or FV.PointSet[obj] then return end
                FV.PointSet[obj]=true
                table.insert(FV.Points,obj)
            end
            local function FV_RemovePoint(obj)
                if not obj or not FV.PointSet[obj] then return end
                FV.PointSet[obj]=nil
                for i=#FV.Points,1,-1 do
                    if FV.Points[i]==obj then table.remove(FV.Points,i); break end
                end
            end
            for _,obj in ipairs(CollectionService:GetTagged("VaultPoint")) do FV_AddPoint(obj) end
            Workspace.DescendantAdded:Connect(FV_AddPoint)
            Workspace.DescendantRemoving:Connect(FV_RemovePoint)
            -- The old startup scan ran synchronously; batch it to reduce mobile startup heat.
            task.spawn(function()
                local ok, descendants = pcall(function() return Workspace:GetDescendants() end)
                if not ok or type(descendants) ~= "table" then return end
                for i,obj in ipairs(descendants) do
                    if obj and obj.Parent then FV_AddPoint(obj) end
                    if i % 250 == 0 then task.wait() end
                end
            end)
            local function FV_Pos(point)
                if point and point:IsA("BasePart") then return point.Position end
                if point and point:IsA("Model") then local part=point.PrimaryPart or point:FindFirstChildWhichIsA("BasePart",true); return part and part.Position end
                return nil
            end
            local function FV_Nearest(pos, maxDist)
                local nearest, best=nil,maxDist or 9
                for i=#FV.Points,1,-1 do
                    local point=FV.Points[i]
                    if not point or not point.Parent then
                        if point then FV.PointSet[point]=nil end
                        table.remove(FV.Points,i)
                    else
                        local p=FV_Pos(point)
                        if p then local d=(p-pos).Magnitude; if d<best then nearest,best=point,d end end
                    end
                end
                return nearest
            end
            local function FV_Boost(char, point)
                local root=char and char:FindFirstChild("HumanoidRootPart"); if not root then return end
                pcall(function() char:SetAttribute("Sprinting",true); char:SetAttribute("IsRunning",true) end)
                local pos=FV_Pos(point); if not pos then return end
                local delta=Vector3.new(pos.X-root.Position.X,0,pos.Z-root.Position.Z)
                if delta.Magnitude>0.05 and Vector3.new(root.AssemblyLinearVelocity.X,0,root.AssemblyLinearVelocity.Z).Magnitude<13 then
                    pcall(function() local dir=delta.Unit; local y=root.AssemblyLinearVelocity.Y; root.CFrame=CFrame.new(root.Position,root.Position+dir); root.AssemblyLinearVelocity=dir*22+Vector3.new(0,y,0) end)
                end
            end
            local function FV_TryHook()
                if FV.HookReady then return end
                local modules=ReplicatedStorage:FindFirstChild("Modules",true)
                local module=modules and modules:FindFirstChild("SurvivorActions",true)
                if module and not FV.HookedActions then
                    local ok,actions=pcall(require,module)
                    if ok and type(actions)=="table" and type(actions.startVault)=="function" then
                        local original=actions.startVault; local wrap=(type(newcclosure)=="function") and newcclosure or function(fn) return fn end
                        local okWrap,replacement=pcall(function() return wrap(function(controller,point,...)
                            if FV.Enabled then FV_Boost((controller and controller.character) or LocalPlayer.Character,point) end
                            local results=table.pack(original(controller,point,...))
                            if FV.Enabled then
                                local remotes=ReplicatedStorage:FindFirstChild("Remotes"); local window=remotes and remotes:FindFirstChild("Window")
                                local fast=window and window:FindFirstChild("fastvault"); local complete=window and window:FindFirstChild("VaultCompleteEventpart1")
                                if fast and fast:IsA("RemoteEvent") then pcall(function() fast:FireServer(LocalPlayer) end) end
                                if complete and complete:IsA("RemoteEvent") then pcall(function() complete:FireServer() end) end
                            end
                            return table.unpack(results,1,results.n)
                        end) end)
                        if okWrap and type(replacement)=="function" and pcall(function() actions.startVault=replacement end) then FV.HookedActions=actions end
                    end
                end
                local animModule=modules and modules:FindFirstChild("SurvivorAnimationsController",true)
                if animModule and not FV.HookedFacing then
                    local ok,ctrl=pcall(require,animModule)
                    if ok and type(ctrl)=="table" and type(ctrl._isFacingStraightEnough)=="function" then
                        local original=ctrl._isFacingStraightEnough; local wrap=(type(newcclosure)=="function") and newcclosure or function(fn) return fn end
                        local okWrap,replacement=pcall(function() return wrap(function(...) if FV.Enabled then return true end; return original(...) end) end)
                        if okWrap and type(replacement)=="function" and pcall(function() ctrl._isFacingStraightEnough=replacement end) then FV.HookedFacing=ctrl end
                    end
                end
                FV.HookReady=FV.HookedActions~=nil and FV.HookedFacing~=nil
            end
            function FV.SetEnabled(value)
                FV.Enabled=value==true
                if FV.Enabled then
                    FV_TryHook()
                    task.spawn(function() for _=1,12 do if not FV.Enabled or FV.HookReady then break end; task.wait(1); FV_TryHook() end end)
                end
            end
            UserInputService.InputBegan:Connect(function(input, processed)
                if not FV.Enabled or processed or GetRole()~="Survivor" then return end
                if input.KeyCode~=Enum.KeyCode.Space and input.KeyCode~=Enum.KeyCode.E then return end
                local char=LocalPlayer.Character; local root=char and char:FindFirstChild("HumanoidRootPart"); local hum=char and char:FindFirstChildOfClass("Humanoid")
                if not root or not hum or hum.Health<=0 then return end
                local point=FV_Nearest(root.Position,9); if point then FV_Boost(char,point) end
            end)
        end

