            moonwalkSection:AddDropdown({ Title = "Moonwalk Mode", Options = {"Classic", "Sway"}, Default = "Classic", ConfigId = "N3K_MoonwalkMode", Callback = function(v) if W.MAWWW_Moonwalk then W.MAWWW_Moonwalk.Mode = v or "Classic" end end })
