            -- Auto Attach Player: stay behind the selected player and follow their movement.
            local followPlayerSection = MakeSection(MiscTab, "Auto Attach Player")
            local selectedFollowPlayer = nil
            local autoAttachFollowEnabled = false
            local autoAttachFollowConnection = nil
            local autoAttachFollowDistance = 1.5
            local autoAttachFollowDirection = "Belakang"
            local autoAttachFollowVertical = 0
            local attachOffsetByDirection = {
                ["Belakang"] = Vector3.new(0, 0, 1),
                ["Kiri"] = Vector3.new(-1, 0, 0),
                ["Kanan"] = Vector3.new(1, 0, 0),
                ["Depan"] = Vector3.new(0, 0, -1),
            }

            local function GetFollowPlayerNames()
                local names = {}
                for _, targetPlayer in ipairs(Players:GetPlayers()) do
                    if targetPlayer ~= LocalPlayer then
                        table.insert(names, targetPlayer.Name)
                    end
                end
                table.sort(names)
                if #names == 0 then names[1] = "None" end
                return names
            end

            local function StopAutoAttachFollow()
                autoAttachFollowEnabled = false
                local connection = autoAttachFollowConnection
                autoAttachFollowConnection = nil
                if connection then
                    pcall(function() connection:Disconnect() end)
                end
            end

            local function StartAutoAttachFollow()
                local targetPlayer = selectedFollowPlayer and Players:FindFirstChild(selectedFollowPlayer)
                if not targetPlayer or targetPlayer == LocalPlayer then
                    StopAutoAttachFollow()
                    VD_Notify("Auto Attach Player", "Pilih player yang valid terlebih dahulu", 3)
                    return
                end

                StopAutoAttachFollow()
                autoAttachFollowEnabled = true
                autoAttachFollowConnection = RunService.Heartbeat:Connect(function()
                    if not autoAttachFollowEnabled then
                        StopAutoAttachFollow()
                        return
                    end

                    local currentTarget = selectedFollowPlayer and Players:FindFirstChild(selectedFollowPlayer)
                    if not currentTarget or currentTarget == LocalPlayer then return end

                    local targetCharacter = currentTarget.Character
                    local ownCharacter = LocalPlayer.Character
                    if not targetCharacter or not ownCharacter then return end

                    local targetRoot = targetCharacter:FindFirstChild("HumanoidRootPart")
                    local ownRoot = ownCharacter:FindFirstChild("HumanoidRootPart")
                    local targetHumanoid = targetCharacter:FindFirstChildOfClass("Humanoid")
                    local ownHumanoid = ownCharacter:FindFirstChildOfClass("Humanoid")
                    if not targetRoot or not ownRoot then return end
                    if targetHumanoid and targetHumanoid.Health <= 0 then return end
                    if ownHumanoid and ownHumanoid.Health <= 0 then return end

                    -- Keep the selected relative position, but always face the target player.
                    local directionOffset = attachOffsetByDirection[autoAttachFollowDirection] or attachOffsetByDirection["Belakang"]
                    local offsetCFrame = targetRoot.CFrame * CFrame.new(
                        directionOffset.X * autoAttachFollowDistance,
                        0,
                        directionOffset.Z * autoAttachFollowDistance
                    )
                    local desiredPosition = offsetCFrame.Position + Vector3.new(0, autoAttachFollowVertical, 0)
                    -- Aim at the target on the horizontal plane so the character stays upright.
                    local facePosition = Vector3.new(targetRoot.Position.X, desiredPosition.Y, targetRoot.Position.Z)
                    local desiredCFrame = CFrame.lookAt(desiredPosition, facePosition)
                    pcall(function()
                        if ownRoot.Parent and targetRoot.Parent and currentTarget.Character == targetCharacter then
                            ownRoot.CFrame = desiredCFrame
                        end
                    end)
                end)
                VD_Notify("Auto Attach Player", "Mengikuti dari belakang: " .. targetPlayer.Name, 2)
            end

            local initialFollowPlayerNames = GetFollowPlayerNames()
            if initialFollowPlayerNames[1] and initialFollowPlayerNames[1] ~= "None" then
                selectedFollowPlayer = initialFollowPlayerNames[1]
            end
            local followPlayerDropdown = followPlayerSection:AddDropdown({
                Title = "Select Player",
                Options = initialFollowPlayerNames,
                Default = selectedFollowPlayer or "None",
                Multi = false,
                ConfigId = "AutoAttachPlayerTarget",
                Callback = function(value)
                    local selected = type(value) == "table" and value[1] or value
                    selectedFollowPlayer = (selected and tostring(selected) ~= "None") and tostring(selected) or nil
                end
            })

            local function RefreshFollowPlayerList()
                local names = GetFollowPlayerNames()
                local chosen = nil
                for _, name in ipairs(names) do
                    if name == selectedFollowPlayer then chosen = name; break end
                end
                if not chosen then chosen = names[1] end

                local dropdownApis = getgenv().__MAWWW_DropdownAPIs
                local api = dropdownApis and followPlayerDropdown and dropdownApis[followPlayerDropdown]
                if api and type(api.SetValues) == "function" then
                    pcall(function() api.SetValues(names, chosen, true) end)
                end
                selectedFollowPlayer = (chosen and chosen ~= "None") and chosen or nil
            end

            followPlayerSection:AddButton({
                Title = "Refresh Player List",
                Callback = function()
                    RefreshFollowPlayerList()
                    VD_Notify("Auto Attach Player", "Daftar player diperbarui", 2)
                end
            })
            followPlayerSection:AddDropdown({
                Title = "Attach Position",
                Content = "Pilih posisi relatif terhadap arah target",
                Options = {"Belakang", "Kiri", "Kanan", "Depan"},
                Default = autoAttachFollowDirection,
                Multi = false,
                ConfigId = "AutoAttachPlayerDirection",
                Callback = function(value)
                    local selected = type(value) == "table" and value[1] or value
