            })
            followPlayerSection:AddSlider({
                Title = "Attach Distance",
                Content = "Jarak dari target (lebih kecil = lebih dekat)",
                Min = 0.5, Max = 8, Default = 1.5, Increment = 0.5,
                Suffix = " studs",
