    local function __MAWWW_DecodeQRBase64(encoded)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for i = 1, #alphabet do
            lookup[alphabet:sub(i, i)] = i - 1
        end

        local output = {}
        local buffer, bits = 0, 0
        for i = 1, #encoded do
            local ch = encoded:sub(i, i)
            local value = lookup[ch]
            if value ~= nil then
                buffer = buffer * 64 + value
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    local byteValue = math.floor(buffer / (2 ^ bits)) % 256
                    output[#output + 1] = string.char(byteValue)
                    buffer = buffer % (2 ^ bits)
                end
            elseif ch == "=" then
                break
            end
        end
        return table.concat(output)
    end

    local function __MAWWW_GetQRPhotoAsset()
        local assetLoader = nil
        if type(getcustomasset) == "function" then
            assetLoader = getcustomasset
        elseif type(getsynasset) == "function" then
            assetLoader = getsynasset
        end
        if not assetLoader or type(writefile) ~= "function" then
            return nil
        end

        local fileName = "MAWWW_HUB_QR_Poster.jpg"
        local imageBytes = __MAWWW_DecodeQRBase64(QR_IMAGE_BASE64)
        local wrote = pcall(function()
            writefile(fileName, imageBytes)
        end)
        if not wrote then
            return nil
        end

        local okAsset, asset = pcall(assetLoader, fileName)
        if okAsset and type(asset) == "string" and asset ~= "" then
            return asset
        end
        return nil
    end

    -- Load embedded background photos through executor-local asset support.
    local function __MAWWW_GetEmbeddedPhotoAsset(encoded, fileName)
        local assetLoader = nil
        if type(getcustomasset) == "function" then
            assetLoader = getcustomasset
        elseif type(getsynasset) == "function" then
            assetLoader = getsynasset
        end
        if not assetLoader or type(writefile) ~= "function" then
            return nil
        end

        local imageBytes = __MAWWW_DecodeQRBase64(encoded)
        local wrote = pcall(function()
            writefile(fileName, imageBytes)
        end)
        if not wrote then return nil end

        local okAsset, asset = pcall(assetLoader, fileName)
        if okAsset and type(asset) == "string" and asset ~= "" then
            return asset
        end
        return nil
    end

