    -- Lightweight sparkle/glow overlay. Accent palettes are intentionally different per BG.
    local BG_EFFECT_PALETTES = {
        [1] = {tint = Color3.fromRGB(55, 205, 255), primary = Color3.fromRGB(78, 225, 255), secondary = Color3.fromRGB(205, 250, 255)},
        [2] = {tint = Color3.fromRGB(115, 55, 220), primary = Color3.fromRGB(175, 105, 255), secondary = Color3.fromRGB(255, 135, 235)},
        [3] = {tint = Color3.fromRGB(245, 170, 55), primary = Color3.fromRGB(255, 205, 90), secondary = Color3.fromRGB(255, 246, 190)},
        [4] = {tint = Color3.fromRGB(225, 65, 165), primary = Color3.fromRGB(255, 105, 205), secondary = Color3.fromRGB(165, 235, 255)},
    }

    local backgroundGlowTint = new("Frame", {
        Name = "MainBackgroundGlowTint",
        BackgroundColor3 = BG_EFFECT_PALETTES[currentBackgroundIndex].tint,
