    for i, spec in ipairs(sparkleLayout) do
        local x, y, size = spec[1], spec[2], spec[3]
        local palette = BG_EFFECT_PALETTES[currentBackgroundIndex]
        local sparkleColor = (i % 2 == 0) and palette.secondary or palette.primary
        local glow = new("Frame", {
            Name = "BackgroundGlow" .. tostring(i),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(x, y),
