            ZIndex = 3,
        }, backgroundEffectsLayer)
        corner(glow, 99)
        local outline = stroke(glow, sparkleColor, 1.1, 0.40)

        local star = new("TextLabel", {
            Name = "BackgroundSparkle" .. tostring(i),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(x, y),
            Size = UDim2.fromOffset(size * 2, size * 2),
            BackgroundTransparency = 1,
