        Position = UDim2.fromScale(1.12, -0.12),
        Size = UDim2.fromOffset(270, 10),
        Rotation = 135,
        BackgroundColor3 = BG_EFFECT_PALETTES[currentBackgroundIndex].primary,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 5,
    }, backgroundEffectsLayer)
    corner(backgroundFlashGlow, 99)

    backgroundFlashCore = new("Frame", {
        Name = "MainBackgroundFlashCore",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(1.12, -0.12),
        Size = UDim2.fromOffset(230, 2),
        Rotation = 135,
        BackgroundColor3 = BG_EFFECT_PALETTES[currentBackgroundIndex].secondary,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 6,
    }, backgroundEffectsLayer)
    corner(backgroundFlashCore, 99)

    backgroundFlashSide = new("Frame", {
        Name = "MainBackgroundFlashSide",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(1.08, -0.02),
        Size = UDim2.fromOffset(115, 2),
        Rotation = 135,
        BackgroundColor3 = BG_EFFECT_PALETTES[currentBackgroundIndex].primary,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 5,
    }, backgroundEffectsLayer)
    corner(backgroundFlashSide, 99)

    local function __MAWWW_PlayBackgroundLightFlash()
        if not (backgroundEffectsLayer.Parent and backgroundFlashOverlay.Parent) then return end
        local palette = BG_EFFECT_PALETTES[currentBackgroundIndex] or BG_EFFECT_PALETTES[1]

        -- A brief color pulse brightens the image, then fades immediately.
        backgroundFlashOverlay.BackgroundColor3 = palette.secondary
        backgroundFlashOverlay.BackgroundTransparency = 0.90
        TweenService:Create(backgroundFlashOverlay,
            TweenInfo.new(0.20, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {BackgroundTransparency = 1}
        ):Play()

        -- Colored outer glow + narrow white/secondary core travel upper-right to lower-left.
        backgroundFlashGlow.BackgroundColor3 = palette.primary
        backgroundFlashCore.BackgroundColor3 = palette.secondary
        backgroundFlashSide.BackgroundColor3 = palette.primary

        backgroundFlashGlow.Position = UDim2.fromScale(1.12, -0.12)
        backgroundFlashCore.Position = UDim2.fromScale(1.12, -0.12)
        backgroundFlashSide.Position = UDim2.fromScale(1.06, 0.02)
        backgroundFlashGlow.BackgroundTransparency = 0.48
        backgroundFlashCore.BackgroundTransparency = 0.12
        backgroundFlashSide.BackgroundTransparency = 0.30
        backgroundFlashGlow.Visible = true
        backgroundFlashCore.Visible = true
        backgroundFlashSide.Visible = true

        local duration = 0.46 + math.random() * 0.16
        local info = TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        TweenService:Create(backgroundFlashGlow, info, {
            Position = UDim2.fromScale(-0.12, 1.12), BackgroundTransparency = 1,
        }):Play()
        TweenService:Create(backgroundFlashCore, info, {
            Position = UDim2.fromScale(-0.12, 1.12), BackgroundTransparency = 1,
        }):Play()
        TweenService:Create(backgroundFlashSide, info, {
            Position = UDim2.fromScale(-0.10, 1.08), BackgroundTransparency = 1,
        }):Play()

        task.delay(duration + 0.03, function()
            pcall(function()
                backgroundFlashGlow.Visible = false
                backgroundFlashCore.Visible = false
                backgroundFlashSide.Visible = false
            end)
        end)
    end

    -- Random, brief light flashes keep the effect visible without a heavy per-frame loop.
    task.spawn(function()
        while main.Parent and featureGui.Parent and backgroundEffectsLayer.Parent do
            task.wait(math.random(17, 29) / 10)
            if main.Parent and featureGui.Parent and backgroundEffectsLayer.Parent then
                pcall(__MAWWW_PlayBackgroundLightFlash)
            end
        end
    end)

    -- A single low-frequency task animates the light particles to minimize overhead.
    task.spawn(function()
        while main.Parent and featureGui.Parent and backgroundEffectsLayer.Parent do
            -- Pulse the currently selected background photo with its own color palette.
            -- BG1: cyan, BG2: violet, BG3: gold, BG4: pink/cyan.
            local activePalette = BG_EFFECT_PALETTES[currentBackgroundIndex] or BG_EFFECT_PALETTES[1]
            local pulseBright = math.random(1, 100) <= 42
            pcall(function()
                TweenService:Create(backgroundGlowTint,
                    TweenInfo.new(0.52, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                    {
                        BackgroundColor3 = pulseBright and activePalette.primary or activePalette.tint,
                        BackgroundTransparency = pulseBright and 0.89 or 0.965,
                    }
                ):Play()
            end)

            for _, particle in ipairs(backgroundSparkles) do
                -- Sweep from upper-right to lower-left. Each particle keeps its own phase,
                -- then respawns near the top/right edge after leaving the visible window.
                local step = 0.014 + ((particle.index % 4) * 0.0035)
                local nextX = (tonumber(particle.currentX) or particle.x) - step
                local nextY = (tonumber(particle.currentY) or particle.y) + step
                if nextX < -0.04 or nextY > 1.04 then
                    nextX = 1.02 + math.random() * 0.10
                    nextY = -0.12 + math.random() * 0.34
                end
                particle.currentX = nextX
                particle.currentY = nextY

                local bright = math.random(1, 100) <= 58
                local duration = 0.42 + math.random() * 0.24
                local sizeScale = bright and 1.24 or 0.78
                local targetPos = UDim2.fromScale(nextX, nextY)
                pcall(function()
                    TweenService:Create(particle.star,
                        TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                        {
                            TextTransparency = bright and 0.06 or 0.82,
                            Rotation = math.random(-28, 28),
                            Position = targetPos,
                        }
                    ):Play()
                    TweenService:Create(particle.glow,
                        TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                        {
                            BackgroundTransparency = bright and 0.68 or 0.94,
                            Size = UDim2.fromOffset(particle.size * sizeScale, particle.size * sizeScale),
                            Position = targetPos,
                        }
                    ):Play()
                    TweenService:Create(particle.outline,
                        TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                        {Transparency = bright and 0.16 or 0.80}
                    ):Play()
                end)
            end
            task.wait(0.62)
        end
    end)

    local function __MAWWW_StopBackgroundCycle()
        if bgCycleEnabled then
            bgCycleEnabled = false
            bgCycleToken = bgCycleToken + 1
            if bgCycleButton then bgCycleButton.Text = "AUTO ROTATE: OFF" end
            if bgCycleStroke then bgCycleStroke.Color = COLORS.Stroke end
            bgSelectorButtonStroke.Color = COLORS.Stroke
        end
    end

    local function __MAWWW_ApplyMainBackground(index, fromManualSelection, animateChange)
        index = math.clamp(tonumber(index) or 1, 1, #INFO_FLICKER_IMAGES)
        if fromManualSelection then
            __MAWWW_StopBackgroundCycle()
        end

        currentBackgroundIndex = index
        __MAWWW_ApplyBackgroundEffectPalette(index, animateChange)
        pcall(function()
            -- This is the ImageLabel parented directly to MainWindow, behind every tab.
            if animateChange then background.ImageTransparency = 0.46 end
            background.Image = INFO_FLICKER_IMAGES[index]
            if animateChange then
                TweenService:Create(
                    background,
                    TweenInfo.new(0.24, Enum.EasingStyle.Sine, Enum.EasingDirection.Out),
                    { ImageTransparency = 0 }
                ):Play()
            else
                background.ImageTransparency = 0
            end
        end)

        bgSelectedLabel.Text = "Selected: Background " .. tostring(index)
        for i, button in ipairs(bgButtons) do
            local selectionStroke = button:FindFirstChild("SelectionStroke")
            if selectionStroke then
                selectionStroke.Color = (i == index) and COLORS.Cyan or COLORS.Stroke
                selectionStroke.Thickness = (i == index) and 2 or 1
                selectionStroke.Transparency = (i == index) and 0 or 0.30
            end
        end
    end

    for i, imageId in ipairs(INFO_FLICKER_IMAGES) do
        local thumb = new("ImageButton", {
            Name = "MainBackgroundChoice" .. tostring(i),
            BackgroundColor3 = COLORS.Panel3,
            BackgroundTransparency = 0.02,
            BorderSizePixel = 0,
            Image = imageId,
            ImageTransparency = 0,
            ScaleType = Enum.ScaleType.Crop,
            AutoButtonColor = false,
            Position = UDim2.fromOffset(8 + ((i - 1) * 54), 41),
            Size = UDim2.fromOffset(48, 51),
            ZIndex = 501,
        }, bgPopup)
        corner(thumb, 6)
        local thumbStroke = stroke(thumb, COLORS.Stroke, 1, 0.30)
        thumbStroke.Name = "SelectionStroke"
        bgButtons[i] = thumb

        local thumbText = makeLabel(thumb, "BG " .. tostring(i), 7,
            UDim2.new(0, 0, 1, -15), UDim2.new(1, 0, 0, 15),
            Enum.Font.GothamBold, COLORS.Text, 503)
        thumbText.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        thumbText.BackgroundTransparency = 0.30

        thumb.Activated:Connect(function()
            __MAWWW_ApplyMainBackground(i, true, true)
        end)
    end

    bgCycleButton = new("TextButton", {
        Name = "MainBackgroundAutoRotateButton",
        Position = UDim2.fromOffset(8, 101),
        Size = UDim2.new(1, -16, 0, 31),
        BackgroundColor3 = COLORS.Panel3,
        BackgroundTransparency = 0.02,
        BorderSizePixel = 0,
        Text = "AUTO ROTATE: OFF",
        TextColor3 = COLORS.Text,
        TextSize = 8,
        Font = Enum.Font.GothamBold,
        AutoButtonColor = false,
        ZIndex = 501,
    }, bgPopup)
    corner(bgCycleButton, 7)
    bgCycleStroke = stroke(bgCycleButton, COLORS.Stroke, 1, 0.25)

    bgSelectorButton.Activated:Connect(function()
        bgPopup.Visible = not bgPopup.Visible
        bgSelectorButtonStroke.Color = bgPopup.Visible and COLORS.Cyan or COLORS.Stroke
    end)

    bgCycleButton.Activated:Connect(function()
        if bgCycleEnabled then
            __MAWWW_StopBackgroundCycle()
            return
        end
        bgCycleEnabled = true
        bgCycleToken = bgCycleToken + 1
        local thisToken = bgCycleToken
        bgCycleButton.Text = "AUTO ROTATE: ON"
        bgCycleStroke.Color = COLORS.Cyan
        bgSelectorButtonStroke.Color = COLORS.Cyan
        task.spawn(function()
            while bgCycleEnabled and bgCycleToken == thisToken
                and bgPopup.Parent and background.Parent and main.Parent do
                task.wait(2.5)
                if not (bgCycleEnabled and bgCycleToken == thisToken
                    and bgPopup.Parent and background.Parent and main.Parent) then
                    break
                end
                __MAWWW_ApplyMainBackground((currentBackgroundIndex % #INFO_FLICKER_IMAGES) + 1, false, true)
            end
        end)
    end)

    -- Keep the selected background on the actual window, not inside a tab card.
    __MAWWW_ApplyMainBackground(2, false, false)

    featureGui.Destroying:Connect(function()
        bgCycleEnabled = false
        bgCycleToken = bgCycleToken + 1
    end)

