        Position = UDim2.fromOffset(258, 69),
        BackgroundTransparency = 1,
        Text = "↝",
        Font = Enum.Font.GothamBold,
        TextSize = 19,
        TextColor3 = COLORS.Muted,
        AutoButtonColor = false,
        ZIndex = 954,
    }, floating)

    local floatingRepeat = new("TextButton", {
        Size = UDim2.fromOffset(30, 30),
        Position = UDim2.fromOffset(290, 69),
        BackgroundTransparency = 1,
        Text = "↻",
        Font = Enum.Font.GothamBold,
        TextSize = 19,
        TextColor3 = COLORS.Muted,
        AutoButtonColor = false,
        ZIndex = 954,
    }, floating)

    local visualizer = new("Frame", {
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(124, 105),
        Size = UDim2.new(1, -134, 0, 25),
        ZIndex = 953,
    }, floating)

    local visualizerBars = {}
    for i = 1, 22 do
        local bar = new("Frame", {
            BackgroundColor3 = COLORS.Cyan,
            BackgroundTransparency = 0.08,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(0.5, 1),
            Position = UDim2.new((i - 0.5) / 22, 0, 1, 0),
            Size = UDim2.new(0, 3, 0, 5),
            ZIndex = 954,
        }, visualizer)
        corner(bar, 3)
        visualizerBars[i] = bar
    end

    local draggingFloating = false
    local dragStart
    local floatingStart

    floating.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingFloating = true
            dragStart = input.Position
            floatingStart = floating.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    draggingFloating = false
                end
            end)
        end
    end)

    table.insert(musicConnections, UserInputService.InputChanged:Connect(function(input)
        if not draggingFloating or not dragStart or not floatingStart then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        local delta = input.Position - dragStart
        floating.Position = UDim2.new(
            floatingStart.X.Scale, floatingStart.X.Offset + delta.X,
            floatingStart.Y.Scale, floatingStart.Y.Offset + delta.Y
        )
    end))

    local function musicFormatTime(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
    end

    local function musicUpdateFloating()
        local song = MUSIC_SONGS[musicCurrent]
        if not song then return end
        floatingTitle.Text = song.name
        floatingArtist.Text = song.artist ~= "" and song.artist or ("MAWWW HUB • Track " .. tostring(musicCurrent))
        if musicSound.IsPlaying then
            floatingPlay.Text = "Ⅱ"
        else
            floatingPlay.Text = "▶"
        end
    end

    local function musicHighlight()
        for _, child in ipairs(musicPage:GetChildren()) do
            local idx = child:GetAttribute("MAWWWMusicIndex")
            if idx then
                child.BackgroundColor3 = (idx == musicCurrent)
                    and Color3.fromRGB(24, 91, 130)
                    or COLORS.Panel2
            end
        end
    end

    local function musicSetFloatingVisible(enabled)
        musicFloatingVisible = enabled == true
        floating.Visible = musicFloatingVisible
        showFloating.Text = musicFloatingVisible and "FLOAT ON" or "FLOAT OFF"
        showFloating.TextColor3 = musicFloatingVisible and COLORS.Cyan or COLORS.Muted
        showFloating.BackgroundColor3 = musicFloatingVisible and Color3.fromRGB(24, 91, 130) or COLORS.Panel3
    end

    local function musicNextIndex()
        if musicShuffle then
            if #MUSIC_SONGS <= 1 then return musicCurrent end
            local nextIndex = musicCurrent
            for _ = 1, 8 do
                nextIndex = math.random(1, #MUSIC_SONGS)
                if nextIndex ~= musicCurrent then break end
            end
            return nextIndex
        end
        return (musicCurrent % #MUSIC_SONGS) + 1
    end

    local function musicLoadSong(index, autoplay)
        if not MUSIC_SONGS[index] then return end
        musicLoadToken += 1
        local myToken = musicLoadToken
        musicCurrent = index
        local song = MUSIC_SONGS[index]

        musicSound:Stop()
        musicSound.SoundId = ""
        musicSound.TimePosition = 0
        musicLoading = true
        musicUpdateFloating()
        musicHighlight()

        task.spawn(function()
            local okSet = pcall(function()
                musicSound.SoundId = song.id
            end)
            if not okSet or myToken ~= musicLoadToken then
                musicLoading = false
                return
            end

            local loaded = false
            local failed = false
            local loadedConnection = musicSound.Loaded:Connect(function()
                loaded = true
            end)

            local okPreload = pcall(function()
                MusicContentProvider:PreloadAsync({musicSound})
            end)
            if not okPreload then
                failed = true
            end

            local deadline = os.clock() + 8
            while not loaded and not failed and os.clock() < deadline do
                if myToken ~= musicLoadToken then
                    loadedConnection:Disconnect()
                    return
                end
                if musicSound.TimeLength > 0 then
                    loaded = true
                    break
                end
                task.wait(0.1)
            end
            loadedConnection:Disconnect()

            if myToken ~= musicLoadToken then return end

            musicLoading = false
            if not loaded or musicSound.TimeLength <= 0 then
                floatingTitle.Text = "Audio gagal dimuat"
                floatingArtist.Text = song.name
                floatingPlay.Text = "▶"
                task.wait(0.25)
                if myToken == musicLoadToken then
                    local nextIndex = musicNextIndex()
                    if nextIndex ~= index then
                        musicLoadSong(nextIndex, true)
                    end
                end
                return
            end

            musicUpdateFloating()
            if autoplay then
                pcall(function() musicSound:Play() end)
            end
            musicUpdateFloating()
        end)
    end

    local musicListCard = new("Frame", {
        BackgroundColor3 = COLORS.Panel2,
        BackgroundTransparency = 0.10,
        BorderSizePixel = 0,
        Size = UDim2.new(1, -2, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        LayoutOrder = 2,
        ZIndex = 21,
    }, musicPage)
    corner(musicListCard, 10)
    stroke(musicListCard, COLORS.Stroke, 1, 0.55)

    local musicListTitle = makeLabel(musicListCard,
        "PLAYLIST • " .. tostring(#MUSIC_SONGS) .. " SONGS", 10,
        UDim2.fromOffset(12, 10), UDim2.new(1, -24, 0, 22),
        Enum.Font.GothamBold, COLORS.Text, 22)
    musicListTitle.TextXAlignment = Enum.TextXAlignment.Left

    local musicListHolder = new("Frame", {
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(7, 38),
        Size = UDim2.new(1, -14, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        ZIndex = 22,
    }, musicListCard)

    new("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 4),
    }, musicListHolder)

    new("UIPadding", {
        PaddingBottom = UDim.new(0, 8),
