    for index, song in ipairs(MUSIC_SONGS) do
        local row = new("TextButton", {
            Size = UDim2.new(1, 0, 0, 42),
            BackgroundColor3 = COLORS.Panel2,
            BackgroundTransparency = 0.02,
            BorderSizePixel = 0,
            Text = "",
            AutoButtonColor = false,
            LayoutOrder = index,
            ZIndex = 23,
        }, musicListHolder)
        corner(row, 8)

        new("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(10, 5),
            Size = UDim2.fromOffset(28, 31),
            Font = Enum.Font.GothamBold,
            Text = string.format("%02d", index),
            TextColor3 = COLORS.Muted,
            TextSize = 9,
            TextXAlignment = Enum.TextXAlignment.Center,
            ZIndex = 24,
        }, row)

        local rowTitle = new("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(45, 4),
            Size = UDim2.new(1, -57, 0, 19),
            Font = Enum.Font.GothamSemibold,
            Text = song.name,
            TextColor3 = COLORS.Text,
            TextSize = 9,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 24,
        }, row)

        local rowSub = new("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(45, 23),
            Size = UDim2.new(1, -57, 0, 13),
            Font = Enum.Font.Gotham,
            Text = song.artist ~= "" and song.artist or ("Track " .. tostring(index)),
            TextColor3 = COLORS.Muted,
            TextSize = 7,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 24,
        }, row)

        row:SetAttribute("MAWWWMusicIndex", index)

        row.Activated:Connect(function()
            musicLoadSong(index, true)
        end)
        row.MouseEnter:Connect(function()
            if index ~= musicCurrent then
                row.BackgroundColor3 = Color3.fromRGB(20, 57, 80)
            end
        end)
        row.MouseLeave:Connect(function()
            if index ~= musicCurrent then
                row.BackgroundColor3 = COLORS.Panel2
            end
        end)
    end

    local function musicTogglePlay()
        if musicLoading then return end
        if not MUSIC_SONGS[musicCurrent] then musicCurrent = 1 end

        if musicSound.SoundId == "" then
            musicLoadSong(musicCurrent, true)
            return
        end

        if musicSound.IsPlaying then
            musicSound:Pause()
        else
            pcall(function() musicSound:Play() end)
        end
        musicUpdateFloating()
    end

    local function musicPrev()
        local index = musicCurrent - 1
        if index < 1 then index = #MUSIC_SONGS end
        musicLoadSong(index, true)
    end

    local function musicNext()
        musicLoadSong(musicNextIndex(), true)
    end

    showFloating.Activated:Connect(function()
        musicSetFloatingVisible(not musicFloatingVisible)
    end)

    stopMusic.Activated:Connect(function()
        musicLoadToken += 1
        musicLoading = false
        pcall(function() musicSound:Stop() end)
        musicSound.TimePosition = 0
        musicUpdateFloating()
    end)

    floatingPlay.Activated:Connect(musicTogglePlay)
    floatingPrev.Activated:Connect(musicPrev)
    floatingNext.Activated:Connect(musicNext)

    floatingShuffle.Activated:Connect(function()
        musicShuffle = not musicShuffle
        floatingShuffle.TextColor3 = musicShuffle and COLORS.Cyan or COLORS.Muted
    end)

    floatingRepeat.Activated:Connect(function()
        musicRepeat = not musicRepeat
        floatingRepeat.TextColor3 = musicRepeat and COLORS.Cyan or COLORS.Muted
    end)

    floatingHeart.Activated:Connect(function()
        floatingHeart.Text = floatingHeart.Text == "♡" and "♥" or "♡"
        floatingHeart.TextColor3 = floatingHeart.Text == "♥" and COLORS.Cyan or COLORS.Text
    end)

    table.insert(musicConnections, musicSound.Ended:Connect(function()
        if musicRepeat then
            musicLoadSong(musicCurrent, true)
        else
            musicLoadSong(musicNextIndex(), true)
        end
    end))

    table.insert(musicConnections, RunService.RenderStepped:Connect(function()
        local length = musicSound.TimeLength
        local position = musicSound.TimePosition

        if length > 0 then
            floatingProgress.Size = UDim2.new(
                math.clamp(position / length, 0, 1), 0, 1, 0
            )
        else
            floatingProgress.Size = UDim2.new(0, 0, 1, 0)
        end

        if musicFloatingVisible then
            local active = musicSound.IsPlaying
            for i, bar in ipairs(visualizerBars) do
                local wave = math.abs(math.sin(os.clock() * (3 + i * 0.17)))
                local height = active and (5 + math.floor(wave * 17)) or 5
                bar.Size = UDim2.new(0, 3, 0, height)
            end
        end

        musicUpdateFloating()
    end))

    musicSetFloatingVisible(false)
    musicHighlight()

    local tabs = {"INFORMATION", "SURVIVE", "KILLER", "VISUAL", "MISC", "SAVE", "MUSIC"}
    local buttons = {}

    local function showPage(name)
        local key = string.upper(tostring(name))
        if bgPopup then bgPopup.Visible = false end
        for childName, child in pairs(page:GetChildren()) do
            if child:IsA("ScrollingFrame") then
                child.Visible = (child.Name == "FeaturePage_" .. key)
            end
        end
        if pageTitle then
            pageTitle.Text = key
        end
        if pageSubtitle then
            pageSubtitle.Text = "MAWWW HUB • " .. tostring(scriptName or "VILONCE DISTRICT")
        end
        for buttonName, button in pairs(buttons) do
            button.BackgroundColor3 =
                (buttonName == key)
                and Color3.fromRGB(24, 91, 130)
                or COLORS.Panel2
            button.TextColor3 =
                (buttonName == key)
                and COLORS.Cyan
                or COLORS.Text
        end
    end

    for i, name in ipairs(tabs) do
        local button = new("TextButton", {
            LayoutOrder = i,
            Size = UDim2.new(1, -14, 0, 34),
            Position = UDim2.fromOffset(7, 7 + (i - 1) * 39),
            BackgroundColor3 = COLORS.Panel2,
            BackgroundTransparency = 0.08,
            BorderSizePixel = 0,
            Text = name,
            Font = Enum.Font.GothamBold,
            TextSize = 10,
            TextColor3 = COLORS.Text,
            AutoButtonColor = false,
            ZIndex = 7,
        }, sidebar)
        corner(button, 9)
        buttons[name] = button
        button.Activated:Connect(function()
            showPage(name)
        end)
    end

