        local function decodeAndLoadFloatingImage(fileName, encodedImage)
            local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local lookup = {}
            for i = 1, #alphabet do
                lookup[string.sub(alphabet, i, i)] = i - 1
            end

            local output = {}
            local buffer, bitCount = 0, 0
            for i = 1, #encodedImage do
                local char = string.sub(encodedImage, i, i)
                if char == "=" then break end
                local value = lookup[char]
                if value ~= nil then
                    buffer = buffer * 64 + value
                    bitCount = bitCount + 6
                    if bitCount >= 8 then
                        bitCount = bitCount - 8
                        output[#output + 1] = string.char(math.floor(buffer / (2 ^ bitCount)) % 256)
                        buffer = buffer % (2 ^ bitCount)
                    end
                end
            end

            writefile(fileName, table.concat(output))
            return assetGetter(fileName)
        end

        if type(writefile) == "function" and type(assetGetter) == "function" then
            local openOk, openUri = pcall(function()
                return decodeAndLoadFloatingImage(
                    "mawww_hub_mawww_catgirl_floating_icon_open.png",
                    MAWWW_FLOATING_LOGO_OPEN_BASE64
                )
            end)
            if openOk and type(openUri) == "string" and openUri ~= "" then
                MAWWW_FLOATING_LOGO_IMAGE = openUri
            end

            local closedOk, closedUri = pcall(function()
                return decodeAndLoadFloatingImage(
                    "mawww_hub_mawww_catgirl_floating_icon_closed.png",
                    MAWWW_FLOATING_LOGO_CLOSED_BASE64
                )
            end)
            if closedOk and type(closedUri) == "string" and closedUri ~= "" then
                MAWWW_FLOATING_LOGO_CLOSED_IMAGE = closedUri
            else
                MAWWW_FLOATING_LOGO_CLOSED_IMAGE = MAWWW_FLOATING_LOGO_IMAGE
            end

            local headOpenOk, headOpenUri = pcall(function()
                return decodeAndLoadFloatingImage(
                    "mawww_hub_catgirl_head_motion_open.png",
                    MAWWW_FLOATING_HEAD_OPEN_BASE64
                )
            end)
            if headOpenOk and type(headOpenUri) == "string" and headOpenUri ~= "" then
                MAWWW_FLOATING_HEAD_OPEN_IMAGE = headOpenUri
            end

            local headClosedOk, headClosedUri = pcall(function()
                return decodeAndLoadFloatingImage(
                    "mawww_hub_catgirl_head_motion_closed.png",
                    MAWWW_FLOATING_HEAD_CLOSED_BASE64
                )
            end)
            if headClosedOk and type(headClosedUri) == "string" and headClosedUri ~= "" then
                MAWWW_FLOATING_HEAD_CLOSED_IMAGE = headClosedUri
            else
                MAWWW_FLOATING_HEAD_CLOSED_IMAGE = MAWWW_FLOATING_HEAD_OPEN_IMAGE
            end

            local hairOk, hairUri = pcall(function()
                return decodeAndLoadFloatingImage(
                    "mawww_hub_catgirl_hair_motion_layer.png",
                    MAWWW_FLOATING_HAIR_LAYER_BASE64
                )
            end)
            if hairOk and type(hairUri) == "string" and hairUri ~= "" then
                MAWWW_FLOATING_HAIR_LAYER_IMAGE = hairUri
            end

            local bodyOk, bodyUri = pcall(function()
                return decodeAndLoadFloatingImage(
                    "mawww_hub_catgirl_body_motion_layer.png",
                    MAWWW_FLOATING_BODY_LAYER_BASE64
                )
            end)
            if bodyOk and type(bodyUri) == "string" and bodyUri ~= "" then
                MAWWW_FLOATING_BODY_LAYER_IMAGE = bodyUri
            end

            -- Do not show an inpainted backing frame without its matching layers.
            if not (openOk and closedOk and headOpenOk and headClosedOk and hairOk and bodyOk
                and type(openUri) == "string" and openUri ~= ""
                and type(closedUri) == "string" and closedUri ~= ""
                and type(headOpenUri) == "string" and headOpenUri ~= ""
                and type(headClosedUri) == "string" and headClosedUri ~= ""
                and type(hairUri) == "string" and hairUri ~= ""
                and type(bodyUri) == "string" and bodyUri ~= "") then
                MAWWW_FLOATING_LOGO_IMAGE = LOGO
                MAWWW_FLOATING_LOGO_CLOSED_IMAGE = LOGO
                MAWWW_FLOATING_HEAD_OPEN_IMAGE = nil
                MAWWW_FLOATING_HEAD_CLOSED_IMAGE = nil
                MAWWW_FLOATING_HAIR_LAYER_IMAGE = nil
                MAWWW_FLOATING_BODY_LAYER_IMAGE = nil
            end
        else
            -- Keep the prior Roblox asset as a safe fallback on executors without local assets.
            MAWWW_FLOATING_LOGO_CLOSED_IMAGE = MAWWW_FLOATING_LOGO_IMAGE
            MAWWW_FLOATING_HEAD_OPEN_IMAGE = nil
            MAWWW_FLOATING_HEAD_CLOSED_IMAGE = nil
            MAWWW_FLOATING_HAIR_LAYER_IMAGE = nil
            MAWWW_FLOATING_BODY_LAYER_IMAGE = nil
        end
    end

    -- Compact, backgroundless restore icon. The ImageButton remains the single
    -- touch target; only the transparent logo artwork is visible.
    local restore = new("ImageButton", {
        Name = "MAWWWRestore",
        Size = UDim2.fromOffset(54, 54),
        Position = UDim2.new(0, 16, 0.28, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = "",
        ImageTransparency = 1,
        AutoButtonColor = false,
        Active = true,
        Selectable = false,
        Visible = true, -- Show the single floating icon after the key screen is dismissed.
        ZIndex = 1200,
    }, featureGui)

    local restoreArt = new("ImageLabel", {
        Name = "LogoArt",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(50, 50),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = MAWWW_FLOATING_LOGO_IMAGE,
        ImageTransparency = 0,
        ScaleType = Enum.ScaleType.Fit,
        Active = false,
        ZIndex = 1201,
    }, restore)

    -- Keep the entire button, ring, and badge fixed. The transparent cutout moves
    -- around a neck-level pivot so only the character's head/hair performs the shake.
    local headMotionArt = nil
    local headPivot = nil
    if type(MAWWW_FLOATING_HEAD_OPEN_IMAGE) == "string"
        and MAWWW_FLOATING_HEAD_OPEN_IMAGE ~= "" then
        headPivot = new("Frame", {
            Name = "HeadMotionPivot",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.64, 0),
            Size = UDim2.fromOffset(50, 50),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Rotation = 0,
            Active = false,
            Selectable = false,
            ZIndex = 1202,
        }, restore)
        headPivot.ClipsDescendants = false

        headMotionArt = new("ImageLabel", {
            Name = "HeadMotionArt",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.35, 0),
            Size = UDim2.fromOffset(50, 50),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Image = MAWWW_FLOATING_HEAD_OPEN_IMAGE,
            ImageTransparency = 0,
            ScaleType = Enum.ScaleType.Fit,
            Active = false,
            Selectable = false,
            ZIndex = 1202,
        }, headPivot)
    end

    -- Only separated hair and torso layers sway a tiny amount, using smooth sine tweens.
    if type(MAWWW_FLOATING_HAIR_LAYER_IMAGE) == "string"
        and MAWWW_FLOATING_HAIR_LAYER_IMAGE ~= ""
        and type(MAWWW_FLOATING_BODY_LAYER_IMAGE) == "string"
        and MAWWW_FLOATING_BODY_LAYER_IMAGE ~= "" then

        -- Attach the transparent hair/ears layer to the head pivot, not the button.
        -- The parent pivot moves the character while the outer circle stays fixed.
        local hairMotionParent = headPivot or restore
        local hairBasePosition = headPivot
            and UDim2.new(0.5, 0, 0.35, 0)
            or UDim2.fromScale(0.5, 0.5)
        local hairMotionArt = new("ImageLabel", {
            Name = "HairMotionArt",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = hairBasePosition,
            Size = UDim2.fromOffset(50, 50),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Image = MAWWW_FLOATING_HAIR_LAYER_IMAGE,
            ImageTransparency = 0,
            ScaleType = Enum.ScaleType.Fit,
            Active = false,
            Selectable = false,
            ZIndex = 1203,
        }, hairMotionParent)

        local bodyMotionArt = new("ImageLabel", {
            Name = "BodyMotionArt",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(50, 50),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Image = MAWWW_FLOATING_BODY_LAYER_IMAGE,
            ImageTransparency = 0,
            ScaleType = Enum.ScaleType.Fit,
            Active = false,
            Selectable = false,
            ZIndex = 1204,
        }, restore)

        local hairSwayPosition = headPivot
            and UDim2.new(0.5, 0.35, 0.35, -0.08)
            or UDim2.new(0.5, 0.35, 0.5, -0.08)
        local hairSway = TweenService:Create(
            hairMotionArt,
            TweenInfo.new(1.55, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
            { Position = hairSwayPosition, Rotation = 0.6 }
        )
        local bodySway = TweenService:Create(
            bodyMotionArt,
            TweenInfo.new(1.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
            { Position = UDim2.new(0.5, -0.08, 0.5, 0.22), Rotation = -0.35 }
        )
        hairSway:Play()
        bodySway:Play()
    end

    -- Smooth head shake: the ring and restore button are untouched; only the head pivot rotates.
    task.spawn(function()
        while restore.Parent and featureGui.Parent do
            if not restore.Visible or not headPivot or not headPivot.Parent then
                task.wait(0.2)
            else
                local leftShake = TweenService:Create(
                    headPivot,
                    TweenInfo.new(0.18, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                    { Rotation = -2.2 }
                )
                leftShake:Play()
                leftShake.Completed:Wait()
                if not restore.Parent or not featureGui.Parent then break end

                local rightShake = TweenService:Create(
                    headPivot,
                    TweenInfo.new(0.32, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                    { Rotation = 2.2 }
                )
                rightShake:Play()
                rightShake.Completed:Wait()
                if not restore.Parent or not featureGui.Parent then break end

                local settleShake = TweenService:Create(
                    headPivot,
                    TweenInfo.new(0.18, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                    { Rotation = 0 }
                )
                settleShake:Play()
                settleShake.Completed:Wait()
                task.wait(0.12)
            end
        end
        if headPivot and headPivot.Parent then headPivot.Rotation = 0 end
    end)

    -- Briefly switch to the closed-eye frame every 2 seconds, then reopen.
    task.spawn(function()
        while restoreArt.Parent and featureGui.Parent do
            task.wait(2)
            if not restoreArt.Parent or not featureGui.Parent then break end
            restoreArt.Image = MAWWW_FLOATING_LOGO_CLOSED_IMAGE
            if headMotionArt then headMotionArt.Image = MAWWW_FLOATING_HEAD_CLOSED_IMAGE or MAWWW_FLOATING_HEAD_OPEN_IMAGE end
            task.wait(0.12)
            if not restoreArt.Parent or not featureGui.Parent then break end
            restoreArt.Image = MAWWW_FLOATING_LOGO_IMAGE
            if headMotionArt then headMotionArt.Image = MAWWW_FLOATING_HEAD_OPEN_IMAGE end
        end
    end)

    -- The static backing frame plus transparent motion layers preserve the original portrait.

    minimizeButton.Activated:Connect(function()
        main.Visible = false
        restore.Visible = true
    end)

    -- Floating icon drag intentionally mirrors AP_MakeDraggablePanel so mobile/PC
    -- use the same proven press -> delta move -> release behavior as the parry panels.
    -- Keep the art passive so the parent ImageButton owns the single touch target.
    restoreArt.Active = false

    local restoreDragging = false
    local restoreMoved = false
    local restoreInput = nil
    local restoreStartPointer = nil
    local restoreStartPosition = nil
    local restoreDragThreshold = 3
    local restoreConnections = {}

    local function restoreOpenHub()
        if not restore.Visible then return end
        main.Visible = true
        restore.Visible = false
    end

    local function restoreFinishGesture(input)
        if not restoreDragging or not restoreInput or not input then return end
        local sameMouseRelease = restoreInput.UserInputType == Enum.UserInputType.MouseButton1
            and input.UserInputType == Enum.UserInputType.MouseButton1
        local sameTouchRelease = restoreInput.UserInputType == Enum.UserInputType.Touch
            and input.UserInputType == Enum.UserInputType.Touch
        if not sameMouseRelease and not sameTouchRelease then return end

        local shouldOpen = not restoreMoved
        restoreDragging = false
        restoreMoved = false
        restoreInput = nil
        restoreStartPointer = nil
        restoreStartPosition = nil

        if shouldOpen then restoreOpenHub() end
    end

    restore.InputBegan:Connect(function(input)
        if not restore.Visible or restoreDragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        restoreDragging = true
        restoreMoved = false
        restoreInput = input
        restoreStartPointer = input.Position
        restoreStartPosition = restore.Position
    end)

    restoreConnections[#restoreConnections + 1] = UserInputService.InputChanged:Connect(function(input)
        if not restoreDragging or not restoreStartPointer or not restoreStartPosition
            or not restore.Parent or not restore.Visible then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        -- Same absolute-from-start delta math as the parry status panels.
        local delta = input.Position - restoreStartPointer
        -- Move immediately, just like the parry panel; the threshold only decides
        -- whether release counts as a tap to restore the hub or as a drag.
        if delta.Magnitude >= restoreDragThreshold then
            restoreMoved = true
        end

        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(360, 720)
        local width, height = restore.AbsoluteSize.X, restore.AbsoluteSize.Y
        local x = (restoreStartPosition.X.Scale * viewport.X)
            + restoreStartPosition.X.Offset + delta.X
        local y = (restoreStartPosition.Y.Scale * viewport.Y)
            + restoreStartPosition.Y.Offset + delta.Y

        -- Clamp based on the actual hit-area so it can be dragged to the top edge.
        x = math.clamp(x, 0, math.max(0, viewport.X - width))
        y = math.clamp(y, 0, math.max(0, viewport.Y - height))
        restore.Position = UDim2.fromOffset(x, y)
    end)

    restoreConnections[#restoreConnections + 1] = UserInputService.InputEnded:Connect(function(input)
        restoreFinishGesture(input)
    end)

    restoreConnections[#restoreConnections + 1] = featureGui.Destroying:Connect(function()
        restoreDragging = false
        restoreInput = nil
        restoreStartPointer = nil
        restoreStartPosition = nil
        for _, connection in ipairs(restoreConnections) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(restoreConnections)
    end)

    local closeOverlay = new("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BackgroundTransparency = 0.42,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 500,
    }, featureGui)

    local confirm = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(330, 170),
        BackgroundColor3 = COLORS.Panel,
        BorderSizePixel = 0,
        ZIndex = 501,
    }, closeOverlay)
    corner(confirm, 15)
    stroke(confirm, COLORS.Stroke, 1, 0.12)

    makeLabel(confirm, "Close MAWWW HUB?", 17,
        UDim2.fromOffset(16, 13), UDim2.new(1, -32, 0, 28),
        Enum.Font.GothamBold, COLORS.Text, 502).TextXAlignment = Enum.TextXAlignment.Left

    makeLabel(confirm, "Are you sure you want to end the script?", 10,
        UDim2.fromOffset(16, 46), UDim2.new(1, -32, 0, 36),
        Enum.Font.Gotham, COLORS.SubText, 502).TextXAlignment = Enum.TextXAlignment.Left

    local noButton = new("TextButton", {
        Size = UDim2.fromOffset(125, 38),
        Position = UDim2.new(0, 16, 1, -54),
        BackgroundColor3 = COLORS.Panel3,
        BorderSizePixel = 0,
        Text = "NO",
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = COLORS.Text,
        AutoButtonColor = false,
        ZIndex = 502,
    }, confirm)
    corner(noButton, 9)

    local yesButton = new("TextButton", {
        Size = UDim2.fromOffset(125, 38),
        Position = UDim2.new(1, -141, 1, -54),
        BackgroundColor3 = COLORS.Red,
        BorderSizePixel = 0,
        Text = "YES, END",
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = COLORS.Text,
        AutoButtonColor = false,
        ZIndex = 502,
    }, confirm)
    corner(yesButton, 9)

    closeButton.Activated:Connect(function()
        closeOverlay.Visible = true
    end)

    noButton.Activated:Connect(function()
        closeOverlay.Visible = false
    end)

    yesButton.Activated:Connect(function()

        pcall(function()
            musicLoadToken = (musicLoadToken or 0) + 1
            musicLoading = false
            musicDisconnectAll()
            if musicSound and musicSound.Parent then
                musicSound:Stop()
                musicSound:Destroy()
            end
        end)

        pcall(function()
            featureGui:Destroy()
        end)
    end)

    local ctx = {
        featureGui = featureGui,
        page = page,
        pageTitle = pageTitle,
        pageSubtitle = pageSubtitle,
        buttons = buttons,
        scriptName = scriptName or "VILONCE DISTRICT",
    }

    infoPage.Name = "FeaturePage_INFORMATION"

    local adapter = __n3k_feature_makeAdapter(ctx)

    pcall(function()
        local pages = adapter.__MAWWW_GetSearchPages and adapter.__MAWWW_GetSearchPages()
        if type(pages) == "table" then
            pages["MUSIC"] = musicPage
        end
    end)

    do
        local originalWindow = adapter.Window
        adapter.Window = function(self, opts)
            local win = originalWindow(self, opts)
            return win
        end
    end

    local function clearSearchResults()
        for _, child in ipairs(searchResults:GetChildren()) do
            if child:IsA("TextButton") or child:IsA("TextLabel") then
                child:Destroy()
            end
        end
        searchResults.Visible = false
        searchResults.Size = UDim2.fromOffset(190, 0)
    end

    local function scrollToFeature(pageObject, holder)
        if not pageObject or not holder then return end

        task.spawn(function()
            local layout = pageObject:FindFirstChildOfClass("UIListLayout")
            local padding = pageObject:FindFirstChildOfClass("UIPadding")
            if not layout then return end

            if not pageObject.Visible then
                return
            end

            for _ = 1, 40 do
                task.wait(0.05)
                if holder.Parent == pageObject
                    and holder.AbsoluteSize.Y > 1
                    and layout.AbsoluteContentSize.Y > 1 then
                    break
                end
            end

            if holder.Parent ~= pageObject then return end

            local targetY = 0
            local topPad = 0
            if padding then
                topPad = padding.PaddingTop.Offset
            end
            targetY = topPad

            local siblings = {}
            for _, child in ipairs(pageObject:GetChildren()) do
                if child:IsA("GuiObject") and child ~= layout and child ~= padding then
                    table.insert(siblings, child)
                end
            end
            table.sort(siblings, function(a, b)
                if a.LayoutOrder ~= b.LayoutOrder then
                    return a.LayoutOrder < b.LayoutOrder
                end
                return a.Name < b.Name
            end)

            local listPadding = layout.Padding.Offset
            for _, child in ipairs(siblings) do
                if child == holder then
                    break
                end
                targetY = targetY + child.AbsoluteSize.Y + listPadding
            end

            local viewportH = pageObject.AbsoluteWindowSize.Y
            local canvasH = pageObject.AbsoluteCanvasSize.Y
            local maxY = math.max(0, canvasH - viewportH)
            targetY = math.clamp(targetY - 8, 0, maxY)

            pageObject.CanvasPosition = Vector2.new(0, targetY)

            task.wait(0.12)

            local finalY = topPad
            for _, child in ipairs(siblings) do
                if child == holder then
                    break
                end
                finalY = finalY + child.AbsoluteSize.Y + listPadding
            end

            canvasH = pageObject.AbsoluteCanvasSize.Y
            maxY = math.max(0, canvasH - pageObject.AbsoluteWindowSize.Y)
            finalY = math.clamp(finalY - 8, 0, maxY)
            pageObject.CanvasPosition = Vector2.new(0, finalY)
        end)
    end

    local function collectSearchResults(query)
        local results = {}
        local q = string.lower(tostring(query or "")):gsub("^%s+", ""):gsub("%s+$", "")
        if q == "" then
            return results
        end

        local pages = (type(adapter.__MAWWW_GetSearchPages) == "function" and adapter.__MAWWW_GetSearchPages()) or {}

        for pageKey, pageObject in pairs(pages) do
            if pageKey ~= "INFORMATION" then

                for _, sectionBox in ipairs(pageObject:GetChildren()) do
                    if sectionBox:IsA("Frame")
                        and sectionBox:GetAttribute("MAWWW_SearchSection") == true then

                        local sectionTitle = tostring(sectionBox:GetAttribute("MAWWW_SearchSectionTitle") or "")
                        local searchableParts = { sectionTitle }

                        for _, child in ipairs(sectionBox:GetDescendants()) do
                            if child:IsA("Frame")
                                and child:GetAttribute("MAWWW_SearchChild") == true then
                                table.insert(searchableParts, tostring(child:GetAttribute("MAWWW_FeatureTitle") or ""))
                                table.insert(searchableParts, tostring(child:GetAttribute("MAWWW_FeatureContent") or ""))
                            end
                        end

                        local haystack = string.lower(table.concat(searchableParts, " "))
                        local matchPos = string.find(haystack, q, 1, true)

                        if matchPos then
                            table.insert(results, {
                                holder = sectionBox,
                                page = pageObject,
                                pageKey = pageKey,
                                title = sectionTitle,
                                section = sectionTitle,
                                matchPos = matchPos,
                            })
                        end
                    end
                end
            end
        end

        table.sort(results, function(a, b)
            local at = string.lower(a.title)
            local bt = string.lower(b.title)
            local aq = string.find(at, q, 1, true) or 9999
            local bq = string.find(bt, q, 1, true) or 9999
            if aq ~= bq then return aq < bq end
            return at < bt
        end)

        return results
    end

    local function renderSearchResults(query)
        clearSearchResults()

        local results = collectSearchResults(query)
        if #results == 0 then
            if tostring(query or "") ~= "" then
                new("TextLabel", {
                    Name = "SearchEmpty",
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, -12, 0, 30),
                    LayoutOrder = 1,
                    Font = Enum.Font.Gotham,
                    Text = "No feature found",
                    TextColor3 = COLORS.Muted,
                    TextSize = 9,
                    TextXAlignment = Enum.TextXAlignment.Center,
                    ZIndex = 121,
                }, searchResults)

                searchResults.Size = UDim2.fromOffset(190, 44)
                searchResults.Visible = true
            end
            return
        end

        local maxResults = math.min(#results, 7)

        for i = 1, maxResults do
            local result = results[i]

            local row = new("TextButton", {
                Name = "SearchResult_" .. tostring(i),
                Size = UDim2.new(1, 0, 0, 34),
                LayoutOrder = i,
                BackgroundColor3 = COLORS.Panel2,
                BackgroundTransparency = 0.08,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                ZIndex = 122,
            }, searchResults)
            corner(row, 8)

            new("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(9, 3),
                Size = UDim2.new(1, -18, 0, 16),
                Font = Enum.Font.GothamSemibold,
                Text = result.title,
                TextColor3 = COLORS.Text,
                TextSize = 8,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 123,
            }, row)

            new("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(9, 18),
                Size = UDim2.new(1, -18, 0, 12),
                Font = Enum.Font.Gotham,
                Text = result.pageKey .. " • Main Feature",
                TextColor3 = COLORS.Muted,
                TextSize = 7,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 123,
            }, row)

            row.MouseEnter:Connect(function()
                row.BackgroundColor3 = Color3.fromRGB(24, 91, 130)
            end)

            row.MouseLeave:Connect(function()
                row.BackgroundColor3 = COLORS.Panel2
            end)

            row.Activated:Connect(function()
                local selectedPage = result.page
                if type(adapter.__MAWWW_ShowSearchTab) == "function" then
                    selectedPage = adapter.__MAWWW_ShowSearchTab(result.pageKey) or result.page
                end

                task.defer(function()
                    task.wait()
                    scrollToFeature(selectedPage, result.holder)
                end)

                featureSearch.Text = ""
                clearSearchResults()
            end)
        end

        local rowHeight = 34
        local totalHeight = 12 + (maxResults * rowHeight) + ((maxResults - 1) * 4)
        searchResults.Size = UDim2.fromOffset(190, math.min(totalHeight, 286))
        searchResults.Visible = true
    end

    featureSearch:GetPropertyChangedSignal("Text"):Connect(function()
        renderSearchResults(featureSearch.Text)
    end)

    featureSearch.Focused:Connect(function()
        if featureSearch.Text ~= "" then
            renderSearchResults(featureSearch.Text)
        end
    end)

    featureSearch.FocusLost:Connect(function()
        task.delay(0.12, function()
            if featureSearch.Text == "" then
                clearSearchResults()
            end
        end)
    end)

    __MAWWW_UI_ADAPTER = adapter

    __MAWWW_FEATURE_RUNTIME_STARTED = true
    __MAWWW_FEATURE_RUNTIME_RUNNING = true

    task.spawn(function()
        local ok, err = pcall(function()
            __MAWWW_START()
        end)

        __MAWWW_FEATURE_RUNTIME_RUNNING = false

        if not ok then
            if __MAWWW_EXEC_GUARD then
                __MAWWW_EXEC_GUARD.Active = false
                __MAWWW_EXEC_GUARD.Phase = "failed"
            end
            warn("[MAWWW] Feature runtime error:", err)
            __n3k_feature_notify(
                featureGui,
                "Feature Runtime",
                "Runtime stopped safely. Check executor/game compatibility.",
                4
            )
        end
    end)

    showPage("INFORMATION")
end

